Ceviri.ekle("hy","olay",{
"OLAYLAR_EK5:1704-01-01:0":{"b": ["Բաղդադում քյոլեմենների (մամլուքների) կառավարման սկիզբը", "abe52618"], "d": ["Վրացական ծագմամբ Հասան փաշայի՝ Բաղդադի կուսակալ նշանակվելով Իրաքում սկսվեց մի շրջան, երբ կենտրոնից նշանակվող կուսակալների փոխարեն իշխում էր սեփական ստրուկներից դաստիարակված կառավարող խավը։ Սուլեյման փաշայի՝ 1749 թվականի կուսակալությամբ համակարգն իսպառ արմատավորվեց, և Բարձր դուռն այլևս ստիպված էր նշանակել ոչ թե իր ուզած անձին, այլ ազդեցությունն իր ձեռքը վերցրած քյոլեմեններից մեկին։ Այս կիսաինքնավար կառույցը թեև օգտակար եղավ իրանական սահմանի պաշտպանության գործում, մեկուկես դար շարունակ թուլացրեց Իրաքի նկատմամբ կենտրոնական իշխանության վերահսկողությունը։", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["Թունիսում Հուսեյնյան հարստության հիմնումը", "cb1a98f9"], "d": ["Ալժիրյան ուժերի կողմից Թունիսի ներխուժման հետևանքով առաջացած իշխանական դատարկության պայմաններում թուրքական ծագմամբ սիփահիների աղա Հուսեյն բ. Ալին իր ձեռքը վերցրեց բեյությունը և, հայտնելով իր հավատարմությունը օսմանյան փադիշահին, ձեռք բերեց լեգիտիմություն։ Նրա հիմնած հարստությունը Թունիսը կառավարեց 1705-1735 և 1756-1957 թվականներին. օջախային կառավարմանը փոխարինեց հորից որդի անցնող բեյական կարգը։ Այսպիսով ծնվեց արևմտյան օջախներում կենտրոնին կապված, բայց փաստացի ինքնավար դինաստիական կառույցների առաջին օրինակը։", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["Օրանի (Վահրան) և Մերս էլ-Քեբիրի վերցնելը իսպանացիներից", "b67ce06a"], "d": ["Ալժիրի օջախի բեյլերբեյի ուժերը երկարատև պաշարումից հետո գրավեցին երկու դար իսպանական կայազորի ձեռքում գտնվող Օրանը և նրա նավահանգիստ Մերս էլ-Քեբիրը։ Սա Արևմտյան Միջերկրականում օսմանյան հովանավորության ներքո գտնվող արևմտյան օջախների՝ Իսպանիայի դեմ տարած ամենամեծ հաջողությունն էր և ապահովեց Ալժիրի արևմտյան թևը։ Քաղաքը 1732 թվականին կրկին ենթարկվելու էր իսպանական օկուպացիայի և վերջնականապես հետ վերցվելու էր միայն 1792 թվականին։", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["Պրուտի պայմանագիրը. Ազովի և Թայգանի հետ վերցնելը", "bac5d2a1"], "d": ["Պրուտ գետի մոտ շրջապատված ռուսական բանակի հանձնվելով ստորագրված յոթ հոդվածից բաղկացած պայմանագիրը սահմանում էր, որ Ազովի բերդը՝ իր հողերով և ռազմամթերքով, վերադարձվում է Օսմանյան պետությանը։ Թայգանի, Կամենկայի և Ենիկալեի ամրությունները քանդվելու էին, և կողմերը այդ շրջաններում նոր բերդեր չէին կառուցելու։ Փլուզվեց նավատորմի և հենակետերի այն համակարգը, որը Պյոտր I-ը տասնվեց տարի շարունակ կառուցել էր Վորոնեժում և Ազովում. Ռուսաստանի ելքը դեպի Սև ծով ուշացավ մոտ հիսուն տարով։", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["Տրիպոլիտանիայում Կարամանլի հարստության հիմնումը", "e1105d4a"], "d": ["Օջախի աղաների մրցակցությունից հոգնած Տրիպոլիտանիայում հեծելազորի սպա Ահմեդ Կարամանլին իր ձեռքը վերցրեց կառավարումը և Ստամբուլից ստացած բեյլերբեյության բերաթով պաշտոնականացրեց իր դիրքը։ Ահմեդ փաշայի, նրա որդի Մեհմեդ փաշայի և թոռ Յուսուֆ փաշայի միջոցով ծնվեց 1711-1835 թվականներին տևած հարստություն. առաջացավ կիսաանկախ կառույց, որն ստեղծել էր սեփական նավատորմ և ուղղակի պայմանագրեր էր ստորագրում եվրոպական պետությունների հետ։ Այս շրջանն ավարտվելու էր միայն 1835 թվականին՝ էյալեթը ուղղակիորեն կենտրոնին ենթարկելով։", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["Էդիրնեի պայմանագիրը Ռուսաստանի հետ", "14901a70"], "d": ["Պրուտում տրված խոստումները չկատարելու պատճառով ևս երկու անգամ պատերազմ էր հայտարարվել. վերջապես, երբ ռուսներն ընդունեցին պարտավորությունները, Էդիրնեում ստորագրվեց մնայուն հաշտություն։ Պայմանագիրը հաստատեց Պրուտի պայմանները. Ռուսաստանը չէր միջամտելու Լեհաստանի գործերին, հեռանալու էր կազակական հողերից և չէր խոչընդոտելու Շվեդիայի թագավոր Կարլոս XII-ի (Երկաթագլուխ Շառլ) վերադարձը իր երկիր։ Հյուսիսային ճակատի այսպիսով փակվելը Օսմանյան պետությանը հնարավորություն տվեց դեմքը շրջել դեպի Մորեայի և Վենետիկի ճակատ։ Նույն ամսաթվին միացած այլ վայրեր՝ Խոտին։", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["Պատերազմի հայտարարում Վենետիկին. Մորեայի արշավանքի նախապատրաստությունը", "d970b122"], "d": ["Դիվանում պատերազմի որոշում կայացվեց՝ պատճառաբանելով, որ Վենետիկը աջակցում է Չեռնոգորիայի ապստամբներին, բռնագրավում է օսմանյան առևտրական նավերը և ծանր հարկերով ճնշում է Կառլովիցով ստացած Մորեան։ Մեծ վեզիր Սիլահդար Դամադ Ալի փաշայի նախապատրաստած արշավանքը հաջորդ տարի ավարտվելու էր ամբողջ Մորեա թերակղզու հետ վերցնելով՝ հարյուր օրից էլ պակաս ժամանակում։ Սակայն այս հաջողությունը շարժման մեջ էր դնելու Ավստրիային և 1716 թվականին դուռ էր բացելու շատ ավելի ծանր պատերազմի։", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["Տինոսը (Իստենդիլ). Վենետիկի էգեյան վերջին կղզու հանձնումը", "4abec891"], "d": ["Մորեայի արշավանքի դուրս եկած նավատորմը ճանապարհին խարիսխ գցեց Տինոսի դիմաց՝ Էգեյան ծովում Վենետիկի ձեռքում մնացած միակ կղզու։ Այն կղզին, որը, թեև Նաքսոսի դքսությունն ընկել էր 1566 թվականին, իր լատին բնակչության շնորհիվ ևս հարյուր հիսուն տարի կրել էր Վենետիկի դրոշը, կարճ պաշարումից հետո առանց արյունահեղության հանձնվեց։ Այսպիսով Էգեյան ծովում Վենետիկի վերջին հետքը ջնջվեց, և ծովն ամբողջությամբ վերածվեց օսմանյան ներքին ծովի։", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["Նավպլիոնի նվաճումը. Մորեայի առանցքային բերդը", "62a5808a"], "d": ["Վենետիկի՝ Մորեայի մայրաքաղաքն ու ամենահզոր ամրությունը եղած Նավպլիոնն ընկավ Պալամիդի ամրությունը ինօրյա ռմբակոծությունից հետո գրավելով։ Բերդի այսքան հեշտ վերցնելը կոտրեց թերակղզու մնացած մասի դիմադրությունը։ Կառլովիցով կորցված Մորեայի հետ վերցնելը փաստացի ավարտվեց այստեղ։ Նույն ամսաթվին Ատլասում Վենետիկից Օսմանյան պետությանն անցած այլ բնակավայր՝ Արգոս — հետևում է Նավպլիոնի գլխավոր կենտրոնի շղթային (TDV anabolu; հայտարարված մոտավորություն)։", "8467e05c"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["Մոդոնի հանձնումը", "43faa909"], "d": ["Նավպլիոնի անկումից հետո Մորեայի հարավարևմտյան ծայրի Մոդոնի բերդը, ցամաքից բանակի, ծովից նավատորմի կողմից պաշարվելով, շուտով հանձնվեց։ Այս նավահանգիստը, որը Վենետիկը երկու հարյուր տարի օգտագործել էր իր արևելամիջերկրածովյան երթերում, նավերի համար ջուր և պարեն վերցնելու պարտադիր կանգառ էր։ Դրա կորուստը վերջ տվեց վենետիկյան նավատորմի մանևրելու կարողությանը Էգեյան ծովում։", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["Կորոնի հանձնումը. Մորեայի արշավանքի ավարտը", "e4b9c8a4"], "d": ["Մեսենիայի ծոցի մուտքը հսկող Կորոնի բերդի հանձնումով Մորեա թերակղզում վենետիկյան կառավարումը լիովին ավարտվեց։ Կառլովիցով կորցված թերակղզին ամբողջությամբ հետ վերցվեց արշավանքի սկսվելուց ընդամենը երեք ամիս անց։ Նույն արշավանքի շարունակության մեջ 1715 թվականի սեպտեմբերին Վենետիկից վերցվեց նաև Հոնիական ծովի Այա Մավրա (Լեֆկադա) կղզին։ Այս արագությունը Վենետիկին ստիպեց Ավստրիային ներքաշել պատերազմի մեջ, և երեք տարի անց բացվեց դեպի Պոժարևաց (Պասարովից) տանող ճանապարհը։", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["Կիթերա կղզու (Չուհա) վերցնելը", "494de6c6"], "d": ["Մորեայի հարավային ծայրի Կիթերա կղզին թերակղզու գրավումն ամբողջացնելուց հետո նավատորմը հանձնումով վերցրեց։ Հոնիական և Էգեյան ծովերի միջև անցումը հսկող կղզին այն առաջապահ կետն էր, որը Վենետիկն օգտագործում էր այս ջրերը վերահսկելու համար։ Սակայն այն ձեռքում չմնաց որպես օսմանյան կղզի. երեք տարի անց Պոժարևացով այն վերադարձվեց Վենետիկին։", "42162c0d"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["Ավստրիան դաշինք կնքեց Վենետիկի հետ. 1716-1718 թվականների օսմանա-ավստրիական պատերազմի դուռը", "99511ca2"], "d": ["Օսմանյան պետության կողմից Մորեան Վենետիկից հետ վերցնելուց հետո Ավստրիան, առաջ քաշելով, թե խախտվել է Կառլովիցի պայմանագիրը, դաշինքի պայմանագիր ստորագրեց Վենետիկի հետ. արքայազն Եվգենիոսը մեծ վեզիրին գրած նամակում պահանջեց Վենետիկից վերցված վայրերի վերադարձը։ Դավութփաշայի ճամբարում կայացած խորհրդակցության ժամանակ մեծ վեզիր Ալի փաշայի ճնշմամբ Ավստրիային պատերազմ հայտարարվեց, և դրա համար շեյխ ուլ-իսլամից ֆեթվա ստացվեց։", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["Մեծ վեզիր Ալի փաշան դուրս եկավ ավստրիական արշավանքի", "2fbdce42"], "d": ["Ավստրիային պատերազմ հայտարարելուց հետո սերդարը (գերագույն հրամանատար) Ալի փաշան ավելի քան 100.000-անոց բանակով դուրս եկավ ավստրիական արշավանքի. նավատորմը նույն ամռանը ուղղվեց դեպի Կորֆու։ Բանակը Բելգրադից առաջ էր շարժվելու դեպի Պետրովարադին, և օգոստոսի սկզբի ջախջախման ժամանակ մեծ վեզիրը զոհվելու էր։", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["Պետրովարադինի ջախջախումը. Դամադ Ալի փաշայի զոհվելը", "265c1d81"], "d": ["Բելգրադի վրայով Դանուբն անցած օսմանյան բանակը Պետրովարադինի մոտ հանդիպեց արքայազն Եվգենիոսի հրամանատարությամբ ավստրիական ուժերին. առաջին հարվածի ժամանակ ենիչերիների գրոհը, թեև ճնշում գործադրեց թշնամու խրամատների վրա, հեծելազորի թևի փլուզմամբ շարքերը ցրվեցին։ Մեծ վեզիր Սիլահդար Դամադ Ալի փաշան ճակատից խփվելով զոհվեց, ճամբարն ու հրետանային հանդերձանքը ամբողջությամբ անցան թշնամու ձեռքը։ Այս ջախջախումը, որը օսմանյան տարեգրությունները հիշատակում են որպես «Վարադինի տարի», այն շղթայի առաջին օղակն էր, որը տանում էր Տեմեշվարի, իսկ հաջորդ տարի՝ Բելգրադի կորստին։", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["Կորֆուի պաշարման անհաջող ավարտը", "b2aa7011"], "d": ["Մորեայի սերասքեր Կարա Մուստաֆա փաշան ցամաքից, իսկ կապուդան փաշա Ջանըմ Խոջա Մեհմեդ փաշան նավատորմով ծովից հարձակվեցին Կորֆուի վրա. կղզին Վենետիկի առանցքային հենակետն էր Ադրիատիկում։ Սակայն բերդի ծայրահեղ հզոր ամրությունները, վենետիկյան նավատորմի բերած օժանդակ ուժերը և Դանուբի ճակատից եկող պարտության լուրերը հանգեցրին պաշարման հանմանը։ Կորֆուն չվերցնելը մարեց Մորեայի վերանվաճումով բարձրացած ոգևորությունը և պատերազմի ծանրության կենտրոնը տեղափոխեց Հունգարիա։", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["Տեմեշվարի (Տիմիշոարա) կորուստը հօգուտ Ավստրիայի", "27fe1365"], "d": ["Պետրովարադինի ջախջախումից հետո արքայազն Եվգենիոսը ուղղակիորեն առաջ շարժվեց դեպի Տեմեշվար, և քառասուն օրից ավելի տևած պաշարումից հետո բերդը հանձնվեց պայմանագրով։ Այսպիսով ձեռքից դուրս եկավ 1552 թվականին Կանունիի օրոք նվաճված այն քաղաքը, որը 164 տարի շարունակ որպես բեյլերբեյության կենտրոն համարվում էր Հունգարիայի պաշտպանության արևելյան սյունը։ Տեմեշվարի անկումով Բանատի ամբողջ շրջանն անցավ Ավստրիային, և օսմանյան սահմանը հետ մղվեց Դանուբից հարավ։ Նույն ամսաթվին Ատլասում Օսմանյան պետությունից Հաբսբուրգներին անցած այլ բնակավայրեր՝ Csákóvár, Facset և Կարանշեբեշ (Caransebeş) — Տեմեշվարի էյալեթի փոխանցման հետ (TDV timisvar; բնակավայրերի մակարդակով օրը աղբյուրում նշված չէ, գլխավոր կենտրոնի շղթա, հայտարարված մոտավորություն)։", "a1408ad1"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["Հարամի (Ենի Պալանկա) բերդի հանձնումը Ավստրիային. Բանատի դանուբյան ափը ձեռքից դուրս եկավ", "38ee4c6d"], "d": ["Տեմեշվարի անկումից հետո Բանատի մնացած մասը վերցնելու հանձնարարություն ստացած ավստրիական հեծելազորի գեներալ Մերսին նոյեմբերի 14-ին շարժվեց Դանուբի ափի Հարամի (Ենի Պալանկա) վրա. նոյեմբերի 16-ին, երբ նա հասավ բերդ, 200 հոգանոց օսմանյան կայազորը սպիտակ դրոշ բարձրացրեց և ազատ հեռանալու պայմանով հանձնվեց։ Այսպիսով 1552 թվականից օսմանյան ձեռքում գտնվող Հարավային Բանատի դանուբյան գիծը ևս անցավ Ավստրիային։ Նույն ամսաթվին Ատլասում Օսմանյան պետությունից Հաբսբուրգներին անցած այլ բնակավայր՝ Վերշեց — հետևում է Հարամի գլխավոր կենտրոնի շղթային (Bánlaky 0019/1703; հայտարարված մոտավորություն)։", "5b54ecb0"]},
"OLAYLAR_EK5:1718-07-21:0":{"b": ["Պոժարևացի (Պասարովիցի) պայմանագիրը. Մորեան շահվեց, Բելգրադը և Բանատը կորցվեցին", "d46aa216"], "d": ["Մորեան հետ էր վերցվել Վենետիկից, սակայն պատերազմի մեջ մտած Ավստրիան Պետրովարադինում և Բելգրադում տարած հաղթանակներով բանակցությունների սեղան նստեց առավել ուժեղ դիրքով։ Անգլիայի և Հոլանդիայի միջնորդությամբ ստորագրված պայմանագիրը Մորեան թողեց Օսմանյան պետությանը, փոխարենը Բելգրադի հետ Հյուսիսային Սերբիան, Բանատը և Փոքր Վալախիան զիջվեցին Ավստրիային. TDV-ի ձևակերպմամբ՝ «Հյուսիսային Բոսնիան ամբողջությամբ թողնվել է Ավստրիային»։ Սավայի երկայնքով գտնվող բերդերը, ինչպիսիք են Բոսանսկա Դուբիցան և Բոսանսկի Բրոդը, քարտեզի վրա այս օրվանից անցնում են Ավստրիային (ճշգրիտ սահմանը հանձնակատարները գծեցին մեկ առ մեկ, TDV-ն այս բերդերը անուններով չի թվարկում). իսկ Վենետիկը պահպանեց Հոնիական ափի իր դիրքերը, ինչպիսիք են Պրևեզան և Կիթերան։ Նույն օրը ստորագրված առևտրային ահիդնամեով ավստրիական ապրանքներից վերցվող մաքսատուրքը հինգ տոկոսից իջեցվեց երեքի։ Պայմանագիրը, արձանագրելով Օսմանյան պետության նահանջը Կենտրոնական Եվրոպայից, բացած քսանյոթամյա խաղաղությամբ ստեղծեց Կակաչների դարաշրջանի (1718-1730) հիմքը. Նևշեհիրլի Դամադ Իբրահիմ փաշայի կառավարման օրոք առաջին օսմանյան տպարանը (1727, Իբրահիմ Մյութեֆերիկա), թարգմանչական հանձնաժողովները, ծաղկի պատվաստման դիտարկումները և պալատական-մշակութային նոր կյանքը այս խաղաղ տարիների արդյունքն են։ Նույն օրը Ատլասում ձեռքից ձեռք անցած այլ բնակավայրեր՝ Կրայովա (Craiova), Ռիմնիկ (Râmnicu Vâlcea) և Տուրնու Սևերին (Փոքր Վալախիա/Օլտենիա, Օսմանյան պետությունից Ավստրիային), ինչպես նաև Այա Մավրա (Լեֆկադա) (Օսմանյան պետությունից Վենետիկին. TDV ayamavra. 1718 թվականին Պոժարևացի պայմանագրով կղզին զիջվեց Վենետիկին)։ Փոքր Վալախիայում Տիրգու Ժիուն ևս անցնում է Ավստրիային. Վոնիցան (Voniçe, TDV pasarofca-antlasmasi) և Կիթերա կղզին (TDV cuka-adasi. Պոժարևացի 3-րդ հոդվածը) անցնում են Վենետիկին։", "ec4430bf"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["Արևելյան արշավանք. Թիֆլիսի վերցնելը և իրանական պատերազմի սկիզբը", "78343dc2"], "d": ["Աֆղանական ներխուժմամբ Սեֆյան պետության փլուզման և Ռուսաստանի՝ Կասպից ծովի ափերին իջնելու պայմաններում Օսմանյան պետությունը, որպեսզի առաջացած դատարկությունը ամբողջությամբ չմնար ռուսական ազդեցությանը, զորք ուղարկեց դեպի արևելք։ Թիֆլիսը գրավելով՝ Վրաստանը ենթարկվեց օսմանյան կառավարմանը. այնուհետև առաջխաղացումը շարունակվեց Գանձակի, Երևանի և Նախիջևանի ուղղությամբ։ Կակաչների դարաշրջանի խաղաղ տեսքի հետևում իրականացված այս արշավանքը սկիզբն էր արևելյան երկարատև արկածախնդրության, որը տևելու էր տասներեք տարի և ավարտվելու էր բոլոր ձեռք բերված վայրերի վերադարձմամբ։", "5c412d91"]},
"OLAYLAR_EK5:1723-08-01:0":{"b": ["1723 թվականի իրանական արշավանքը. մուտքը Շիրվան և Վրաստան", "c81189fc"], "d": ["Աֆղանական ներխուժմամբ Սեֆյան պետության փլուզումից հետո, Ռուսաստանի՝ Կասպից ծովի ափեր իջնելը կանխելու պատճառաբանությամբ, արևելյան ուղղությամբ արշավանք սկսվեց։ Էրզրումի բանակը Վրաստանի վրայով մտավ Թիֆլիս, իսկ Շիրվանի թևը՝ Շամախի, հետ վերցնելով հարյուր երեսուն տարի առաջ կորցրած հողերը։ Այս արշավանքը դարձավ Օսմանյան պետության վերջին խոշոր առաջխաղացումը Կովկասում։", "9f84acd9"]},
"OLAYLAR_EK5:1723-10-01:0":{"b": ["Քերմանշահի վերցնելը. Զագրոսի դարպասը", "ad14799f"], "d": ["Բաղդադի բանակը, հաղթահարելով Զագրոսի լեռնանցքները, գրավեց Իրանի արևմտյան դարպասը համարվող Քերմանշահը։ Քաղաքը գտնվում էր Բաղդադից Սպահան գնացող քարավանների և զորքի ճանապարհի վրա, և դրա վերցնելը ապահովում էր Իրաքի էյալեթի արևելյան անվտանգությունը։ Այս առաջխաղացումը ցրվող սեֆյան երկրում Օսմանյան պետության և Ռուսաստանի միջև սկսեց բաժանման մրցավազք։", "65dba49c"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["Ստամբուլի բաժանման պայմանագիրը (մուկասեմենամե). Իրանի բաժանումը Ռուսաստանի հետ", "fce8eec2"], "d": ["Փլուզվող սեֆյան երկրի նկատմամբ Օսմանյան պետության և Ռուսաստանի բախումը կանխելու նպատակով ֆրանսիական դեսպանի միջնորդությամբ ստորագրվեց բաժանման պայմանագիր։ Կասպից ծովի արևմտյան և հարավային ափերը թողնվեցին Ռուսաստանին, իսկ Վրաստանը, Շիրվանը, Ադրբեջանը և Արևմտյան Իրանի քաղաքները՝ Օսմանյան պետությանը։ Թղթի վրա մեծ ձեռքբերում թվացող այս բաժանումը շուտով՝ Նադիր շահի վերելքով, փաստացի անվավեր էր դառնալու։ Ըստ պայմանագրի՝ Շիրվանի բերրի հողերը, ինչպիսիք են Շաբրանը և Մուշքյուրը, թողնվեցին ռուսական կողմին (Çaycıoğlu, DergiPark)։", "7b0b411b"]},
"OLAYLAR_EK5:1724-08-11:0":{"b": ["Նախիջևանի վերցնելը", "bdf14d0a"], "d": ["Արաքսի երկայնքով առաջ շարժվող օսմանյան ուժերը վերցրին Նախիջևանը և Օրդուբադը. Ջուղան ևս միացվեց Նախիջևանի լիվային։ Քաղաքը, որպես Իրանի հյուսիսարևմտյան դարպաս, ենթարկվեց նորաստեղծ Երևանի էյալեթին։ Այսպիսով օսմանյան սահմանը կրկին հասավ Կանունիի ժամանակաշրջանի ամենաարևելյան գծին։", "9e602879"]},
"OLAYLAR_EK5:1724-08-31:0":{"b": ["Համադանի նվաճումը", "e1339a97"], "d": ["Քերմանշահից դեպի արևելք շարժվող բանակը երկար պաշարումից հետո վերցրեց իրանական սարահարթի արևմտյան շեմին գտնվող Համադանը։ Քաղաքը Սպահան տանող ճանապարհի վերջին մեծ կանգառն էր, որը օսմանյան բանակների՝ Իրաքեյնի արշավանքից ի վեր հասած ամենաարևելյան կետն էր։ Նույն տարի Ռուսաստանի հետ ստորագրված Ստամբուլի բաժանման համաձայնագիրը (մուկավելենամե) թղթին հանձնեց ցրվող Իրանի բաժանումը Օսմանյան պետության և Ռուսաստանի միջև։", "81552031"]},
"OLAYLAR_EK5:1724-10-03:0":{"b": ["Երևանի վերանվաճումը", "88acabef"], "d": ["Իննսուն օր տևած ծանր պաշարումից հետո Արաքսի հովտի առանցքային բերդ Երևանը կրկին անցավ օսմանյան կառավարման տակ։ 1583 թվականին կառուցված և 1604 թվականին կորցված բերդն այս անգամ ամրացվեց ավելի ուժեղ կայազորով։ Պաշարման երկարատևությունը ցույց էր տալիս, որ օսմանյան բանակն այլևս հեշտությամբ առաջ չէր շարժվում։ Կարպիի (Էջմիածին՝ Ուչքիլիսե), Շարուրի, Մակուի և Շիրակի (Շյուրեգել) նահիյեները ևս ենթարկվեցին Երևանի էյալեթին։", "a989b1eb"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["Թավրիզի գրավումը. Ադրբեջանի զավթումը", "e502a4f7"], "d": ["Մեկ տարի առաջվա անհաջող փորձից հետո կրկին պաշարված Թավրիզը, փողոց առ փողոց ընթացած ծանր մարտից հետո, հանձնվեց օսմանյան բանակին։ Թավրիզի էյալեթին ենթակա Մարանդը, Մարաղան և Սովուքբուլաքը (Մահաբադ) ևս անցան օսմանյան կառավարման տակ։ Նույն տարի վերցնելով նաև Լոռին, Գանձակը, Արդաբիլը և Խորամաբադը՝ Ստամբուլի բաժանման պայմանագրով Օսմանյան պետության բաժին ընկած շրջանները փաստացի գրավվեցին։ Արևելքում ձեռք բերված այս ընդարձակությունը Ֆերհադ փաշայի պայմանագրի ժամանակից հետո ամենաառաջավոր սահմանն էր. սակայն այն պահելը ծանր բեռ դրեց բանակի և գանձարանի վրա։", "e0953563"]},
"OLAYLAR_EK5:1725-09-04:0":{"b": ["Գանձակի նվաճումը. կովկասյան արշավանքի ավարտը", "875bca7a"], "d": ["Կովկասյան գործողության վերջին թիրախ Գանձակը հանձնումով վերցվեց որպես Կուրի և Արաքսի միջև գտնվող Ղարաբաղի կենտրոն։ Շիրվան-Երևան-Նախիջևան-Գանձակ գիծն ամբողջացնելով՝ Օսմանյան պետությունը Կովկասում հասավ 1590 թվականի իր ընդարձակությանը։ Սակայն այս ձեռքբերումը կարճատև եղավ. Նադիր շահի վերելքը տասը տարում հետ էր վերցնելու ամբողջ շրջանը։", "265db7e0"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["Համադանի պայմանագիրը. Արևմտյան Իրանի միացումը Օսմանյան պետությանը", "94a29dc3"], "d": ["Աֆղան տիրակալ Աշրաֆ շահի հետ ստորագրված պայմանագրով ավարտվեց չորս տարի տևած պատերազմը, և իրավականորեն ճանաչվեցին Օսմանյան պետության զբաղեցրած Արևմտյան Իրանի տարածքները։ Փոխարենը Աշրաֆ շահը ընդունեց օսմանյան փադիշահի խալիֆայությունը և ստանձնեց, որ Իրանում խուտբան կկարդացվի փադիշահի անունով։ Այս դիվանագիտական հաղթանակը կարճատև եղավ. 1730 թվականին Նադիր շահի սկսած հակահարձակումը մի քանի տարում սրբելու-տանելու էր պայմանագրի ձեռքբերումները։", "fd0174b9"]},
"OLAYLAR_EK5:1731-01-01:0":{"b": ["Հեքիմօղլու Ալի փաշան գրավեց Ուրմիան", "eac7f64d"], "d": ["Իրանական արշավանքի ժամանակ Հեքիմօղլու Ալի փաշան նախ գրավեց Ուրմիան (Ռումիյե), ապա 1731 թ. նոյեմբերի 15-ին՝ օսմանցիների համար դատարկված Թավրիզը։ TDV-ն Ուրմիայի գրավման օրը չի նշում. հայտնի է միայն տարին և այն, որ դա տեղի է ունեցել Թավրիզից առաջ։", "f99d74f9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["Ահմեդ փաշայի պայմանագիրը. Արևմտյան Իրանի մեծ մասի վերադարձը", "590d839f"], "d": ["Մալայերում Նադիր շահի տարած հաղթանակից և իրար հաջորդող իրանական հարձակումներից հետո Բաղդադի կուսակալ Ահմեդ փաշան, առանց կենտրոնի հետ խորհրդակցելու, ստորագրեց հաշտության տեքստ։ Ըստ պայմանագրի՝ Արաքս գետն ընդունվեց որպես սահման. Արևմտյան Իրանի քաղաքները՝ Համադանը, Քերմանշահը, Արդելանը, Արդաբիլը և Թավրիզը, վերադարձվեցին Իրանին, իսկ Գանձակն ու Թիֆլիսը մնացին Օսմանյան պետությանը։ Ստամբուլում բացասաբար ընդունված այս տեքստը Նադիր շահը ևս անբավարար համարեց, և դեռ 1732 թվականը չլրացած պատերազմը կրկին բորբոքվեց։ Ատլասը Խոյի շղթային հետևող Կոթուրը ևս այս օրը համարում է Օսմանյան պետությունից Սեֆյաններին անցած (TDV hoy; Կոթուրին հատուկ օրը աղբյուրում նշված չէ — հայտարարված մոտավորություն)։", "fdaa1e6f"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["Օրանի (Վահրան) վերստին կորուստը հօգուտ Իսպանիայի", "20485027"], "d": ["Իսպանիայի թագավոր Ֆիլիպ V-ի ուղարկած մեծ դեսանտային նավատորմը կոմս Մոնտեմարի հրամանատարությամբ հասավ Օրանի մատույցներ և, ջախջախելով Ալժիրի օջախի ուժերը, հետ վերցրեց քաղաքը։ Քսանչորս տարի առաջ նվաճված նավահանգիստը վաթսուն տարի կրկին մնալու էր իսպանական կայազորի ձեռքում։ Արևմտյան Միջերկրականում արևմտյան օջախների ուժի սահմանները ցույց տված այս կորուստը հնարավոր եղավ փոխհատուցել միայն 1792 թվականին՝ Օրանի վերջնական նվաճումով։", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["Խումբարաջի օջախի բարեփոխումը եվրոպական եղանակով և Խումբարահանեի հիմնումը", "d980cf2a"], "d": ["Օսմանյան ծառայության անցած ֆրանսիական ծագմամբ Խումբարաջի Ահմեդ փաշան, մեծ վեզիր Հեքիմօղլու Ալի փաշայի աջակցությամբ, խումբարաջիների (ռումբակիր հրետանավորների) օջախը դարձրեց ռոճիկ ստացող և եվրոպական ձևով կազմակերպված զորամաս։ Բոսնիայից հավաքագրված երեք հարյուր զինվորի տրվեց հաշվարկի և երկրաչափության վրա հիմնված կանոնավոր կրթություն. կազմակերպության, հանդերձանքի և կենսաթոշակի համար պատրաստվեցին նոր կանոնադրություններ, ժամանակակից տեխնիկայով արտադրվեցին հարյուր խումբարա թնդանոթ և հիսուն հազար խումբարա (ռումբ)։ Խումբարահանեն, ուր երկրաչափություն էր դասավանդվում, համարվում է Օսմանյան պետությունում ժամանակակից ռազմաինժեներական կրթության առաջին միջուկը։", "181b7161"]},
"OLAYLAR_EK5:1736-06-24:0":{"b": ["Ահմեդ III-ի մահը", "455f7fba"], "d": ["1730 թ. Պատրոնա Հալիլի ապստամբությամբ գահընկեց արված Ահմեդ III-ը կյանքի վերջին վեց տարիներն անցկացրեց Թոփքափը պալատի՝ գահընկեց փադիշահների համար հատկացված բաժնում և մահացավ վաթսուներեք տարեկանում։ Թաղվեց Բահչեքափըում՝ Ենիջամիի մոտ գտնվող իր տատի՝ Թուրհան սուլթանի դամբարանում։", "00cc8767"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["Ստամբուլի պայմանագիրը. Հարավային Կովկասի զիջումը Իրանին", "8c205aab"], "d": ["Չորս տարի տևած իրանական երկրորդ պատերազմը ավարտվեց Արփաչայի ջախջախումից, ինչպես նաև Գանձակի և Թիֆլիսի կորստից հետո ստորագրված պայմանագրով։ Օսմանյան պետությունը հեռացավ 1723 թվականից ի վեր գրաված Հարավային Կովկասի և Արևմտյան Իրանի բոլոր տարածքներից, և սահմանը վերադարձավ 1639 թվականի Կասր-ի Շիրինի գծին։ Տասներեքամյա արևելյան արշավանքներից մնացին ծանր ֆինանսական բեռ և դատարկված գանձարան. մինչդեռ Ռուսաստանի հետ սկսվող նոր պատերազմի տեսանկյունից արևելյան ճակատի փակվելը կենսական ձեռքբերում էր։", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["Օզիի (Օչակով) բերդի անկումը ռուսների ձեռքը", "f93e61f3"], "d": ["Մարշալ Մյունիխի հրամանատարությամբ ռուսական բանակը պաշարեց Դնեպրի գետաբերանի Օզիի բերդը. զինապահեստի պայթյունով պաշտպանությունը փլուզվեց, և բերդն ընկավ մարդկային մեծ կորուստներով։ Սև ծովի հյուսիսարևմտյան ափի բանալին համարվող Օզիի ձեռքից դուրս գալը ռուսների համար բացեց Ղրիմ տանող ճանապարհը և Ստամբուլում մեծ խուճապ առաջացրեց։ Բերդը հաջորդ տարի համաճարակի և մատակարարման դժվարությունների պատճառով ռուսները լքելու էին, և այն կրկին անցնելու էր Օսմանյան պետությանը։", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["Բանյա Լուկայի հաղթանակը. Բոսնիայի փրկությունը", "f603865a"], "d": ["Երբ ավստրիական ուժերը, մտնելով Բոսնիա, պաշարեցին Բանյա Լուկան, Բոսնիայի կուսակալ Հեքիմօղլու Ալի փաշան տեղի բնակչությունից հավաքած ուժերով օգնության հասավ և թվով գերակշիռ թշնամուն ծանր պարտության մատնեց։ Այս հաղթանակը հենց առաջին քայլից փլուզեց Բոսնիան գրավելու ավստրիական ծրագիրը, և էյալեթի հյուսիսը ամբողջությամբ հետ վերցվեց։ Բանյա Լուկան դարձավ այն շրջադարձային կետերից մեկը, որոնք բարձրացրին 1683 թվականից հետո Ավստրիայի դեմ անընդհատ նահանջող օսմանյան բանակի ոգին։", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["Գրոցկայի (Հիսարջըք) հաղթանակը. Բելգրադի ճանապարհի բացումը", "2101cdff"], "d": ["Բելգրադը պաշտպանելու նպատակով առաջ շարժվող ավստրիական բանակը Դանուբի ափի նեղ կիրճում դարանի մեջ ընկավ և ամբողջ օրը տևած ճակատամարտում ծանր կորուստներ կրեց։ Մինչ մարշալ Վալիսի ուժերը անկանոն կերպով նահանջում էին Բելգրադ, օսմանյան բանակը հասավ բերդի մատույցներ և սկսեց պաշարումը։ Գրոցկան Կառլովիցից ի վեր Ավստրիայի դեմ տարած ամենավճռական դաշտային հաղթանակն էր և ուղղակիորեն ապահովեց Բելգրադի հետ վերցնելը։", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["Նիշի պայմանագիրը. հաշտություն Ռուսաստանի հետ, Ազովի չեզոքացումը և ղրիմյան ասպատակությունների դադարեցումը", "674f974e"], "d": ["Ավստրիայի՝ Բելգրադում հաշտության համաձայնելով մենակ մնացած Ռուսաստանը, ֆրանսիական դեսպան Վիլնյովի միջնորդությամբ, ստիպված եղավ ավարտել պատերազմը։ Ազովի բերդի ամրությունները քանդելով՝ շրջանը երկու պետությունների միջև հայտարարվեց չեզոք հող. Ռուսաստանն ընդունեց Սև ծովում ռազմական և առևտրական նավեր չպահելու պայմանը։ Այսպիսով Ռուսաստանի՝ դեպի ծով դուրս գալու նպատակը հետաձգվեց ևս մեկ սերնդով, և Օսմանյան պետությունը XVIII դարում վերջին անգամ շահած դուրս եկավ բանակցությունների սեղանից։", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["Օզին վերադարձավ ռուսական օկուպացիայից. 1739 թվականի հաշտությամբ բերդը հանձնվեց ամրությունները քանդելուց հետո", "7ecc2bef"], "d": ["Ռուսները Օզին վերցրել էին 1737 թվականի հուլիսի 11-ին։ 1739 թվականին Ռուսաստանի հետ կնքված հաշտության համաձայն՝ բերդի ամրությունները քանդելուց հետո այն կրկին հանձնվեց օսմանցիներին. Օսմանյան պետությունը Օզին իր ձեռքում պահեց մինչև Յասիի պայմանագրից առաջ՝ 1788 թվականը։", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["Մոսուլի պաշտպանությունը. Նադիր շահի հետ մղումը", "c03ffbc1"], "d": ["Քիրքուկն ու Էրբիլը վերցնելով Մոսուլի մատույցներ եկած Նադիր շահը քառասուն օր ռմբակոծեց քաղաքը և իրար հետևից ընդհանուր գրոհներ կազմակերպեց։ Կուսակալ Հուսեյն փաշա ալ-Ջալիլիի վարած պաշտպանությունը, որին նա ներգրավեց նաև զինված քաղաքաբնակչությանը, իրանական բանակին ծանր կորուստներով ստիպեց հանել պաշարումը։ Մոսուլի դիմանալը կանխեց ամբողջ Իրաքի ձեռքից դուրս գալը և մեկ դարով ամրապնդեց Ջալիլիների ընտանիքի ազդեցությունը քաղաքում։", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["Դիրիյայի դաշինքը. առաջին Սաուդյան էմիրության հիմնումը Նեջդում", "188751bf"], "d": ["Էմիր Մուհամմադ բին Սաուդը, իր հովանավորության տակ առնելով Ույայնայից վտարված աստվածաբան Մուհամմադ իբն Աբդ ալ-Վահհաբին Դիրիյայում, նրա հետ դաշինք կնքեց, որով քաղաքական իշխանությունը դրվեց կրոնական կոչի ծառայության մեջ։ Այս համաձայնությունը Սաուդյան ընտանիքի համար նոր պատմություն սկսեց և Նեջդի ցրված օազիսային էմիրությունները միավորեց մեկ շարժման շուրջ։ Այս ուժը, որը կես դարի ընթացքում հասնելու էր Քերբելա, Մեքքա և Մեդինա, Օսմանյան պետությանը ստիպելու էր պաշտպանել իր տիրապետությունը Հիջազում։", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["Կերդենի պայմանագիրը. օսմանա-իրանական պատերազմների վերջը", "1d3a919e"], "d": ["Չորս տարի տևած վերջին պատերազմից հետո ստորագրված պայմանագրով 1639 թվականի Կասր-ի Շիրինի սահմանը նույնությամբ վերահաստատվեց. կողմերից ոչ մեկը տարածքային ձեռքբերում չունեցավ։ Նադիր շահի համառ պահանջը՝ ճանաչել ջաֆարիականությունը որպես հինգերորդ մազհաբ, անպատասխան մնաց. փոխարենը որոշվեց, որ իրանցի ուխտավորները կարող են ազատ ուխտագնացություն կատարել, և կողմերը կփոխանակեն դեսպաններ։ Այսպիսով ավելի քան երկու դար տևած օսմանա-իրանական պատերազմները փաստացի փակվեցին. այս սահմանը մինչև այսօր մեծ մասամբ պահպանվել է։", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["Մահմուդ I-ի մահը և Օսման III-ի գահակալումը", "30203700"], "d": ["Իր քսանչորսամյա կառավարման ընթացքում Բելգրադի պայմանագրով կորցված հողերը հետ վերցրած և Խումբարաջի օջախի բարեփոխումը աջակցած Մահմուդ I-ը վախճանվեց ուրբաթօրյա սելամլըքից վերադառնալիս։ Նրան փոխարինեց մինչև հիսունութ տարեկանը վանդակի կյանք ապրած եղբայրը՝ Օսման III-ը։ Սկսվեց կարճ ու անհանգիստ կառավարում. երեք տարում վեց մեծ վեզիր փոխած Օսման III-ի օրոք պետական գործերում նկատելի լճացում տիրեց։", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["Օսման III-ի մահը և Մուստաֆա III-ի գահակալումը", "3ac10f85"], "d": ["Երեքամյա կառավարումից հետո Օսման III-ի մահով գահ բարձրացավ բարեփոխումների գաղափարներին բաց և պետական գործերով մոտիկից հետաքրքրվող Մուստաֆա III-ը։ Նոր փադիշահը, հենվելով մեծ վեզիր Քոջա Ռաղըփ փաշայի փորձի վրա, փորձեց կարգավորել ֆինանսները և նորոգել բանակը. այս շրջանում ստեղծվեցին բարոն դե Տոտի արագաձիգ հրետանավորները։ Սակայն 1768 թվականին սկսված ռուսական պատերազմը ստվերելու էր տասնյոթամյա կառավարման բոլոր ձեռքբերումները։", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["Պատերազմի հայտարարում Ռուսաստանին. Բալթայի դեպքը և 1768-1774 թվականների պատերազմի սկիզբը", "9c6aabe0"], "d": ["Լեհաստանում Բարի կոնֆեդերացիային հետապնդող ռուսական և կազակական զորամասերը հարձակվեցին օսմանյան սահմանի Բալթա ավանի վրա և այրեցին այն. Դիվանը պատերազմի որոշում կայացրեց, իսկ ռուս դեսպանը բանտարկվեց Եդիքուլեում։ Առանց լուրջ ռազմական նախապատրաստության և վեց ամիս առաջ հայտարարելով սկսված պատերազմը հենց սկզբից վատ ընթացավ։ Վեց տարի տևելիք այս պայքարը Չեշմեի հարձակումով, Կագուլի ջախջախմամբ և Ղրիմի օկուպացիայով վերածվելու էր օսմանյան պատմության ամենածանր պարտությունների շարաններից մեկի։", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["Խոտինի բերդի կորուստը հօգուտ ռուսների", "66d43ea4"], "d": ["Մինչ իշխան Գոլիցինի հրամանատարությամբ ռուսական բանակի երկու փորձը հետ էր մղվել, Կամենեցի և Խոտինի միջև մեծ վեզիրի կրած ջախջախումից հետո բանակը հետ քաշվեց, և կայազորը դատարկեց բերդը։ Դանուբից հյուսիս ամենահզոր օսմանյան ամրության՝ առանց դիմադրության ձեռքից դուրս գալը ռուսների առջև բացեց Վալախիայի և Մոլդովայի դռները։ Երկու իշխանությունները նույն տարի օկուպացվեցին. Խոտինը հնարավոր եղավ հետ վերցնել միայն 1774 թվականին՝ Քյուչուկ Կայնարջայի պայմանագրով։", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["Կագուլի (Քարթալ) դաշտի ջախջախումը", "6f408eaf"], "d": ["Չեշմեում նավատորմի այրվելուց երեք շաբաթ անց Դանուբի երկայնքով գտնվող օսմանյան գլխավոր բանակը Կագուլի դաշտում ցրվեց մարշալ Ռումյանցևի՝ թվով շատ ավելի փոքր, բայց կարգապահ զորամասերի առջև։ Ճամբարը, գումակը և հարյուրավոր թնդանոթներ անցան թշնամու ձեռքը. փախչող զորամասերը Դանուբն անցնելիս մեծ կորուստներ կրեցին։ Նույն ամռանը և՛ նավատորմի, և՛ ցամաքային բանակի ոչնչացումը հանգեցրեց Կիլիայի, Աքքերմանի, Իզմայիլի և Բենդերի իրար հետևից անկմանը և Ղրիմի օկուպացիային։", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["Ղրիմի թերակղզու ռուսական օկուպացիան", "217837b0"], "d": ["Մեկ տարի առաջ Բուջաքը գրաված ռուսական բանակները իշխան Դոլգորուկովի հրամանատարությամբ անցան Օր Կապիի (Պերեկոպ) ամրությունը և ներխուժեցին ամբողջ Ղրիմի թերակղզի։ Խանը գահընկեց արվեց, իսկ ռուսամետ Սահիբ Գիրեյը դրվեց իշխանության գլուխ. այդպիսով կատարվեց խանությունը Օսմանյան պետությունից պոկելու ուղղությամբ առաջին քայլը։ Երեք դար Օսմանյան պետության հյուսիսային վահանը եղած Ղրիմի ձեռքից դուրս գալը սկիզբն էր մի գործընթացի, որը 1774 թվականին հանգեցնելու էր անկախության, իսկ 1783 թվականին՝ ուղղակի բռնակցման։", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["Մուստաֆա III-ի մահը և Աբդուլհամիդ I-ի գահակալումը", "42cba8e2"], "d": ["Ռուսական պատերազմի ամենաճգնաժամային պահին վախճանված Մուստաֆա III-ին փոխարինեց պալատի վանդակում քառասուներեք տարի անցկացրած նրա եղբայր Աբդուլհամիդ I-ը՝ քառասունինը տարեկանում։ Պետության ամենածանր շրջաններից մեկը ստանձնած նոր փադիշահը ստիպված եղավ առերեսվել նույն տարի ստորագրվելիք Քյուչուկ Կայնարջայի պայմանագրի ծանր պայմաններին։ Նրա տասնհինգամյա կառավարումն անցնելու էր Ղրիմի կորստով և ռուսական նոր պատերազմով և ավարտվելու էր 1789 թվականին Օզիի անկման լուրը կարդալիս տարած կաթվածով։", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["Կոզլուջայի ջախջախումը. դեպի Քյուչուկ Կայնարջա տանող պարտությունը", "8e0542f9"], "d": ["Շումենի մոտ հավաքված օսմանյան ուժերը Կոզլուջայում պարտվեցին Սուվորովի և Կամենսկու միացյալ զորասյուներին, և բանակի մեծ մասը ցրվեց։ Այս ջախջախումից հետո Բալկաններում դիմադրելու ուժ չմնաց. ռուսական առաջապահները պաշարեցին Շումենը, և մեծ վեզիրի շտաբը սպառնալիքի տակ հայտնվեց։ Մեկ ամիս չանցած Քյուչուկ Կայնարջայում բանակցությունների սեղան նստելն ու արտակարգ ծանր պայմանների ընդունումը այս պարտության ուղղակի հետևանքն են։", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["Բուկովինայի (Հյուսիսային Մոլդովա) զիջումը Ավստրիային", "190f9caa"], "d": ["Քյուչուկ Կայնարջայի առաջացրած թուլությունից օգտվելով՝ Ավստրիան պահանջեց Մոլդովայի և Տրանսիլվանիայի միջև կապն ապահովող Բուկովինայի շրջանը և առանց պատերազմի մեջ մտնելու, սպառնալիքով և կաշառքով ձեռք բերեց այս հողը։ Խոտինից հարավ-արևմուտք գտնվող այս բերրի և ռազմավարական շրջանի կորուստը Մոլդովայի վոյևոդությունը փաստացի բաժանեց երկու մասի։ Առանց մեկ գնդակ արձակելու կատարված այս զիջումը համարվեց այն բանի ամենաբացահայտ ցուցիչներից մեկը, որ Օսմանյան պետությունն այլևս կորցրել էր զսպելու ուժը։ 1775 թվականին Բուկովինայի զիջմամբ Սուչավան և Չեռնովիցը անցան Ավստրիային (օրը հաստատված չէ)։", "93bbc1f7"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["Բասրայի գրավումը Իրանի կողմից", "0161e709"], "d": ["Զենդ տիրակալ Քերիմ խանի եղբայր Սադեղ խանը մեկ տարի տևած պաշարումից հետո գրավեց Բասրան, և Օսմանյան պետությունը կորցրեց Պարսից ծոցի իր կարևորագույն նավահանգիստը։ Օկուպացիան ուղղակիորեն հարվածեց Հնդկաստանի առևտրային ճանապարհին, արմավի և մարգարիտի եկամուտներին և Իրաքի հարավային պաշտպանությանը։ Քաղաքը հնարավոր եղավ հետ վերցնել միայն 1779 թվականին՝ Քերիմ խանի մահից հետո Իրանում բռնկված գահակալական կռիվների ընթացքում։", "838306ba"]},
"OLAYLAR_EK5:1779-03-21:0":{"b": ["Այնալըքավաքի թեմքիհնամեն (պարզաբանման համաձայնագիր). ժամանակավոր համաձայնություն Ղրիմի շուրջ", "9b3b0468"], "d": ["Ղրիմի խանության գլուխ ով անցնելու հարցի պատճառով պատերազմի շեմին հասած երկու պետությունները Ֆրանսիայի միջնորդությամբ Այնալըքավաք քյոշքում ստորագրեցին պարզաբանող տեքստ։ Ռուսաստանը համաձայնեց իր զորքը դուրս բերել Ղրիմից, իսկ Օսմանյան պետությունը՝ ճանաչել ռուսամետ Շահին Գիրեյի խանությունը. հաստատվեց փադիշահի կրոնական՝ խալիֆայական իրավունքը Ղրիմի նկատմամբ։ Չորս տարի տևելիք այս փխրուն հավասարակշռությունը լիովին փլուզվելու էր 1783 թվականին՝ Ռուսաստանի կողմից թերակղզու ուղղակի բռնակցմամբ։", "8a428802"]},
"OLAYLAR_EK5:1781-01-01:0":{"b": ["Անապայի բերդի կառուցումը. կովկասյան պաշտպանական գիծը", "be92a80f"], "d": ["Քյուչուկ Կայնարջայով Ղրիմի ձեռքից դուրս գալուց հետո Կովկասում օսմանյան ազդեցությունը պահպանելու նպատակով Կուբան գետի գետաբերանում սկսվեց նոր բերդի կառուցումը։ Ջենովական գաղութի ավերակների վրա հիմնված Անապան իր շուկայով, բաղնիքներով և երկու հարյուր հիսունից ավելի խանութներով կարճ ժամանակում դարձավ չերքեզական ցեղերի հետ կապն ապահովող քաղաք։ Բերդը քառասունութ տարի մնաց Օսմանյան պետության ամենաառաջավոր պահակակետը Ռուսաստանի՝ Կովկաս իջնելու դեմ։", "334a40cb"]},
"OLAYLAR_EK5:1785-04-27:0":{"b": ["Մեծ վեզիր Խալիլ Համիդ փաշայի պաշտոնանկությունը և մահապատիժը", "c44001ca"], "d": ["Բարենորոգիչ մեծ վեզիր Խալիլ Համիդ փաշան, որի ծառայություններից իր գոհունակությունը Աբդուլհամիդ I-ը տարբեր առիթներով արտահայտել էր, 1785 թ. մարտի 31-ի լույս առավոտյան հանկարծակի պաշտոնանկ արվեց և աքսորվեց Գալիպոլի, իսկ նրա ողջ ունեցվածքը բռնագրավվեց։ Սկզբում նրան տրվեցին Հաբեշի էյալեթը, Ջիդդայի սանջակը և Մեքքայի շեյխ ալ-հարամի պաշտոնը. 1785 թ. ապրիլն անցկացնելով Բոզջաադայում՝ ճամփորդության պատրաստություններով, նա պաշտոնանկ արվեց նաև այս կուսակալությունից, և արձակված մահապատժի ֆիրմանով նրան սպանեց Ջեզայիրլի Ղազի Հասան փաշայի մարդկանցից Կարաքեթհյուդազադե Ալին։ Կտրված գլուխն ուղարկվեց Ստամբուլ և ցուցադրվեց Օրթակափըի (Միջին դարպասի) մոտ։ Ըստ TDV-ի՝ թեև այս հանկարծակի անկումը մեկնաբանվել է փադիշահին գահընկեց անելու և նրա փոխարեն շեհզադե Սելիմին գահ բարձրացնելու դավադրության մեղադրանքով, իրական պատճառները, հավանաբար, Ղրիմի բռնակցման հանդեպ լռության պատճառով առաջացած զայրույթը, նրա բարեփոխումներից տուժած շրջանակների թշնամանքն ու Ղազի Հասան փաշայի ընդդիմությունն էին։", "6f73b0a5"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["Պատերազմի հայտարարում Ռուսաստանին. սկսվեց 1787-1792 թվականների օսմանա-ռուսական պատերազմը", "3bfb870c"], "d": ["Եկատերինա II-ի ցուցադրական ղրիմյան ճամփորդության և Վրաստանը իր հովանավորության տակ առնելու պատճառով Դիվանը պատերազմի որոշում կայացրեց՝ բռնակցումը հետ դարձնելու նպատակով, և ռուս դեսպանը կրկին փակվեց Եդիքուլեում։ Սակայն բանակը պատրաստ չէր, գանձարանը դատարկ էր, իսկ դաշնակիցների որոնումը անարդյունք էր մնացել։ Հինգ տարի տևելիք պատերազմը ավարտվելու էր Օզիի՝ կոտորածով ուղեկցված անկմամբ, Իզմայիլի կորստով և Յասիի պայմանագրի ծանր պայմաններով։", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["Ավստրիայի մուտքը պատերազմի մեջ. երկճակատ պայքար", "ae912290"], "d": ["Ռուսաստանի հետ 1781 թվականին կնքած գաղտնի դաշինքի համաձայն՝ Ավստրիայի կայսր Յոզեֆ II-ը, պատերազմ հայտարարելով Օսմանյան պետությանը, շարժվեց Բելգրադի և Բոսնիայի ուղղությամբ։ Օսմանյան բանակը մեկեն ստիպված եղավ կռվել միաժամանակ երկու ճակատում՝ հյուսիսում Ռուսաստանի, արևմուտքում Ավստրիայի դեմ։ Չնայած Լազարեթհանեում, Մեհադիայում և Շեբեշում ավստրիացիների դեմ տարած հաղթանակներին՝ 1789 թվականին Բելգրադի կորստով փլուզվելու էր նաև արևմտյան ճակատը։", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["Օսմանա-պրուսական դաշինքը", "03b88e51"], "d": ["Գահ բարձրանալուն պես Եվրոպայում դաշնակից փնտրող Սելիմ III-ը Պրուսիայի հետ ստորագրեց փոխօգնություն նախատեսող դաշնակցային պայմանագիր. Պրուսիան պարտավորվեց պատերազմ հայտարարել Ռուսաստանին և Ավստրիային, իսկ Օսմանյան պետությունը՝ չհաշտվել, քանի դեռ Ղրիմը հետ չի վերցվել։ Սա օսմանյան պատմության մեջ եվրոպական պետության հետ ստորագրված իրական փոխադարձ դաշինքի առաջին տեքստն էր և ցույց էր տալիս, որ լքվել է «անհավատների հետ դաշինք չի լինում» դասական ընկալումը։ Պրուսիան պատերազմի մեջ չմտավ, սակայն Ավստրիային ստիպելով հաշտության՝ ճանապարհ բացեց Սիստովի պայմանագրի համար։", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["Իզմայիլի բերդի անկումը և կոտորածը", "6a296b0c"], "d": ["Դանուբի դելտայի ամենահզոր ամրությունը համարվող Իզմայիլի բերդը մեկ օրում գրավվեց գեներալ Սուվորովի կազմակերպած արյունալի ընդհանուր գրոհով. կայազորը և քաղաքի բնակչությունը մեծ մասամբ սրի քաշվեցին։ Եվրոպայում լայն արձագանք ունեցած այս կոտորածը օսմանյան հասարակության մեջ խոր ցնցում առաջացրեց և կոտրեց Դանուբի պաշտպանական գծի ողնաշարը։ Բերդը մեկ տարի անց հետ էր վերցվելու Յասիի պայմանագրով, սակայն պատերազմի ճակատագիրը վաղուց արդեն որոշված էր լինելու։", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["Սիստովի պայմանագիրը. ավստրիական ճակատի փակումը", "58741f1d"], "d": ["Պրուսիայի ճնշման և Ֆրանսիական հեղափոխության՝ Ավստրիային արևմուտքում զբաղեցնելու շնորհիվ երկու պետությունները հաշտվեցին՝ հիմք ընդունելով նախապատերազմյան սահմանները։ Ավստրիան վերադարձրեց իր զբաղեցրած բոլոր վայրերը, այդ թվում՝ Բելգրադը. Օսմանյան պետությունն ընդունեց միայն փոքր ճշտումներ Խորվաթիայի սահմանին։ Արևմտյան ճակատի այս պայմաններով փակվելը թույլ տվեց Օսմանյան պետությանը իր ամբողջ ուժը կենտրոնացնել Ռուսաստանի դեմ և սահմանափակեց Յասիի պայմանագրի կորուստը։ Խորվաթիայի սահմանի այս ճշտումներով Ցետինը (Cetingrad) և Drežnik Grad-ը Օսմանյան պետությունից անցնում են Հաբսբուրգներին (TDV zistovi-antlasmasi; Korić 2016, n. 118, 4-րդ հոդված)։ Իսկ Օրշովան (Հին Օրշովա) միակ վայրն է, որը չվերադարձվեց (Bánlaky 0019/1796). Ատլասը իրավական փոխանցումը գրում է այս օրով (փաստացի օկուպացիան՝ 1790 թվականի ապրիլի 16)։", "83845e51"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["Յասիի պայմանագիրը. Ղրիմի վերջնական կորուստը և Դնեստրի սահմանը", "a56fd194"], "d": ["Հնգամյա պատերազմի ավարտին ստորագրված պայմանագրով Դնեստր (Թուրլա) գետն ընդունվեց որպես սահման. գետի ձախ ափը մնաց Ռուսաստանին, աջ ափը՝ Օսմանյան պետությանը, իսկ Օզին և նրա շրջակայքը վերջնականապես ձեռքից դուրս եկան։ Օսմանյան պետությունը լիովին թողեց Ղրիմը հետ վերցնելու հույսը և իրավականորեն ճանաչեց 1783 թվականի բռնակցումը. Վալախիան և Մոլդովան վերադարձվեցին երկամյա հարկային արտոնությամբ։ Ընդունվեց նաև տասներկու միլիոն ղուրուշ ռազմատուգանքի պարտավորությունը. այսպիսով Սև ծովի հյուսիսը մնայուն կերպով թողնվեց Ռուսաստանին։ Նույն ամսաթվին միացած այլ վայրեր՝ Իզմայիլ։", "277ee99d"]},
"OLAYLAR_EK5:1792-02-12:0":{"b": ["Օրանի (Վահրան) դատարկումը իսպանացիների կողմից և փոխանցումը Ալժիրին", "9f95cee6"], "d": ["1790 թվականի երկրաշարժից բերդն ու քաղաքը մեծ մասամբ ավերվելուց հետո Իսպանիան, այլևս չկարողանալով կրել երեք դար պահած ծախսատար կայազորը, համաձայնության գալով Ալժիրի օջախի հետ, առանց կռվի փոխանցեց Օրանը և Մերս էլ-Քեբիրը։ Այսպիսով Հյուսիսային Աֆրիկայի ափի վերջին եվրոպական դիրքը ևս վերացվեց։ Օսմանյան Ալժիրը մինչև ֆրանսիական օկուպացիան մնացած երեսունութ տարիների ընթացքում տիրեց ամբողջ ափին։", "c73636aa"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["Փազվանդօղլու Օսմանի փաստացի տիրակալությունը Վիդինում", "0ce70361"], "d": ["Նիզամ-ը Ջեդիդի (Նոր կարգի) կարգավորումների դեմ ապստամբած Փազվանդօղլու Օսմանը, փախուստի մատնելով Վիդինի կուսակալին, գրավեց քաղաքը և Դանուբի երկայնքով ամրացրեց խոր խրամներով։ 1797 թվականին իր հզորության գագաթնակետին, հավաքելով մոտ ութսուն հազարանոց ուժ, նա իր վերահսկողության տակ վերցրեց Նիկոպոլը, Սիստովը, Ռուսեն, Սոֆիան և Նիշը. իրեն ներկայացնում էր ոչ թե որպես ապստամբ, այլ որպես բարեփոխիչ։ Բարձր դռան 1798-1799 թվականներին ամիսներ տևած պաշարումը անարդյունք մնաց, և նա մինչև 1807 թվականին իր մահը կիսաանկախ իշխեց Հյուսիսային Բուլղարիայում։", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["Կայսերական ցամաքային ինժեներական դպրոցի (Մյուհենդիսհանե-ի Բերրի-ի Հյումայուն) բացումը", "e9a3a34b"], "d": ["Նիզամ-ը Ջեդիդի բանակի համար հրետանու, ամրաշինության և քարտեզագրության սպաներ պատրաստելու նպատակով Հասքյոյում բացվեց ցամաքային ինժեներական դպրոցը. այն 1773 թվականին հիմնված ծովային ինժեներական դպրոցի համարժեքն էր ցամաքային բանակում։ Ծրագրում դասավանդվում էին հանրահաշիվ, երկրաչափություն, մեխանիկա, ամրաշինություն և հրաձգաբանություն, եվրոպական լեզուներից թարգմանվում էին մաթեմատիկայի և հրետանու գրքեր։ Թուրքիայում ժամանակակից ինժեներական կրթության արմատը համարվող այս դպրոցը ընդունվում է որպես այսօրվա Ստամբուլի տեխնիկական համալսարանի սկիզբը։", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["Պատերազմի հայտարարում Ֆրանսիային և դաշինք Ռուսաստանի ու Անգլիայի հետ", "80e95bd7"], "d": ["Նապոլեոնի կողմից Եգիպտոսի օկուպացիայից հետո Օսմանյան պետությունը, խախտելով երկուսուկես դարի ավանդական ֆրանսիական բարեկամությունը, պատերազմ հայտարարեց Ֆրանսիային։ Նույն գործընթացում իր պատմության մեջ առաջին անգամ դաշինք կնքեց Ռուսաստանի հետ և ռուսական նավատորմին թույլ տվեց նեղուցներով անցնելով դուրս գալ Միջերկրական ծով. այնուհետև դաշինք ստորագրվեց նաև Անգլիայի հետ։ Այս դաշինքների շնորհիվ Հոնիական կղզիները վերցվեցին ֆրանսիացիներից, սակայն նեղուցների բացումը օտար նավատորմի առջև ստեղծեց նախադեպ, որը հետագայում թանկ էր նստելու։", "7d8a9e45"]},
"OLAYLAR_EK5:1798-10-23:0":{"b": ["Պրևեզայի վերցնելը ֆրանսիացիներից. Նիկոպոլիսի ճակատամարտը", "d8e5e892"], "d": ["1797 թվականին Վենետիկի հանրապետության անկումից հետո Հոնիական կղզիները և ցամաքի Պրևեզան, Պարգան, Վոնիցան անցան Ֆրանսիայի ձեռքը։ Յանինայի կուսակալ Ալի փաշա Թեփեդելենցին, օգտվելով Եգիպտոսի ֆրանսիական օկուպացիայի պատճառով բացված պատերազմից, շարժվեց Պրևեզայի վրա և քաղաքից դուրս գտնվող Նիկոպոլիսի ավերակներում ծանր պարտության մատնեց ֆրանսիական կայազորին։ Այսպիսով Պոժարևացով Վենետիկին թողնված այս նավահանգիստը ութսուն տարի անց անցավ օսմանյան կառավարման տակ։ Բուտրինտը (Butrinto), ֆրանսիական կայազորի՝ ամրությունները պայթեցնելով և Կորֆու քաշվելով, ընկավ հոկտեմբերի 25-ին (Curlin, Preveza B, 2010; Ատլասը օրը վերցնում է Պրևեզայից) և անցավ օսմանյան կառավարման տակ։", "f32e8843"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["Աքքայի պաշտպանությունը. Նապոլեոնի հետ մղումը", "56b5c45b"], "d": ["Եգիպտոսից Սիրիա առաջ շարժվող Նապոլեոնը պաշարեց Աքքան և երկու ամիս շարունակ իրար հետևից գրոհներ կազմակերպեց. քաղաքը Ջեզզար Ահմեդ փաշան պաշտպանեց անգլիական նավատորմի աջակցությամբ և Ստամբուլից ուղարկված Նիզամ-ը Ջեդիդի զորամասերով։ Պաշարումը հանելով Եգիպտոս նահանջելու ստիպված Նապոլեոնը դեպի արևելք տարածվելու իր երազանքը թաղեց այս պարիսպների առջև։ Լուրը Ստամբուլում մեծ ուրախությամբ ընդունվեց և համարվեց ապացույց, որ նորաստեղծ վարժեցված բանակը հանձնել էր իր առաջին լուրջ քննությունը։", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["Վահաբիների հարձակումը Քերբելայի վրա", "522341ed"], "d": ["Նեջդից դուրս եկած վահաբիական ուժերը, մտնելով Քերբելա, թալանեցին քաղաքը, ավերեցին Իմամ Հուսեյնի դամբարանը և սպանեցին ավելի քան երեք հազար մարդ։ Իրաքում Օսմանյան պետության քյոլեմեն կուսակալները չկարողացան կանխել հարձակումը. դեպքը մեծ վրդովմունք առաջացրեց և՛ Իրանում, և՛ Ստամբուլում։ Այս հարձակումը հայտարարություն էր այն մասին, որ սաուդյան շարժումն այլևս օազիսային էմիրությունից վերածվել էր օսմանյան սրբազան քաղաքներին սպառնացող տարածաշրջանային ուժի։", "f571ab30"]},
"OLAYLAR_EK5:1801-09-24:0":{"b": ["Քարթլի-Կախեթին (Արևելյան Վրաստանը) բռնակցվեց Ռուսաստանին", "3b650c5e"], "d": ["1783 թ. ռուսական հովանավորությունն ընդունած և 1795 թ. Իրանի ավերիչ արշավանքին ենթարկված Քարթլի-Կախեթի թագավորությունը վերացվեց. 1801 թ. սեպտեմբերի 12-ի հրամանով այն հռչակվեց Ռուսաստանի նահանգ, և սկսվեց ռուսական կառավարման համակարգի ներդրումը։ Այդ ժամանակից Վրաստանը կորցրեց անկախությունը. մի քանի տարվա ընթացքում Մեգրելիան (1803), Իմերեթին և Գուրիան (1804) նույնպես անցան ռուսական տիրապետության տակ, և Ռուսաստանը հասավ Օսմանյան կայսրության կովկասյան սահմանին։ Այս իրադարձությամբ Գորին, Դուշեթին (Քարթլի) և Թելավին (Կախեթի) անցան Ռուսաստանին։", "f5e0d5d5"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["Եգիպտոսի ազատագրումը ֆրանսիացիներից (տարհանում)", "00cfdc8c"], "d": ["Օսմանյան և անգլիական ուժերի ցամաքից ու ծովից համատեղ գործողության արդյունքում նախ Կահիրեն, ապա Ալեքսանդրիան հանձնումով վերցվեցին, և ֆրանսիական ուժերը նավերով ուղարկվեցին իրենց երկիր։ Երեք տարի տևած օկուպացիայի ավարտով Եգիպտոսը թղթի վրա վերադարձավ օսմանյան կառավարմանը, սակայն քյոլեմեն բեյերի և ալբանական զորամասերի միջև իշխանության պայքարը երկիրը գցեց քաոսի մեջ։ Այս դատարկությունը մի քանի տարում հող էր նախապատրաստելու Կավալացի Մեհմեդ Ալիի վերելքի համար։", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["Փարիզի պայմանագիրը. Ֆրանսիայի հետ հաշտության վերահաստատումը", "1b76991f"], "d": ["Եգիպտոսի ազատագրումից հետո ստորագրված պայմանագրով Օսմանյան պետության և Ֆրանսիայի միջև պատերազմական վիճակը պաշտոնապես ավարտվեց, և վերանորոգվեցին հին կապիտուլյացիաները։ Ֆրանսիական առևտրական նավերին թույլատրվեց մտնել Սև ծով. փոխարենը Ֆրանսիան ճանաչեց օսմանյան տարածքային ամբողջականությունը։ Հաշտության հաստատումը Ռուսաստանի ու Անգլիայի կողքին նեղն ընկած Սելիմ III-ի արտաքին քաղաքականությանը վերստին մանևրի տարածք տվեց։", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["Վահաբիների կողմից Թաիֆի գրավումը", "7b791359"], "d": ["Սաուդ բին Աբդ ալ-Ազիզի հրամանատարությամբ վահաբիական ուժերը Հիջազին ուղղված առաջին հարվածով պաշարեցին և թալանեցին Թաիֆը. քաղաքն ընկավ որպես սրբազան հողեր բացվող առաջին դուռը։ Երկու սրբավայրերի հովանավորի տիտղոսը կրող օսմանյան փադիշահի համար սա սուլթանության լեգիտիմությունը ուղղակիորեն խարխլող հարված էր։ Երկուսուկես ամիս անց նույն բանակը շարժվելու էր Մեքքայի վրա։", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["Վահաբիների կողմից Մեքքայի առաջին գրավումը", "21157c05"], "d": ["Թաիֆի անկումից երկուսուկես ամիս անց վահաբիական ուժերը մտան Մեքքա, քանդեցին դամբարանները և իրենց ըմբռնմամբ կարգ հաստատեցին. շարիֆ Ղալիբը ստիպված եղավ քաշվել Ջիդդա։ Ուխտագնացության ճանապարհների փակումը արձագանք գտավ ամբողջ իսլամական աշխարհում և Ստամբուլին ստիպեց ռազմական օգնություն խնդրել Եգիպտոսի կուսակալ Մեհմեդ Ալիից։ Այս առաջին տիրապետությունը տևելու էր միայն երեք ամիս։", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["Շարիֆ Ղալիբի կողմից Մեքքայի հետ վերցնելը", "83d08dff"], "d": ["Ջիդդա քաշված շարիֆ Ղալիբը իր հավաքած ուժերով պաշարեց Մեքքան և քսանհինգօրյա պաշարումից հետո քաղաքը հետ վերցրեց վահաբիներից. Օսմանյան պետության անունով խուտբան կրկին կարդացվեց։ Այս երկրորդ տիրապետությունը ևս մնայուն չէր լինելու. սաուդյան ուժերը 1806 թվականին կրկին վերցնելու էին քաղաքը։", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["Սերբական առաջին ապստամբության սկիզբը", "0f6e8767"], "d": ["Բելգրադում կառավարումն իրենց ձեռքը վերցրած ապստամբ ենիչերի դայիների կողմից սերբ ավագանու զանգվածային սպանությունից հետո Կարա Յորգու (Karađorđe) առաջնորդությամբ սկսվեց զինված դիմադրություն։ Սկզբում փադիշահին հավատարիմ մնալով և միայն դայիների դեմ վարվող շարժումը շուտով վերածվեց ինքնավարություն և անկախություն պահանջող ազգային ապստամբության։ Սերբական ուժերը 1806 թվականին գրավեցին Բելգրադը. այս ապստամբությունը դարձավ Բալկաններում ազգայնական անկախության շարժումների առաջին օղակը։", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["Վահաբիների կողմից Մեդինայի օկուպացիան", "84e310d7"], "d": ["Մեքքայից հետո Մեդինան ևս անցավ վահաբիական ուժերի ձեռքը. Ռաուզա-ի Մութահհարայի (Մարգարեի գերեզմանի սրբավայրի) գանձերը բաժանվեցին, և քաղաքի գմբեթավոր դամբարանները քանդվեցին։ Այսպիսով երկու սրբազան քաղաքները միաժամանակ դուրս եկան օսմանյան վերահսկողությունից, և Դամասկոսից ու Եգիպտոսից եկող ուխտագնացական քարավանները տարիներ շարունակ չկարողացան ճանապարհ ելնել։ Մեդինան հնարավոր եղավ հետ վերցնել միայն յոթ տարի անց՝ 1812 թվականին, Մեհմեդ Ալի փաշայի որդի Թուսուն փաշայի հրամանատարությամբ եգիպտական բանակի կողմից։", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["Ռուսաստանի հետ պատերազմի սկիզբը (1806-1812 թվականների օսմանա-ռուսական պատերազմ) և նեղուցների փակումը", "ea170804"], "d": ["Նապոլեոնի Աուստեռլիցի հաղթանակից հետո Ֆրանսիային մերձեցող Սելիմ III-ը, չնայած ռուսական ճնշմանը, պաշտոնանկ արեց Վալախիայի և Մոլդովայի վոյևոդներին. ռուսական բանակները գրավեցին երկու իշխանությունները, և սկսվեց պատերազմը։ Օսմանյան պետությունը նեղուցները փակեց ռուսական նավատորմի առջև. ի պատասխան Անգլիան, կանգնելով Ռուսաստանի կողքին, նավախումբ ուղարկեց Ստամբուլ։ Վեց տարի տևելիք այս պատերազմը, միահյուսվելով Կաբաքչիի ապստամբությանը և Սելիմ III-ի գահընկեցությանը, ավարտվելու էր 1812 թվականի Բուխարեստի պայմանագրով Բեսարաբիայի կորստով։", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["Անգլիական նավատորմի ժամանումը Ստամբուլի մատույցներ (Դաքվորթի գործողությունը)", "195bb58f"], "d": ["Օսմանյան պետությանը ստիպել ցանկանալով խզել կապը Ֆրանսիայի հետ՝ Անգլիան ծովակալ Դաքվորթի հրամանատարությամբ նավախումբը անցկացրեց Դարդանելով և խարսխեց Ստամբուլի մատույցներում։ Ֆրանսիական դեսպան Սեբաստիանիի ուղղորդմամբ ևս Ստամբուլի բնակչությունը մոբիլիզացվեց, ափամերձ մարտկոցները օրերի ընթացքում ուժեղացվեցին, և նավախումբը, քաղաքը չկարողանալով ռմբակոծել, ստիպված եղավ հետ քաշվել. վերադարձի ճանապարհին Դարդանելում ծանր կորուստներ կրեց։ Մայրաքաղաքի՝ օտար նավատորմի կողմից առաջին անգամ այսքան մոտիկից սպառնալիքի տակ հայտնվելը նեղուցների հարցը դրեց եվրոպական դիվանագիտության կենտրոնում։", "bf71116c"]},
"OLAYLAR_EK5:1808-11-17:0":{"b": ["Մուստաֆա IV-ի խեղդամահությունը", "eeb75c20"], "d": ["Երբ Ալեմդար Մուստաֆա փաշան հարձակման ենթարկվելով զոհվեց, և ապստամբները ցանկացան շարժվել դեպի պալատ, գահընկեց արված Մուստաֆա IV-ը իր եղբայր Մահմուդ II-ի հրամանով խեղդամահ արվեց։ Դին թաղվեց Բահչեքափըում՝ իր հոր՝ Աբդուլհամիդ I-ի դամբարանում. ապստամբների շրջանում տարածվեց լուր, թե դագաղը դատարկ է։", "8a944508"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["Կալե-ի Սուլթանիեի (Չանակկալեի) պայմանագիրը. հաշտություն Անգլիայի հետ և նեղուցների կանոնը", "fe282117"], "d": ["Դաքվորթի գործողության ձախողումից հետո Անգլիայի հետ ստորագրված պայմանագրով ավարտվեց երկու պետությունների միջև պատերազմը, և անգլիացի վաճառականներին վերադարձվեցին նախկին արտոնությունները։ Տեքստում տեղ գտած և «հնավանդ կանոն» կոչվող դրույթը արձանագրում էր, որ խաղաղ ժամանակ ոչ մի օտար ռազմանավ չի կարող անցնել նեղուցներով։ Այս սկզբունքը դարձավ XIX դարի ընթացքում նեղուցների ռեժիմը ձևավորելիք բոլոր միջազգային կարգավորումների իրավական հիմքը։", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["Սլոբոզիայի ջախջախումը. Դանուբյան բանակի շրջապատումը", "54b60fd1"], "d": ["Ռուսեի մոտ Դանուբն անցած օսմանյան բանակի մեծ մասը Կուտուզովի՝ գետի հակառակ ափից կատարած շրջապատման մանևրով սեղմվեց Սլոբոզիայում և մատնվեց սովի։ Հազարավոր զինվորներ ստիպված եղան հանձնվել. մեծ վեզիրի ձեռքում եղած ուժը փաստացի հալվեց, և Բարձր դուռը մեկ ամիս անց ստիպված եղավ զինադադար խնդրել։ Այս պարտությունը 1812 թվականի Բուխարեստի պայմանագրով Բեսարաբիան տալու համաձայնության ուղղակի պատճառն է։", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["Բելգրադի հետ վերցնելը և սերբական առաջին ապստամբության ճնշումը", "06f56f52"], "d": ["Բուխարեստի պայմանագրով ռուսական աջակցությունից զրկված սերբ ապստամբները չդիմացան Բոսնիայից և Ռումելիայից եկած ուժերի համատեղ գործողությանը. Խուրշիդ Ահմեդ փաշան մտավ Բելգրադ, և իննամյա ապստամբությունը լիովին ճնշվեց։ Կարա Յորգին փախավ Ավստրիա, Սմեդերևոյի սանջակը վերստին ուղղակիորեն ենթարկվեց օսմանյան կառավարմանը։ Սակայն կիրառված խիստ միջոցները երկու տարի անց հրահրելու էին Միլոշ Օբրենովիչի առաջնորդությամբ երկրորդ և մնայուն ապստամբությունը։", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["Սերբական երկրորդ ապստամբությունը և Միլոշ Օբրենովիչի գլխավոր կնյազությունը", "e6e82ad2"], "d": ["Առաջին ապստամբության ճնշումից հետո կիրառված ծանր միջոցների դեմ Միլոշ Օբրենովիչի առաջնորդությամբ բռնկվեց նոր ապստամբություն. այս անգամ Բարձր դուռը ուժի փոխարեն նախընտրեց համաձայնությունը։ Կնքված համաձայնությամբ Միլոշը ճանաչվեց «գլխավոր կնյազ» կարգավիճակով, հարկեր հավաքելու և ներքին գործերը վարելու իրավասությունը թողնվեց սերբ կնյազներին։ Փաստացի ինքնավարության այս առաջին միջուկը դարձավ 1830 թվականի հրովարտակին և 1878 թվականի անկախությանը հասնող գործընթացի մեկնակետը։", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["Վալախիական ապստամբությունը. Իփսիլանտիի անցումը Պրուտով և Վլադիմիրեսկուի ապստամբությունը", "67d46a98"], "d": ["Ռուսական բանակի գեներալ Ալեքսանդր Իփսիլանտին, Ֆիլիկի Էթերիայի անունից անցնելով Պրուտը, փորձեց Վալախիայում և Մոլդովայում սկսել հույների համընդհանուր ապստամբություն. նույն օրերին Թուդոր Վլադիմիրեսկուն ևս շարժման մեջ դրեց տեղացի գյուղացիներին։ Երկու շարժումները չկարողացան միավորվել. Իփսիլանտիի՝ թուրքերի դեմ միասին կռվելու կոչին Վլադիմիրեսկուն պատասխանեց. «Ես ոչ թե թուրքերի, այլ հույների դեմ եմ ապստամբել», և շուտով սպանվեց Իփսիլանտիի մարդկանց կողմից։ Ապստամբությունը մայիսին ճնշվեց օսմանյան ուժերի կողմից, սակայն ֆանարիոտ վոյևոդների կարգը վերջ գտավ, և ապստամբության կրակը ցատկեց Մորեա։", "64b96ac8"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["Երկրորդ Սաուդյան պետության հիմնումը Ռիադում", "34dad3bd"], "d": ["1818 թվականին Դիրիյայի անկումից և Սաուդյան առաջին պետության կործանումից վեց տարի անց Թուրքի բին Աբդուլլահը եգիպտական կայազորները դուրս մղեց Նեջդից և Ռիադ կենտրոնով հիմնեց սաուդյան նոր էմիրություն։ Նոր կառույցը, խուսափելով Հիջազ տարածվելուց, նախընտրեց մնալ Նեջդում և հեռու մնաց օսմանա-եգիպտական ուժերի հետ ուղղակի բախումից։ Այս երկրորդ պետությունը տևելու էր մինչև դարի վերջը և կազմելու էր այսօրվա Սաուդյան Արաբիայի հիմնադրմանը տանող շղթայի երկրորդ օղակը։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Դիրիյա (Նեջդ)։", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["Աքքերմանի պայմանագիրը. զիջումներ Սերբիային և իշխանություններին", "c75f15d0"], "d": ["Ենիչերական օջախի վերացումից անմիջապես հետո առանց բանակի մնացած Օսմանյան պետությունը ռուսական ուլտիմատումի առջև ստիպված եղավ ընդունել ծանր պայմաններով պայմանագիր։ Հաստատվեց Սերբիային խոստացված ինքնավարությունը, ընդունվեց, որ Վալախիայի և Մոլդովայի վոյևոդները չեն կարող պաշտոնանկ արվել առանց Ռուսաստանի համաձայնության, ռուսական առևտրական նավերին նեղուցներում տրվեց լիակատար ազատություն։ Երկու տարի անց Բարձր դուռը հունական հարցի պատճառով հայտարարեց, որ չի ճանաչում պայմանագիրը, և Ռուսաստանը դա համարելու էր պատերազմի առիթ։", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["Թիմարային համակարգի վերացումը", "84d5d1d6"], "d": ["Ենիչերական օջախի վերացումից մեկ տարի անց Ռումելիայի և Անատոլիայի հիսուներեք սանջակներում գտնվող մոտ 5.200 թիմարակիր սիփահիներ իրենց թիմարային եկամուտներով վերածվեցին «Ասաքիր-ի Մանսուրե» (նոր կանոնավոր բանակի) հեծելազորի։ Այսպիսով փաստացի ավարտվեց թիմարային ռեժիմը, որը չորս դար եղել էր օսմանյան հողային, հարկային և ռազմական կարգի ողնաշարը։ Ազատված թիմարները փոխանցվեցին գանձարանին, և ճանապարհ բացվեց կենտրոնական ռոճիկով բանակի ու դրամական հարկի համակարգին անցնելու համար։", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["Կայսերական բժշկական դպրոցի (Թըփհանե-ի Ամիրե) հիմնումը. ժամանակակից բժշկական կրթության սկիզբը", "ac3e57c0"], "d": ["Նորաստեղծ «Ասաքիր-ի Մանսուրե» բանակի համար բժիշկներ և վիրաբույժներ պատրաստելու նպատակով գլխավոր բժիշկ Մուստաֆա Բեհչեթ էֆենդիի առաջարկով Շեհզադեբաշիում բացվեց Թըփհանե-ի Ամիրեն։ Դասերը կազմակերպվեցին եվրոպական ուսումնական ծրագրի համաձայն, և սկզբում դասավանդումը կատարվում էր ֆրանսերենով. մի քանի տարի անց հիմնվեց նաև Ջերրահհանե-ի Ամիրեն (վիրաբուժական դպրոցը), և երկու հաստատությունները միավորվեցին։ Թուրքիայում ժամանակակից բժշկական ուսուցման սկիզբը համարվող այս դպրոցը ընդունվում է որպես այսօրվա Ստամբուլի բժշկական ֆակուլտետի ակունքը։", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["1828-1829 թվականների օսմանա-ռուսական պատերազմի սկիզբը", "9dff4e05"], "d": ["Նավարինում նավատորմի այրվելուց և Բարձր դռան՝ Աքքերմանի պայմանագիրը չճանաչելու մասին հայտարարելուց հետո Ռուսաստանը պատերազմ սկսեց միաժամանակ երկու ճակատից։ Քանի որ ենիչերական օջախը նոր էր վերացվել, իսկ նոր բանակը դեռ ձևավորման փուլում էր, օսմանյան պաշտպանությունը սկզբից թույլ էր. ռուսները, անցնելով Դանուբը, արևելքում վերցրին Կարսը և Ախալցխան։ Մեկ տարում մինչև Էդիրնե առաջ շարժված ռուսական բանակը պարտադրելու էր 1829 թվականի Էդիրնեի պայմանագրի ծանր պայմանները և Հունաստանի անկախությունը։", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["Առաջին պայմանագիրը Ամերիկայի Միացյալ Նահանգների հետ", "d737516f"], "d": ["Տարիներ տևած շփումներից հետո ստորագրված առևտրի և նավագնացության պայմանագրով ԱՄՆ-ը Օսմանյան երկրում ձեռք բերեց առավել բարենպաստության ազգի կարգավիճակ և նեղուցներով առևտրային անցման իրավունք։ Առանձին գաղտնի հոդվածը նախատեսում էր, որ Օսմանյան պետությունն իր ցանկության դեպքում կարող է ամերիկյան նավաշինարաններում նավեր կառուցել տալ, պատրաստի նավեր և փայտանյութ գնել. ԱՄՆ Սենատը վավերացրեց պայմանագիրը, բայց այս գաղտնի հոդվածը մերժեց 27 ձայնով ընդդեմ 18-ի։ Սակայն նավերի ճանապարհը, այնուամենայնիվ, չփակվեց. Henry Eckford-ը (Հենրի Էքֆորդ) 1831 թվականին իր բերած նավը վաճառեց Օսմանյան պետությանը, իսկ Այնալըքավաքում աշխատող ամերիկացի վարպետները նավատորմին նոր տիպի նավեր տվեցին։ Այս պայմանագիրը դարձավ Եվրոպայից դուրս գտնվող պետության հետ Օսմանյան պետության հաստատած առաջին համապարփակ հարաբերության փաստաթուղթը։", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["Բաղդադում քյոլեմենների կառավարմանը վերջ դնելը", "7e1d38a3"], "d": ["Կենտրոնացման քաղաքականություն վարող Մահմուդ II-ը ապստամբ հռչակեց Բաղդադի կուսակալ Դավուդ փաշային, որը պահանջված գումարը չէր ուղարկում և սպանել էր տվել կենտրոնից եկած պաշտոնյային։ Ալի Ռիզա փաշայի հրամանատարությամբ ուժը իննսուն օր տևած պաշարումից հետո գրավեց քաղաքը, և քյոլեմենները գրեթե ամբողջությամբ վերացվեցին։ Այսպիսով ավարտվեց 1704 թվականից տևող կիսաանկախ քյոլեմենյան կառավարումը, և Իրաքը վերստին ուղղակիորեն ենթարկվեց կենտրոնին։", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["Ռազմական ուսումնարանի (Մեքթեբ-ի Հարբիյե) հիմնումը Մաչկա զորանոցում", "bf31c7d9"], "d": ["«Ասաքիր-ի Մանսուրե-ի Մուհամմեդիյե» բանակին եվրոպական եղանակով պատրաստված սպաներ ապահովելու նպատակով Մաչկա զորանոցում բացվեց ռազմական գիտությունների ուսումնարանը (Մեքթեբ-ի Ֆյունուն-ը Հարբիյե)։ Ուսանողներին դասավանդվում էին մաթեմատիկա, քարտեզագրություն, ամրաշինություն և օտար լեզու. շուտով Վիեննա և Փարիզ ուսանողներ ուղարկելով՝ կադրերն ուժեղացվեցին։ Այս դպրոցը դարձավ օսմանյան բանակում դպրոցական սպաների ավանդույթի, հետևաբար նաև XIX դարի վերջին հանդես եկող նոր զինվորական-մտավորական սերնդի ծննդավայրը։", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["Տրիպոլիտանիայի ուղղակի ենթարկումը կենտրոնին. Կարամանլի հարստության վերջը", "faabcb96"], "d": ["Կարամանլի ընտանիքի ներսում գահակալական կռիվների և 1830 թվականին Ֆրանսիայի կողմից Ալժիրի օկուպացիայից հետո ուժեղացած եվրոպական ճնշման պայմաններում Բարձր դուռը ուղղակիորեն միջամտեց Տրիպոլիտանիային։ Ստամբուլից ուղարկված նավատորմը մտավ քաղաք, Կարամանլիների վերջին բեյը պաշտոնանկ արվեց և բերվեց Ստամբուլ, իսկ էյալեթը հանձնվեց կենտրոնից նշանակված կուսակալի։ 124-ամյա դինաստիական շրջանն ավարտվեց, իսկ Հյուսիսային Աֆրիկայում Օսմանյան պետության ուղղակիորեն կառավարած վերջին հողակտորն ամրապնդվեց։", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["Դեֆթերդարության վերացումը և Ֆինանսների նախարարության հիմնումը", "89f8125e"], "d": ["Վերացվեց դասական օսմանյան ֆինանսական կարգի գլուխ դեֆթերդարի պաշտոնը, և հիմնվեց եվրոպական ձևի նախարարություն՝ Ֆինանսների նախարարությունը (Մալիյե Նեզարեթի), իսկ ցրված գանձարանները հավաքվեցին մեկ ձեռքում։ Նույն տարի Բարձր դռան մյուս միավորները ևս վերակազմավորվեցին նախարարություն անվան տակ, և անցում կատարվեց ժամանակակից նախարարների խորհրդի կառուցվածքին։ Այս կարգավորումը կարևորագույն քայլերից մեկն էր, որ նախապատրաստեց մեկ տարի անց հրապարակվելիք Թանզիմաթի հրովարտակի վարչական ենթակառուցվածքը։", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["Անգլիացիների հաստատվելը Ադենում", "ddbd556b"], "d": ["Անգլիան, հենվելով 1802 թվականին Լահեջի սուլթան Ահմեդ բին Աբդ ալ-Քարիմի հետ ստորագրած առևտրի և բարեկամության համաձայնագրի վրա, զորք իջեցրեց Ադենի նավահանգիստ և քաղաքը վերցրեց իր վերահսկողության տակ։ Կարմիր ծովի մուտքը հսկող այս նավահանգիստը, որպես Հնդկաստանի ճանապարհի ածխի մատակարարման հենակետ, վերածվեց բրիտանական կայսերական ռազմավարության առանցքային կետի։ Թեև Օսմանյան պետության հավակնությունը Եմենի նկատմամբ թղթի վրա շարունակվեց, հարավային ափին նրա փաստացի տիրապետությունն այս թվականից հետո այլևս չվերադարձավ։", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["Վերադարձ Թիհամայի ափ. Հոդեյդայի, Զաբիդի և Մոխայի վերցնելը", "353982d2"], "d": ["1840 թվականին եգիպտական բանակի հեռանալով անտեր մնացած Եմենի ափ Մեքքայի շարիֆի վերահսկողության ներքո Թևֆիկ փաշայի հրամանատարությամբ ուժերը ափ իջնելով՝ Հոդեյդայի, Զաբիդի և Մոխայի նավահանգիստները ենթարկեցին օսմանյան կառավարմանը։ Թեև ցանկացան առաջ շարժվել մինչև Սանաա, բնակչության դիմադրության պատճառով վերադարձան Հոդեյդա. այսպիսով լեռնային շրջանները մնացին զեյդիական իմամներին, և օսմանյան տիրապետությունը քսաներեք տարի պահպանվեց միայն Թիհամայի շերտում։ Ներքին Եմենը հետ էր վերցվելու միայն 1872 թվականին՝ Ահմեդ Մուխթար փաշայի արշավանքով։", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["Բալթալիմանիի կոնվենցիան. օսմանա-ռուսական համատեղ հովանավորություն Վալախիայում և Մոլդովայում", "d3bb22e9"], "d": ["1848 թվականի հեղափոխությունների՝ Վալախիա և Մոլդովա տարածվելուց հետո օսմանյան և ռուսական ուժերը համատեղ գրավել էին իշխանությունները։ Բալթալիմանիում ստորագրված կոնվենցիայով որոշվեց, որ վոյևոդները ոչ թե ընտրությամբ, այլ փադիշահի կողմից նշանակվեն յոթ տարի ժամկետով, և երկու պետությունները տարածաշրջանում հաստատեն համատեղ վերահսկողություն։ Համաձայնությունը, պահպանելով Օսմանյան պետության թղթի վրա եղած գերիշխանությունը, Ռուսաստանին տվեց փաստացի գործընկերության իրավունք և արագացրեց Դանուբյան իշխանությունների անջատումը Օսմանյան պետությունից։", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["Հունգարացի փախստականների հարցը. Կոշուտի և նրա ընկերների ապաստանը Օսմանյան պետությունում", "1c7d7ef4"], "d": ["1848-1849 թվականների հունգարական հեղափոխության՝ ռուս-ավստրիական միջամտությամբ ճնշվելուց հետո Լայոշ Կոշուտը և հազարավոր հունգարացի ու լեհ փախստականներ ապաստանեցին օսմանյան հողերում։ Ավստրիան և Ռուսաստանը խստորեն պահանջեցին փախստականների հանձնումը. Բարձր դուռը Անգլիայի և Ֆրանսիայի աջակցությամբ մերժեց հանձնումը և խմբին բնակեցրեց Քյոթահիայում։ Կոշուտի շրջապատն այստեղ մնաց մոտ տասնութ ամիս, հարյուրավոր փախստականներ իսլամ ընդունելով անցան օսմանյան ծառայության։ Դեպքը համարվեց հազվագյուտ դիվանագիտական հաղթանակներից մեկը, որը բարձրացրեց Թանզիմաթի դարաշրջանի Օսմանյան պետության հեղինակությունը եվրոպական հասարակական կարծիքում։", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["Էնջումեն-ի Դանիշի հիմնումը. Ստամբուլում առաջին օսմանյան ակադեմիան", "6fda1365"], "d": ["Հանրակրթության ընդհանուր խորհրդի (Մեջլիս-ի Մաարիֆ-ի Ումումիյե) որոշմամբ հիմնված Էնջումեն-ի Դանիշը (Գիտության ժողով) թուրքերենով գիտական և դասագրքեր պատրաստելու համար ստեղծված առաջին օսմանյան գիտությունների ակադեմիան է։ Այն 1851 թվականի հուլիսի 18-ին հանդիսավոր կերպով բացվեց Դարյուլմաարիֆի շենքում. նրա տեղացի և օտարերկրյա անդամների թվում էր նաև Ահմեդ Ջևդեթ փաշան։ Թեև կարճակյաց էր, Ջևդեթ փաշայի «Պատմությունը» (Թարիհ) և «Օսմանյան քերականությունը» (Կավաիդ-ի Օսմանիյե) այս հաստատության արդյունքն էին, և այն համարվեց թուրքերենի՝ գիտության լեզու դառնալու անկյունաքարը։", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["Օլթենիցայի հաղթանակը. առաջին օսմանյան հաջողությունը Դանուբյան ճակատում", "a660ad2f"], "d": ["Ղրիմի պատերազմի սկզբնական փուլում սերդարը (գերագույն հրամանատար) Օմեր Լյութֆի փաշան, անցնելով Դանուբը, Օլթենիցայում ծանր կորուստներով հետ մղեց ռուսական ուժերին։ Հաղթանակը, հենց պատերազմի սկզբում կանգնեցնելով ռուսական առաջխաղացումը, Եվրոպային ցույց տվեց Թանզիմաթից հետո վարժանքներով ձեռք բերված օսմանյան բանակի ուժը։ Այս հաջողությունը նախապատրաստեց հոգեբանական հող, որը հեշտացրեց Անգլիայի և Ֆրանսիայի՝ Օսմանյան պետության կողքին պատերազմի մեջ մտնելու որոշումը։", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["Դաշինքի պայմանագիր Ստամբուլում Անգլիայի և Ֆրանսիայի հետ", "04809278"], "d": ["Ղրիմի պատերազմում Ռուսաստանի դեմ Օսմանյան պետության, Անգլիայի և Ֆրանսիայի միջև ստորագրված դաշնակցային պայմանագիրը սահմանում էր, որ երեք պետությունները վարելու են համատեղ գործողություններ, և դաշնակիցները չեն կնքի առանձին հաշտություն մինչև պատերազմի ավարտը։ Այսպիսով Օսմանյան պետությունն իր պատմության մեջ առաջին անգամ եվրոպական մեծ պետությունների հետ որպես հավասար կողմ ռազմական դաշինքի մեջ մտավ։ Այս պայմանագիրը նաև ստեղծեց իրավական հիմք, որ երկու տարի անց Փարիզում Օսմանյան պետությունը պաշտոնապես ընդունվի եվրոպական պետությունների համակարգ։", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["Ստամբուլի քաղաքային վարչության (Շեհրեմանեթի) հիմնումը. առաջին ժամանակակից քաղաքապետական կազմակերպությունը", "be4af27f"], "d": ["Ղրիմի պատերազմի ժամանակ Ստամբուլում կուտակված դաշնակից զինվորները և աճող բնակչությունից առաջացած ենթակառուցվածքային ճգնաժամը բացահայտեցին կադիության վրա հիմնված դասական քաղաքային կառավարման անբավարարությունը։ Եվրոպական օրինակներով հիմնված Շեհրեմանեթիով մաքրությունը, գների սահմանումը (նարհ), շուկայի վերահսկողությունը և շինարարական գործերը հավաքվեցին մեկ ձեռքում. հաջորդ տարի Բեյօղլու-Ղալաթիայում որպես փորձնական շրջան ստեղծվեց Վեցերորդ քաղաքապետական շրջանը։ Այս քայլը համարվում է Օսմանյան պետությունում ժամանակակից քաղաքապետական կառավարման սկիզբը։", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["Փարիզի պայմանագիրը. Ղրիմի պատերազմի վերջը և Օսմանյան պետության ընդունումը եվրոպական պետությունների համակարգ", "4aee0e2a"], "d": ["Ղրիմի պատերազմն ավարտած Փարիզի պայմանագրով Օսմանյան պետությունը հռչակվեց եվրոպական պետությունների իրավունքի հավասար անդամ, և նրա տարածքային ամբողջականությունն առնվեց մեծ պետությունների համատեղ երաշխիքի տակ։ Սև ծովը չեզոքացվեց, անվավեր ճանաչվեց ուղղափառ հպատակների նկատմամբ հովանավորության այն հավակնությունը, որը Ռուսաստանը ձեռք էր բերել Քյուչուկ Կայնարջայից ի վեր, Բեսարաբիայի հարավը (Կիլիայի, Կահուլի, Իզմայիլի և Բոլգրադի կազաները) տրվեց Մոլդովային։ Սակայն նույն պայմանագիրը, Իսլահաթի (բարեփոխումների) հրովարտակը վերածելով միջազգային պարտավորության, դուռ բացեց նաև ներքին գործերին միջամտության համար։", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["Դոլմաբահչե պալատի բացումը. կառավարման կենտրոնի տեղափոխումը Թոփքափըից", "71ad26d0"], "d": ["1842 թվականին Աբդուլմեջիդի կողմից Բալյան ընտանիքին պատվիրված պալատը բացվեց տասնչորսամյա շինարարությունից հետո, և պետության կառավարման կենտրոնը չորս դարի Թոփքափըից տեղափոխվեց Բոսֆորի ափ։ Եվրոպական ոճով, բյուրեղապակյա աստիճանավանդակով և Հանդիսությունների (Մուայեդե) դահլիճով պալատը դարձավ Թանզիմաթի արևմտականացման հավակնության քարեղեն արտահայտությունը։ Մինչդեռ նրա հսկայական ծախսը դարձավ այն տարիների ամենաշատ քննադատված հոդվածներից մեկը, երբ օսմանյան ֆինանսները մտնում էին արտաքին փոխառությունների պարույրի մեջ։", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["Վալախիայի և Մոլդովայի միավորումը Կուզայի իշխանության ներքո. Ռումինիայի ծնունդը", "baef4da5"], "d": ["Փարիզի պայմանագրից հետո կազմակերպված ընտրություններում երկու իշխանություններն էլ վոյևոդ ընտրեցին գնդապետ Ալեքսանդրու Իոան Կուզային՝ իրականացնելով փաստացի միավորումը։ Թեև Բարձր դուռը և Ավստրիան դեմ էին դրան, Ֆրանսիայի աջակցած կատարված փաստը ստիպված եղան ընդունել։ Թղթի վրա Օսմանյան պետությանը ենթակա մնացած այս միությունը 1862 թվականին ստանալու էր Ռումինիա անունը և 1877 թվականին միակողմանիորեն հռչակելու էր անկախությունը. դա շրջադարձային կետ է Դանուբի երկայնքով օսմանյան տիրապետության կազմալուծման մեջ։", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["Կուլելիի դեպքը. Ստամբուլում Աբդուլմեջիդի դեմ առաջին հեղաշրջման փորձը", "e3653b21"], "d": ["Թանզիմաթի քաղաքականությանը և Իսլահաթի հրովարտակով ոչ մահմեդականներին տրված հավասարությանը դեմ զինվորական-քաղաքացիական խառը գաղտնի ընկերությունը, մինչ ծրագրում էր գահընկեց անել փադիշահին, բռնվեց Քըլըչ Ալի փաշա մզկիթում ժողովի ժամանակ։ Մեղադրյալները դատվեցին Կուլելի զորանոցում, ուստի դեպքը կոչվեց այդ անունով. մահվան դատավճիռները փոխարինվեցին աքսորով։ Այն ընդունվում է որպես օսմանյան պատմության մեջ գաղափարական հիմնավորմամբ ստեղծված կազմակերպության ձեռնարկած առաջին պալատական հեղաշրջման փորձ։", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["Դրուզա-մարոնիական քաղաքացիական պատերազմը Լեռնային Լիբանանում և Դամասկոսի դեպքերը", "5595fdd6"], "d": ["1860 թվականի մայիսին Սիդոնի մոտ երկու դրուզի սպանությամբ բռնկված բախումները վերածվեցին լեռան ամենաարյունալի դրուզա-մարոնիական քաղաքացիական պատերազմի և հուլիսին տարածվեցին Դամասկոս՝ ավարտվելով հազարավոր քրիստոնյաների մահով։ Ֆրանսիայի զորք իջեցնելուց հետո Բարձր դուռը Ֆուադ փաշային արտակարգ լիազորություններով ուղարկեց տարածաշրջան. իրականացվեց խիստ պատժիչ գործողություն։ Դեպքերը առիթ դարձան եվրոպական միջամտության և ուղղակի պատճառը՝ Լիբանանի՝ հատուկ կարգավիճակ ստանալու։", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["«Թերջյուման-ը Ահվալ»-ի հրատարակության սկիզբը. Ստամբուլում առաջին մասնավոր թուրքերեն թերթը", "24792957"], "d": ["Ագյահ էֆենդիի հրատարակած և Շինասիի խմբագրած «Թերջյուման-ը Ահվալ»-ը առանց պետական աջակցության հրատարակված առաջին թուրքերեն թերթն է։ Առաջին համարի նախաբանում պաշտպանվում էր ժողովրդի՝ իր գործերի մասին խոսք ասելու իրավունքը. թերթը, հատվածաբար հրատարակելով Շինասիի «Բանաստեղծի ամուսնությունը», դուռ բացեց նաև ժամանակակից թուրք գրականության համար։ Օսմանյան պետությունում հասարակական կարծիքի հասկացության և ընդդիմադիր մամուլի ծնունդը կապում են այս թվականի հետ։", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["Լեռնային Լիբանանի կանոնադրությունը. Լիբանանին արտոնյալ մութասարիֆության կարգավիճակ", "bf375603"], "d": ["1860 թվականի կոտորածներից հետո մեծ պետությունների ճնշմամբ պատրաստված կանոնադրությունը Լեռնային Լիբանանը դարձրեց արտոնյալ մութասարիֆություն՝ ուղղակիորեն Բարձր դռանը ենթակա և դավանանքների հավասարակշռությամբ կազմված վարչական խորհրդով կառավարվող։ Պայման դրվեց, որ մութասարիֆը լինի օսմանյան հպատակ կաթոլիկ քրիստոնյա, և նրա նշանակումը ներկայացվի մեծ պետությունների հաստատմանը. առաջին մութասարիֆը դարձավ Դավուդ փաշան։ Այս կարգը տևելու էր մինչև 1915 թվականը և կազմելու էր ժամանակակից Լիբանանի պետության միջուկը։", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["Աբդուլմեջիդի մահը և սուլթան Աբդուլազիզի գահակալումը", "27204d7c"], "d": ["Իր քսաներկուամյա կառավարման ընթացքում Թանզիմաթի և Իսլահաթի հրովարտակները ստորագրած Աբդուլմեջիդի՝ թոքախտից մահանալուց հետո գահ բարձրացավ նրա եղբայր Աբդուլազիզը։ Նոր փադիշահը առաջին տարիներին խնայողության միջոցներով և պարզ ապրելակերպով հույս ներշնչեց. նավատորմը դարձրեց աշխարհի նշանավոր ուժերից մեկը։ Սակայն նրա կառավարման վերջում կուտակվող ծանր արտաքին պարտքը, 1875 թվականի սնանկությունը և բալկանյան ապստամբությունները հող էին նախապատրաստելու 1876 թվականի գահընկեցության համար։", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["Միացյալ իշխանությունները ստացան Ռումինիա անունը", "d960e3fc"], "d": ["1859 թվականին Կուզայի կրկնակի ընտրությամբ փաստացի միավորված Վալախիան և Մոլդովան 1862 թվականին իրենց խորհրդարաններն ու կառավարությունները Բուխարեստում միավորելով մեկ հարկի տակ՝ պաշտոնապես ստացան Ռումինիա անունը։ Թեև Օսմանյան պետությունը իրավականորեն պահպանեց գերիշխողի կարգավիճակը և տարեկան հարկը, իշխանապետության նկատմամբ վերահսկողությունը փաստացի կորցրեց։ Դանուբից հյուսիս չորս դարի օսմանյան ազդեցության վախճանը խորհրդանշվում է այս թվականով։", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["Սուակինի, Մասսաուայի և Դահլաքի միացումը Եգիպտոսին", "a0924860"], "d": ["1846 թվականին սուլթան Աբդուլմեջիդի կողմից Եգիպտոսի խեդիվ Մեհմեդ Ալի փաշային Սուակինի հետ սալյանե (եկամտի հատկացում) տրված Մասսաուան խեդիվ Իսմայիլ փաշայի օրոք Դահլաքի և Սուակինի հետ ներառվեց Եգիպտոսի կալվածքների մեջ և կազմակերպվեց կայմակամության կարգավիճակով։ Այսպիսով Կարմիր ծովի աֆրիկյան ափի այս երեք նավահանգիստները, իրավականորեն մնալով օսմանյան հող, վարչականորեն Բարձր դռնից ուղղակիորեն անցան Կահիրեին՝ մտնելով նույն վասալ շերտի մեջ, ինչ հարևան Եգիպտոսն ու Սուդանը։", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["Կրետեի ապստամբության սկիզբը (1866-1869)", "3679b861"], "d": ["Հունաստանի բացահայտ աջակցությամբ կղզում բռնկված լայնածավալ ապստամբությունը Կրետեի հույների էնոսիսի (Հունաստանին միանալու) պահանջը առաջին անգամ դարձրեց միջազգային հարց։ Երեք տարի տևած դժվարին լեռնային պատերազմը օսմանյան բանակին ծանր կորուստներ պատճառեց և մեծ արձագանք ունեցավ եվրոպական հասարակական կարծիքում։ Ապստամբությունը հնարավոր եղավ մարել միայն 1868 թվականին, երբ Ալի փաշան, գնալով կղզի, ուժի մեջ դրեց լայն արտոնություններ տվող կանոնադրությունը։", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["Բելգրադից և Սերբիայի բերդերից օսմանյան վերջին կայազորների դուրսբերումը", "b34217db"], "d": ["Մեծ պետությունների ճնշման և իշխան Միհաիլոյի համառ պահանջի հետևանքով Բարձր դուռը համաձայնեց դատարկել Սերբիայում իր ձեռքում մնացած վերջին ռազմական հենակետերը. 1867 թվականի ապրիլի 18-ին Բելգրադի բերդում օսմանյան դրոշն իջեցվեց, և բանալիները հանձնվեցին իշխանին։ Այսպիսով ավարտվեց 1521 թվականից տևող փաստացի օսմանյան ռազմական ներկայությունը, և վերացավ Սերբիայի՝ դեպի անկախություն տանող ճանապարհի վերջին մեծ խոչընդոտը։ Փադիշահի գերիշխանությունը հանգեցվեց միայն խորհրդանշական դրոշի և հարկի հարցի։", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["Եգիպտոսի կուսակալներին խեդիվի տիտղոսի շնորհումը", "09e10c12"], "d": ["Կավալացու հարստության երրորդ սերնդի Իսմայիլ փաշայի ակտիվ լոբբինգի և Ստամբուլ հոսեցրած գումարների արդյունքում Եգիպտոսի կուսակալին տրվեց խեդիվի տիտղոսը, որը շեշտում էր նրա գերակայությունը մյուս կուսակալների նկատմամբ։ Նույն տարիներին գահաժառանգության կարգը ևս փոխվեց՝ հորից որդի անցնելու սկզբունքով, և Եգիպտոսին ճանաչվեցին ինքնիշխան բնույթի լիազորություններ, ինչպիսիք են արտաքին փոխառությունը, շքանշան շնորհելը և հյուպատոսություններ ունենալը։ Այս քայլերը Օսմանյան պետությունից Եգիպտոսի իրավական անջատումը արագացրած շղթայի առաջին օղակն են։", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["Կրետեի կանոնադրությունը. լայն վարչական արտոնություններ կղզուն", "12052262"], "d": ["Եռամյա ապստամբությունը վերջացնելու նպատակով մեծ վեզիր Ալի փաշան անձամբ անցավ կղզի, և փադիշահի հաստատմամբ հրապարակված կանոնադրությամբ կրետացիներին տրվեցին խառը վարչական խորհուրդներ, տեղական դատարաններ, հունարենի կիրառում պաշտոնական գործառնություններում և հարկային դյուրություններ։ Այս կարգավորումը օսմանյան տիրապետությունը կղզում պահեց ևս երեսուն տարի։ Սակայն քրիստոնյա բնակչությանը տրված արտոնությունները թուլացրին մահմեդական կրետացիների դիրքը և սերմանեցին 1896-1898 թվականների ճգնաժամի սերմերը։", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["Պետական խորհրդի (Շուրա-ի Դևլեթ) բացումը. օսմանյան պետական խորհրդի հիմնումը", "70b16497"], "d": ["1868 թվականի մարտի 5-ի իրադեով Մեջլիս-ի Ահքամ-ը Ադլիյեն բաժանվեց երկուսի՝ վարչական-օրենսդրական գործերը թողնվեցին Պետական խորհրդին, իսկ դատական գործերը՝ Դիվան-ը Ահքամ-ը Ադլիյեին. հաստատությունը հանդիսավոր կերպով բացվեց Բարձր դռանը, և նրա առաջին նախագահ դարձավ Միդհաթ փաշան։ Նրան հանձնարարվեց պատրաստել օրինագծեր, լուծել վարչական վեճերը և վարել պաշտոնյաների դատավարությունները։ Մահմեդական և ոչ մահմեդական անդամներից խառը կազմով այն համարվում է Օսմանյան պետությունում իշխանությունների տարանջատման գաղափարի առաջին ինստիտուցիոնալ կիրառությունը։", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["Սուեզի ջրանցքի բացումը. Եգիպտոսի վրայով Հնդկաստանի ճանապարհի կրճատումը", "377ccd04"], "d": ["1859 թվականին սկսված շինարարությունը տևեց տասը տարի, և Միջերկրական ծովը Կարմիր ծովի հետ կապող 163 կիլոմետրանոց ջրանցքը շուքով հանդիսավոր արարողությամբ գործարկվեց։ Երբ Եվրոպան Հնդկաստանի հետ կապող ճանապարհը հազարավոր մղոններով կրճատվեց, Եգիպտոսը մեկեն դարձավ համաշխարհային առևտրի առանցքային կետը։ Այս աշխարհառազմավարական արժեքը լինելու էր հիմնական պատճառը, որ ջրանցքի բացումից տասներեք տարի անց Անգլիան գրավի Եգիպտոսը. իսկ ջրանցքի՝ Եգիպտոսի վրա բարդած պարտքը խեդիվությունը հասցնելու էր սնանկության։", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["Բուլղարական էկզարխատի հիմնումը. բուլղարական եկեղեցու անջատումը Ֆանարից", "33a8272c"], "d": ["Փադիշահի հրովարտակով հիմնվեց հունական պատրիարքությունից առանձին, ինքնուրույն բուլղարական եկեղեցի (էկզարխատ), և որոշումը, թե որ կազաները կենթարկվեն էկզարխատին, թողնվեց ժողովրդական քվեարկությանը։ Թեև Բարձր դուռն այս քայլն արել էր հունական ազդեցությունը կոտրելու համար, արդյունքը հակառակը ստացվեց. եկեղեցին վերածվեց բուլղարական ազգային ինքնության և Մակեդոնիայի նկատմամբ բուլղարական հավակնության կազմակերպված կենտրոնի։ Այսպիսով դրվեց Բալկաններում բուլղարա-հունա-սերբական մրցակցության և 1876 թվականի ապստամբությունների ինստիտուցիոնալ հիմքը։", "ce8f108b"]},
"OLAYLAR_EK5:1871-01-01:0":{"b": ["Ասիրի անցումը ուղղակի կառավարման", "4559e099"], "d": ["Սուեզի ջրանցքի բացմամբ Կարմիր ծովի ռազմավարական արժեքի աճից հետո պարզ դարձավ, որ Եմեն տանող ցամաքային ճանապարհի կենտրոնում գտնվող Ասիրի լեռները չի կարելի թողնել առանց վերահսկողության։ Եմենյան արշավանքի դուրս եկած Ռեդիֆ փաշայի ուժերը, մտնելով Աբհա, շրջանն ուղղակիորեն ենթարկեցին օսմանյան կառավարմանը, և հիմնվեց Ասիրի սանջակը։ Լեռնային աշխարհագրության և Իդրիսիների ազդեցության պատճառով այս տիրապետությունը երբեք լիովին չարմատավորվեց։", "eb2bbdad"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["Միդհաթ փաշայի նեջդյան արշավանքը. օսմանյան տիրապետության վերահաստատումը Լահսայում", "7db51461"], "d": ["Բաղդադի կուսակալ Միդհաթ փաշան, օգտվելով Սաուդյան ընտանիքի ներսում գահակալական կռվից, զորք ուղարկեց Պարսից ծոցի արևմտյան ափ և Լահսայի շրջանը Նեջդի սանջակ անունով միացրեց Բասրայի վիլայեթին։ Աբդուլլահ բին Ֆեյսալը նշանակվեց մութասարիֆ, և օսմանյան տիրապետությունը հաստատվեց թղթի վրա։ Արշավանքի նպատակն էր կանգնեցնել անգլիական ազդեցության տարածումը ծոցում. նույն տարի այն հանգեցրեց նաև Կատարի անցմանը օսմանյան վերահսկողության տակ։", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["Մեծ վեզիր Ալի փաշայի մահը. Թանզիմաթի կադրերի վերջը", "1cf0141c"], "d": ["1869 թվականին Ֆուադ փաշայի մահից հետո Թանզիմաթի քաղաքականությունը միայնակ իր ուսերին կրող Ալի փաշայի մահով սպառվեց այն վարպետ դիվանագետների սերունդը, որը երեսուն տարի ղեկավարել էր պետության արտաքին քաղաքականությունը։ Նրան փոխարինած Մահմուդ Նեդիմ փաշայի ռուսամետ և կամայական կառավարումը ամրապնդեց Աբդուլազիզի անձնական իշխանությունը։ Ալի փաշայի մահից հետո հինգ տարվա ընթացքում ֆինանսները սնանկացան, Բալկանները ապստամբեցին, և գահի փոփոխությունը դարձավ անխուսափելի։", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["Օսմանյան վերահսկողության հաստատումը Կատարում", "3b453165"], "d": ["Անգլիական ճնշման տակ գտնվող շեյխ Քասիմ բին Սանիի հրավերով օսմանյան ուժերը իջան Կատարի թերակղզի, և 1871 թվականի աշնանը տարածաշրջանում հաստատվեց օսմանյան վերահսկողություն։ Կատարը կազմակերպվեց որպես Նեջդի սանջակին ենթակա կազա, իսկ շեյխը նշանակվեց կայմակամ։ Այս քայլը դարձավ Միդհաթ փաշայի՝ ծոցում Անգլիայի դեմ վարած առաջխաղացման քաղաքականության ամենակոնկրետ ձեռքբերումը. օսմանյան դրոշը թերակղզում ծածանվեց մինչև 1913 թվականը։", "823711c3"]},
"OLAYLAR_EK5:1871-10-24:0":{"b": ["Թունիսին ժառանգական իշխանության ֆիրման. բեյությունը՝ Մեհմեդ Սադըք փաշայի ընտանիքին", "1509ebb0"], "d": ["Պրուսիայից Ֆրանսիայի կրած պարտությունից օգտվելով՝ Թունիսի բեյ Մեհմեդ Սադըք փաշայի կողմից Ստամբուլ ուղարկված Հայրեդդին փաշայի ջանքերով տրված ֆիրմանով Թունիսը, անմիջականորեն Ստամբուլին ենթակա մնալու պայմանով, ժառանգական կարգով տրվեց Մեհմեդ Սադըք փաշային և նրա սերունդներին։ Առանց փադիշահի թույլտվության պատերազմի և խաղաղության բանակցություններ չպետք է վարվեին, երկրից ոչ մի հող չպետք է տրվեր ուրիշին, և պետք է կատարվեր Օսմանյան պետության զինվորների պահանջը։ Ֆրանսիան չճանաչեց ֆիրմանը. տասը տարի անց նա օկուպացրեց Թունիսը։", "b72eabcc"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["Սանաայի վերցնելը. օսմանյան իշխանության վերահաստատումը Եմենում", "978e20a0"], "d": ["Սուեզի ջրանցքի բացմամբ Կարմիր ծովի ռազմավարական արժեքը մեծանալուց հետո Բարձր դուռը Եմեն ուղարկեց Ահմեդ Մուխթար փաշայի հրամանատարությամբ պահեստային դիվիզիայի (ֆիրքա-ի իհթիյաթիյե) բանակ։ Սանաայի վերցնելով Ներքին Եմենում, որը երկու դար փաստացի կորսված էր, վերահաստատվեց պետական իշխանությունը, և շրջանը դարձվեց վիլայեթ։ Սակայն զեյդիական իմամների դեմ պայքարը երբեք չավարտվեց. 1891, 1898 և 1904 թվականների ապստամբությունները կազմեցին Օսմանյան պետության ամենաթանկ և ամենաերկարատև ներքին ճակատը։ Նույն ամսաթվին միացած այլ վայրեր՝ Սանաա, Թաիզ։", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["Հերցեգովինայի ապստամբության սկիզբը. Արևելյան հարցի վերստին բորբոքումը", "571b18ec"], "d": ["Ծանր հարկերի և այանների ճնշման պատճառով Նևեսինյեի շրջակա քրիստոնյա գյուղացիների ապստամբությունը կարճ ժամանակում տարածվեց ամբողջ Հերցեգովինայում և սնվեց Սերբիայից ու Չեռնոգորիայից եկած կամավորներով։ Ապստամբությունը, հանգեցնելով Ավստրիայի և Ռուսաստանի բարեփոխումների պարտադրմանը, հաջորդ տարի հրահրեց բուլղարական ապստամբությունները և Սերբիայի ու Չեռնոգորիայի կողմից պատերազմի հայտարարումը։ Այսպիսով ճաքեց այն մեծ շղթայի առաջին օղակը, որը տանում էր 1877-78 թվականների (93-ի) պատերազմին և Բեռլինի պայմանագրով Բալկանների կորստին։", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["Օսմանյան ֆինանսների սնանկությունը. արտաքին պարտքի վճարումների կիսով չափ կրճատումը", "2cac2fa5"], "d": ["1854 թվականից ի վեր իրար հետևից վերցված փոխառությունները, Ղրիմի պատերազմի ծախսերը, պալատական շինարարությունները և 1873-74 թվականների անատոլիական սովը բյուջեի պակասուրդը վերածեցին հինգ միլիոն լիրայից ավելի անդունդի։ Մահմուդ Նեդիմ փաշայի կառավարությունը, հայտարարելով, որ պարտքի տոկոսների և մայր գումարի վճարումները հինգ տարով կիսով չափ կկրճատվեն, փաստացի մորատորիում հայտարարեց։ Եվրոպական բորսաներում մեծ վրդովմունք առաջացրած այս որոշումը սկիզբ դրեց մի գործընթացի, որը վեց տարի անց ավարտվելու էր Մուհառամի հրամանագրով և Օսմանյան պետական պարտքի վարչության (Դույուն-ը Ումումիյե) ստեղծմամբ։", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["Մուրադ V-ի գահընկեցությունը և Աբդուլհամիդ II-ի գահակալումը", "cffb2271"], "d": ["Աբդուլազիզի գահընկեցությունից հետո գահ բարձրացած Մուրադ V-ը իր հորեղբոր մահվան և Չերքեզ Հասանի դեպքի ցնցած հոգեկան առողջության պատճառով դարձավ անկարող պաշտոնավարելու. իննսուներեքօրյա կառավարման միայն յոթ օրն էր, որ նրա դատողությունը սթափ էր։ Շեյխ ուլ-իսլամի ֆեթվայով նա գահընկեց արվեց, և նրան փոխարինեց եղբայրը՝ Աբդուլհամիդ II-ը։ Նոր փադիշահը գահ բարձրացավ՝ Միդհաթ փաշային խոստանալով հռչակել սահմանադրական միապետությունը. սկսվում էր երեսուներեք տարի տևելիք մի դարաշրջան։", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["Թերսանեի (Նավաշինարանի) կոնֆերանսը. մեծ պետությունների՝ Բալկաններում բարեփոխումների պարտադրումը", "b5006a2c"], "d": ["Բալկանյան ճգնաժամը լուծելու նպատակով մեծ պետությունների՝ Ստամբուլում գումարած կոնֆերանսը պահանջեց Բուլղարիան բաժանել երկու ինքնավար վիլայեթի և Բոսնիա-Հերցեգովինայում կիրառել միջազգային վերահսկողությամբ բարեփոխումներ։ Բարձր դուռը, կոնֆերանսի բացման օրը թնդանոթի կրակոցներով հայտարարելով Հիմնական օրենքի (Կանուն-ը Էսասի) հռչակումը, փորձեց պարտադրանքներին դիմագրավել սահմանադրական բարեփոխմամբ։ Պատվիրակները, դա համարելով ժամանակ ձգել, 1877 թվականի հունվարի 20-ին ցրվեցին. չորս ամիս անց Ռուսաստանը պատերազմ հայտարարեց։", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["Առաջին Պատգամավորների պալատի (Մեջլիս-ի Մեբուսան) բացումը Դոլմաբահչեում", "429bb279"], "d": ["Հիմնական օրենքի համաձայն ընտրված 115 պատգամավորները 1877 թվականի մարտի 19-ին առաջին անգամ հավաքվեցին Դոլմաբահչե պալատի Հանդիսությունների դահլիճում կայացած արարողությամբ. այսպիսով օսմանյան պատմության մեջ սկսվեց ներկայացուցչական խորհրդարանի շրջանը։ Մահմեդական և ոչ մահմեդական պատգամավորները խստորեն հարցաքննեցին կառավարությանը, քննարկեցին պատերազմի ղեկավարումը և նախարարների պատասխանատվությունը։ Այս համարձակ ընդդիմությունը լինելու էր խորհրդարանի կյանքը կրճատած հիմնական պատճառը։", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["Պլևնայի պաշտպանության սկիզբը. Ղազի Օսման փաշայի դիմադրությունը", "0e04a878"], "d": ["1877-78 թվականների (93-ի) պատերազմում Դանուբն անցած ռուսական բանակի՝ դեպի Ստամբուլ ճանապարհը կտրելու նպատակով Վիդինից Պլևնա շարժված Օսման փաշան, ավանը ամրացնելով ամրություններով և խրամատներով, սկսեց հնգամսյա լեգենդար պաշտպանություն։ Իրար հաջորդող ռուս-ռումինական երեք խոշոր գրոհները ծանր կորուստներով հետ մղվեցին, և ցար Ալեքսանդր II-ի անձամբ ղեկավարած բանակը ստիպված եղավ անցնել պաշարման։ Պլևնան պատմության մեջ մտավ որպես XIX դարում օսմանյան բանակի ամենափայլուն պաշտպանական հաջողությունը։", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["Պլևնայի անկումը. Դանուբյան ճակատի փլուզումը", "185e7602"], "d": ["Հնգամսյա պաշարման ընթացքում պարենը սպառված Օսման փաշան Վիտ գետի վրայով ելանումի գործողություն ձեռնարկեց. վիրավորվելով և գերի ընկնելով՝ քաղաքը հանձնվեց։ Ռուս հրամանատարները գերի վերցրած փաշային ողջունեցին՝ վերադարձնելով նրա սուրը, և Օսման փաշային շնորհվեց «Ղազի» տիտղոսը։ Պլևնայի անկմամբ ռուսական բանակի առջև ճանապարհը բացվեց. երկու ամսում ընկան Սոֆիան, Ֆիլիպեն և Էդիրնեն, ռուսական առաջապահները հասան Եշիլքյոյ (Սան Ստեֆանո)։", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["Սոֆիայի օկուպացիան ռուսական ուժերի կողմից", "ef369d22"], "d": ["Պլևնայի անկումից հետո Բալկանները հաղթահարած ռուսական բանակը մտավ անպաշտպան մնացած Սոֆիա։ Քաղաքն այլևս չէր վերադառնալու օսմանյան կառավարման տակ. 1878 թվականի վերջին այն դառնալու էր ինքնավար Բուլղարական իշխանապետության, իսկ 1879 թվականին՝ փաստացի մայրաքաղաքը։ Քարտեզի վրա Սոֆիան այս թվականից սկսած դուրս է գալիս օսմանյան ուղղակի կառավարումից, անցնում ժամանակավոր ռուսական օկուպացիայի, ապա ինքնավար բուլղարական կառավարման տակ։", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["Էդիրնեի զինադադարը. զենքերի լռելը 1877-78 թվականների (93-ի) պատերազմում", "1f899180"], "d": ["Սոֆիայի, Ֆիլիպեի և Էդիրնեի իրար հետևից անկումից և ռուսական բանակի՝ Մարմարա ծովի ափերին մոտենալուց հետո Բարձր դուռը ստիպված եղավ զինադադար խնդրել։ Էդիրնեում ստորագրված զինադադարը Օսմանյան պետությանը ստիպեց ընդունել նախնական հաշտության պայմանները, ինչպիսիք էին Բուլղարիայի ինքնավարությունը, Չեռնոգորիայի, Սերբիայի և Ռումինիայի անկախությունը և ծանր ռազմատուգանքը։ Այս պայմանները մեկ ամիս անց Այաստեֆանոսում վերածվելու էին պայմանագրի տեքստի։", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["Աբդուլհամիդ II-ի կողմից Պատգամավորների պալատի անորոշ ժամանակով արձակումը", "e770b540"], "d": ["Պատերազմի աղետալի ավարտի համար կառավարությանն ու պալատին պատասխանատու համարող պատգամավորների խիստ քննադատությունների պատճառով Աբդուլհամիդ II-ը, հենվելով Հիմնական օրենքով իրեն տրված իրավասության վրա, անորոշ ժամանակով արձակեց խորհրդարանը։ Մոտ տասնմեկ ամիս աշխատած առաջին օսմանյան խորհրդարանը այսպիսով փակվեց, և սկսվեց երեսուն տարի տևելիք բռնապետական շրջանը (իստիբդադ)։ Խորհրդարանը կարողանալու էր կրկին հավաքվել միայն 1908 թվականի հեղափոխությունից հետո։", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["Այաստեֆանոսի (Սան Ստեֆանոյի) պայմանագիրը. Մեծ Բուլղարիայի նախագիծը", "2c7cc611"], "d": ["1877-78 թվականների (93-ի) պատերազմն ավարտած Այաստեֆանոսի պայմանագիրը ստեղծում էր մինչև Էգեյան ծով ձգվող և Մակեդոնիան ներառող հսկայական ինքնավար Բուլղարիա, ճանաչում էր Սերբիայի, Չեռնոգորիայի և Ռումինիայի անկախությունը, Ռուսաստանին թողնում էր Կարսը, Արդահանը, Բաթումը և Դողուբայազիտը, ինչպես նաև բարդում էր անհնար վճարվող ռազմատուգանք։ Ռուսաստանին Միջերկրական ծով իջեցնող այս տեքստը առաջացրեց Անգլիայի և Ավստրիայի բուռն վրդովմունքը։ Չկիրառված՝ այն չորս ամսվա ընթացքում վերաձևակերպվեց Բեռլինի կոնգրեսով. այնուամենայնիվ մնաց որպես օսմանյան Ռումելիայի վերջը հայտարարող փաստաթուղթ։", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-13:0":{"b": ["Կարսը, Արդահանը և Բաթումը զիջվեցին Ռուսաստանին. «էլվիյեի սելասե»", "99bdfad2"], "d": ["Բեռլինի պայմանագրով Օսմանյան պետությունը պատերազմական ռազմատուգանքի մի մասի դիմաց Ռուսաստանին զիջեց Կարսը, Արդահանը և Բաթումը. իսկ Սան Ստեֆանոյում Ռուսաստանին տրված Դողուբայազիթը և Ալաշկերտի հովիտը մնացին Օսմանյան պետությանը։ Բաթումը տրվեց որպես ազատ նավահանգիստ, բայց այդ կարգավիճակը կարողացավ պահել միայն մինչև 1886 թ.։ Ռուսները Կարսը դարձրին մարզ՝ ենթակա Թիֆլիս կենտրոնով Անդրկովկասի ընդհանուր նահանգապետությանը. երեք սանջակներից մինչև 100.000 հասնող բնակչություն ստիպված եղավ գաղթել Էրզրումի կողմը։ Նույն պայմանագրով Հարավային Բեսարաբիան (Կիլիա, Կահուլ, Բոլգրադ) Ռումինիայից վերադարձվեց Ռուսաստանին։", "867dda58"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["Բոսնիա-Հերցեգովինայի և Նովի Պազարի օկուպացիան Ավստրո-Հունգարիայի կողմից", "e5f901df"], "d": ["Բեռլինի պայմանագրով տրված իրավասության վրա հենվելով՝ ավստրո-հունգարական բանակները մտան Բոսնիա. թեև օսմանյան կառավարությունը համաձայնել էր չդիմադրել, Սարաևոյի և Մոստարի տեղացի մահմեդական ու ուղղափառ բնակչությունը զենքի դիմեց և երեք ամիս համառ դիմադրություն ցույց տվեց։ Օկուպացիան հնարավոր եղավ ավարտել միայն 1878 թվականի հոկտեմբերի 20-ին։ Փադիշահի իրավական գերիշխանությունը մինչև 1908 թվականը շարունակվեց թղթի վրա, սակայն չորս դարի օսմանյան Բոսնիան փաստացի ձեռքից դուրս եկավ, և սկսվեց մահմեդականների արտագաղթի մեծ ալիք։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Բանյա Լուկա։", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["Մուհառամի հրամանագիրը և Օսմանյան պետական պարտքի վարչության (Դույուն-ը Ումումիյե) հիմնումը", "02b7cc03"], "d": ["1875 թվականի սնանկությունից հետո պարտատեր պետությունների ներկայացուցիչների հետ վարված բանակցություններն ավարտվեցին հիջրայի 1299 թվականի Մուհառամի 28-ի (1881 թվականի դեկտեմբերի 20) հրամանագրով. պարտքի մայր գումարը կրճատվեց կեսից ավելի, իսկ փոխարենը ամենաեկամտաբեր աղբյուրները՝ աղի, ծխախոտի, մետաքսի, դրոշմանիշի և ձկան տուրքերը, ուղղակիորեն փոխանցվեցին պարտատերերի կառավարած Օսմանյան պետական պարտքի վարչությանը։ Հազարավոր պաշտոնյաներ ունեցող այս վարչությունը պետության ներսում վերածվեց առանձին ֆինանսական կազմակերպության։ Այն համարվում է օսմանյան ֆինանսական անկախության փաստացի ավարտի թվականը։", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["Սուակին. միակ նավահանգիստը, որ չընկավ Մահդիի ձեռքը", "5a37b198"], "d": ["Մինչ 1884 թվականի փետրվարից սկսած Սուակինից բացի արևելյան Սուդանի բոլոր շրջաններն անցնում էին Մուհամմադ Ահմեդ ալ-Մահդիի տիրապետության տակ, նավահանգիստը գոյատևեց գեներալ Գրեհեմի հրամանատարությամբ երեք գումարտակից բաղկացած անգլիական ուժի ռազմական պաշտպանությամբ։ Սա սկիզբն էր մի շրջանի, երբ փաստացի և իրավական վիճակները տարաբաժանվեցին. թեև ափը փաստացի գտնվում էր անգլիական ռազմական վերահսկողության տակ, վարչական կապը 1885 թվականին վերցվելու էր Եգիպտոսից և ուղղակիորեն կապվելու էր Եմենի վիլայեթին, այսինքն՝ Բարձր դռանը. այդ կարգը տևեց մինչև 1888 թվականին ֆրանսիացիների կողմից Զեյլայի օկուպացմամբ դրա ավարտը։", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["Միդհաթ փաշայի սպանությունը Թաիֆի բանտում", "f4562261"], "d": ["Հիմնական օրենքի ճարտարապետ և Առաջին սահմանադրական շրջանի խորհրդանիշ Միդհաթ փաշան Յըլդըզի դատարանում մեղավոր էր ճանաչվել Աբդուլազիզի մահվան գործով, և նրա մահապատիժը փոխարինվելով աքսորով՝ ուղարկվել էր Թաիֆ։ TDV-ի արձանագրության համաձայն՝ 1884 թվականի մայիսի 7-ի լույս 8-ի գիշերը նա խեղդամահ արվեց իր խցում. պաշտոնական պատճառ հայտարարվեց «շիրփենչե» (սիբիրախտանման թարախապալար) հիվանդությունը։ Նրա մահը դարձավ Աբդուլհամիդ II-ի օրոք սահմանադրական ընդդիմության վերացման խորհրդանիշ։", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["Հայդարփաշա-Անկարա երկաթուղու կոնցեսիայի տրումը գերմանացիներին", "5705b163"], "d": ["Փադիշահի իրադեով Հայդարփաշա-Անկարա գծի կառուցման և շահագործման կոնցեսիան տրվեց Դոյչե բանկը ներկայացնող բանկիր Ալֆրեդ ֆոն Կաուլլային, և հիմնվեց Անատոլիական երկաթուղիների ընկերությունը։ Այս կոնցեսիան դարձավ շրջադարձային կետ, որը կոտրեց անգլո-ֆրանսիական մենաշնորհը օսմանյան տրանսպորտում և արտաքին քաղաքականության մեջ և արմատավորեց գերմանական ազդեցությունը։ Տասնմեկ տարի անց նույն ընկերությանը տրվելիք Բաղդադի գծի կոնցեսիայի հետ միասին ծնվելու էր «Բեռլին-Բաղդադ» երազանքը, որը դառնալու էր Առաջին համաշխարհային պատերազմից առաջ մեծ տերությունների մրցակցության գլխավոր առանցքներից մեկը։", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["Օսմանյան միության ընկերության (Իթթիհադ-ը Օսմանի) հիմնումը Ստամբուլում", "b7187939"], "d": ["Ռազմաբժշկական ուսումնարանի չորս ուսանող բռնապետական կառավարման դեմ հիմնեցին Օսմանյան միության ընկերությունը որպես գաղտնի կազմակերպություն. այդ կառույցը շուտով վերածվեց «Միություն և առաջադիմություն» ընկերության, որն իր հովանու ներքո հավաքելու էր երիտթուրքական շարժման բոլոր ընդդիմադիր տարրերը։ Բջիջային սկզբունքով կազմակերպությունը միավորվեց Եվրոպայի աքսորականների և Սալոնիկի սպաների հետ։ 1908 թվականին Երկրորդ սահմանադրական շրջանը հռչակել տվող և 1913 թվականից հետո պետությունը միանձնյա կառավարող կադրերը ծնվեցին այս փոքրիկ ուսանողական բջիջից։", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["Հարձակումը Օսմանյան բանկի վրա. դաշնակցական գործիչների Ղալաթիայի գործողությունը", "08b3095f"], "d": ["Հայ Դաշնակցություն կազմակերպության զինված խումբը, նպատակ ունենալով Եվրոպայի ուշադրությունը հրավիրել հայկական հարցի վրա, հարձակվեց Ղալաթիայում գտնվող Օսմանյան բանկի գլխամասի վրա, պատանդներ վերցրեց և սպառնաց պայթեցնել շենքը։ Ճգնաժամն ավարտվեց դեսպանների միջամտությամբ՝ ի փոխարեն գործիչների՝ նավով երկրից դուրս բերվելու։ Հարձակմանը հաջորդած օրերին Ստամբուլում տեղի ունեցած արյունալի դեպքերը վճռորոշ եղան հայկական հարցի՝ միջազգային միջամտության լծակի վերածվելու մեջ։", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["1897 թվականի օսմանա-հունական պատերազմի սկիզբը. Թեսալիայի ճակատ", "33e490ab"], "d": ["Հունաստանի կողմից Կրետե նավատորմ և զորք իջեցնելու և Ռումելիայի սահմանում չեթաների հարձակումների պատճառով Օսմանյան պետությունը պատերազմ հայտարարեց։ Գերմանական բարեփոխիչ առաքելության վարժեցրած օսմանյան բանակը, Թեսալիայում արագ առաջ շարժվելով, մեկ ամսում վերցրեց Լարիսան (Ենիշեհիր), Չաթալջան (Ֆարսալա) և Դոմոկոսը. հունական բանակը ցրվեց։ Մեծ տերությունների միջամտությամբ գրավված հողերը վերադարձվեցին, սակայն պատերազմը մնաց Աբդուլհամիդ II-ի օրոք միակ վճռական ռազմական հաղթանակը և չկարողացավ կանխել Կրետեի փաստացի կորուստը։", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["Կոնիա-Բաղդադ գծի կոնցեսիայի տրումը գերմանացիներին", "fd8b6cbd"], "d": ["Կայզեր Վիլհելմ II-ի՝ 1898 թվականին Ստամբուլ և Դամասկոս այցից հետո Անատոլիական երկաթուղիների ընկերությանը տրվեց Կոնիայից մինչև Բաղդադ և Բասրա ձգվելիք գծի նախնական կոնցեսիան։ Բաղդադի երկաթուղու նախագիծը Օսմանյան պետության համար նշանակում էր ամրապնդել կենտրոնական վերահսկողությունը արաբական վիլայեթների նկատմամբ, իսկ Գերմանիայի համար՝ հասնել Պարսից ծոցին։ Անգլիայի և Ռուսաստանի կողմից խստորեն դեմ արտահայտված այս նախագիծը դարձավ Առաջին համաշխարհային պատերազմին տանող իմպերիալիստական մրցակցության ամենավիճելի թղթապանակներից մեկը։", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["Հիջազի երկաթուղու շինարարության սկիզբը Դամասկոսում", "62f58f68"], "d": ["Աբդուլհամիդ II-ի 1900 թվականի մայիսի 2-ի իրադեով հրամայած գծի շինարարությունը սկսվեց 1900 թվականի սեպտեմբերի 1-ին Դամասկոսում կայացած պաշտոնական արարողությամբ։ Ամբողջությամբ իսլամական աշխարհից հավաքված նվիրատվություններով և օսմանյան ինժեներ-զինվորների աշխատանքով իրականացված նախագիծը ուխտավորների Դամասկոս-Մեդինա ճանապարհորդությունը քառասուն օրից կրճատեց հինգ օրի։ Այն և՛ խալիֆայության հոգևոր հեղինակությունն ամրապնդող հեղինակային գործ էր, և՛ Հիջազի նկատմամբ ռազմական վերահսկողությունն ուժեղացնող ռազմավարական ներդրում։", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["Մյուրցշտեգի ծրագիրը. միջազգային բարեփոխումների վերահսկողություն Մակեդոնիայում", "4c7464da"], "d": ["Իլինդենի ապստամբությունից հետո Ռուսաստանի և Ավստրիայի կայսրերը, հանդիպելով Մյուրցշտեգում, պատրաստեցին Մակեդոնիայի բարեփոխումների նոր փաթեթ։ Ծրագիրը նախատեսում էր օսմանյան ընդհանուր տեսուչի կողքին տեղադրել երկու օտարերկրյա քաղաքացիական գործակալ, եվրոպացի սպաների կողմից վերակազմակերպել ժանդարմերիան և վարչական սահմանները փոխել ազգային սկզբունքով։ Թեև Բարձր դուռը դիմադրեց՝ պատճառաբանելով, որ խախտվում են նրա ինքնիշխան իրավունքները, համատեղ ճնշման առջև ստիպված եղավ ընդունել. ծրագիրը դարձավ այն հիմնական գործոններից մեկը, որոնք երիտասարդ սպաների շրջանում արագացրին իթթիհատական կազմակերպումը։", "b56ab15c"]},
"OLAYLAR_EK5:1904-08-29:0":{"b": ["Մուրադ V-ի մահը", "396659a7"], "d": ["1876 թ. շուրջ երեք ամիս գահին մնացած և գահընկեց արված Մուրադ V-ը, նրան կրկին գահ բարձրացնելու փորձերից հետո, խիստ հսկողության ներքո քսանութ տարի ապրեց բանտարկված վիճակում և մահացավ շաքարախտից։ Թաղվեց Ենիջամիի Ջեդիդ Հավաթին դամբարանում՝ մոր կողքին։ Պատմության մեջ մտավ որպես ամենակարճ ժամանակ գահին մնացած օսմանյան փադիշահ։", "8558c1b8"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["Սանաայի կորուստը հօգուտ իմամ Յահյայի", "e7f876cb"], "d": ["Զեյդիական իմամ Յահյա Համիդադդինի՝ 1904 թվականին սկսած ապստամբությունը 1905 թվականի ապրիլին ավարտվեց պաշարման արդյունքում Սանաայի անկմամբ. քաղաքը դուրս եկավ օսմանյան կառավարումից, իսկ պաշարման ողջ ընթացքում սով և համաճարակ բռնկվեցին։ Եմենի լեռնային աշխարհագրությունը, մատակարարման գծերի երկարությունը և զեյդիական իմամության տեղական լեգիտիմությունը այստեղ օսմանյան տիրապետությունը հիմնադրումից ի վեր դարձնում էին փխրուն։ Քաղաքը հինգ ամիս անց ծանր կորուստների գնով հետ էր վերցվելու, սակայն Եմենի խնդիրը չէր փակվելու մինչև 1918 թվականը։", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["Յըլդըզի մահափորձը. ռումբով հարձակում Աբդուլհամիդ II-ի վրա", "1ee2e1a6"], "d": ["Հայ Դաշնակցություն կազմակերպությունը մահափորձ կատարեց ուրբաթօրյա սելամլըքից դուրս եկող փադիշահի կառքի դեմ՝ պայթեցնելով ժամային ռումբ կրող լանդոն. շեյխ ուլ-իսլամի հետ զրուցելու պատճառով Աբդուլհամիդի մի քանի րոպե ուշանալը փրկեց նրա կյանքը։ Պայթյունի հետևանքով զոհվեց քսանվեց մարդ, վիրավորվեց հիսունից ավելին։ Դեպքն էլ ավելի խստացրեց փադիշահի անվտանգության մոլուցքը և լրտեսական կազմակերպության վրա հիմնված բռնապետական կառավարումը. այն դարձավ նաև Թևֆիկ Ֆիքրեթի «Մի ակնթարթի ուշացում» բանաստեղծության թեման։", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["Սանաայի հետ վերցնելը. իմամ Յահյայի ապստամբության ճնշումը", "dec3b8f9"], "d": ["1904 թվականին զեյդիական իմամ Յահյայի առաջնորդությամբ սկսված ապստամբությունը 1905 թվականի ապրիլին հանգեցրեց Սանաայի անկմանը, և քաղաքում սով ու համաճարակ բռնկվեցին։ Ալի Ռիզա փաշայի և Ահմեդ Ֆեյզի փաշայի հրամանատարությամբ օժանդակ բանակները 1905 թվականի հուլիսի 15-ից սեպտեմբերի 1-ը իրականացրած գործողությամբ, որին աջակցեցին նաև Թաիզում գտնվող ուժերը, ծանր կորուստների գնով հետ վերցրին քաղաքը, և ապստամբությունը ճնշվեց։ Եմենի արշավանքը օսմանյան բանակին բերեց տասնյակ հազարավոր կորուստներ և հսկայական ֆինանսական բեռ. Ռումելիայի սպաների շրջանում «Եմեն աքսորվելու» վախը իթթիհատական կազմակերպումը սնող բողոքների առաջիններից էր։", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["Երկրորդ սահմանադրական շրջանի առաջին Պատգամավորների պալատի գումարումը", "e7fd2716"], "d": ["Երեսուն տարվա ընդմիջումից հետո կայացած երկաստիճան ընտրություններով ձևավորված խորհրդարանը 1908 թվականի դեկտեմբերի 17-ին բացվեց փադիշահի ճառով, և նրա նախագահ ընտրվեց երիտթուրքական շարժման առաջնորդ Ահմեդ Ռիզա բեյը։ Թուրք, արաբ, ալբանացի, հույն, հայ և հրեա պատգամավորներից կազմված խորհրդարանը օսմանիզմի գաղափարի վերջին մեծ փորձն էր։ Սակայն Բուլղարիայի անկախությունը, Բոսնիայի բռնակցումը և Կրետեի՝ Հունաստանին միանալու հայտարարությունը դեռ խորհրդարանի բացվելուց առաջ ստվերել էին այս լավատեսությունը։", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["Շարժական բանակը (Հարեքեթ օրդուսու) և Աբդուլհամիդ II-ի գահընկեցությունը. Մեհմեդ V Ռեշադի գահակալումը", "6a65a704"], "d": ["31-ը մարտի դեպքի պատճառով Սալոնիկից ճանապարհ ելած Շարժական բանակը ապրիլի 22-ի լույս 23-ի գիշերը չորս ուղղությամբ մտավ Ստամբուլ, և ապրիլի 24-ին Յըլդըզ պալատը հանձնվեց։ Ազգային ընդհանուր ժողովը ապրիլի 27-ին որոշեց գահընկեց անել Աբդուլհամիդ II-ին. փադիշահն ուղարկվեց Սալոնիկ, և նրա փոխարեն գահ բարձրացվեց եղբայրը՝ Մեհմեդ V Ռեշադը։ Այսպիսով ավարտվեց երեսուներեք տարվա անձնական կառավարումը, սակայն նրան փոխարինեց նոր շրջան, երբ փադիշահը դարձել էր խորհրդանիշ, իսկ «Միություն և առաջադիմությունը» կառավարում էր բանակի աջակցությամբ։", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["Ալբանական ապստամբությունը. զինված դիմադրությունը Կոսովոյում և Շկոդրայում", "93ed30c6"], "d": ["Իթթիհատական կառավարության կենտրոնացնող հարկային քաղաքականությունը, զենք հավաքելու արշավը և լատինատառ այբուբենի շուրջ վեճը ապստամբեցրին ալբանական ցեղերին, որոնք մինչ այդ համարվում էին պետությանը ամենահավատարիմ տարրերից։ Թեև Մահմուդ Շևքեթ փաշայի հրամանատարությամբ բանակը խստորեն ճնշեց ապստամբությունը, անհանգստությունը կրկին բորբոքվեց 1911 և 1912 թվականներին։ Այս ապստամբությունները ոչ միայն մաշեցին օսմանյան բանակը Բալկանյան պատերազմի նախօրեին, այլև արագացրին ալբանական ազգային շարժման ծնունդը։", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["Ուշիի պայմանագիրը. Տրիպոլիտանիայի և Բենղազիի զիջումը Իտալիային", "4ffa1fd2"], "d": ["Բալկանյան պետությունների պատերազմական պատրաստությունների պայմաններում երկճակատ բախման չհամարձակվող Բարձր դուռը Շվեյցարիայի Ուշի ավանում գաղտնի հաշտություն ստորագրեց Իտալիայի հետ և թողեց Տրիպոլիտանիան ու Բենղազին։ Այսպիսով Օսմանյան պետությունը կորցրեց Աֆրիկայում իր վերջին հողը. փոխարենը խոստացվեց վերադարձնել Իտալիայի զբաղեցրած Ռոդոսը և Տասներկու կղզիները, սակայն այդ խոստումը երբեք չկատարվեց։ Պայմանագրի ստորագրման պահին Բալկանյան պատերազմը վաղուց սկսվել էր։ Այս դեպքով Մուրզուկը (Ֆեզան), Ղաթը, Սեբհան, Ուբարին, Տիրգանը (Traghan), Զավիլան (Zawila) և ալ-Կատրունը (Ֆեզան (Տրիպոլիտանիայի վիլայեթի սանջակ)) անցան իտալական կառավարման տակ։", "5896634d"]},
"OLAYLAR_EK5:1912-10-21:0":{"b": ["Լեմնոսի օկուպացիան Հունաստանի կողմից", "9555af1d"], "d": ["Բալկանյան առաջին պատերազմում հունական նավատորմը օկուպացրեց Լեմնոսը. կղզու Մուդրոս նավահանգիստը դարձավ Դարդանելի նեղուցի շրջափակման հենակետ։ Կղզին Լոզանում (1923 թ. հուլիսի 24) անցավ Հունաստանին։", "61677826"]},
"OLAYLAR_EK5:1912-10-30:0":{"b": ["Թասոսի օկուպացիան Հունաստանի կողմից", "6c03c7f0"], "d": ["Բալկանյան առաջին պատերազմում Հունաստանը օկուպացրեց Թասոսն ու Սամոթրակեն։", "b0695c7a"]},
"OLAYLAR_EK5:1912-11-01:0":{"b": ["Սամոթրակեի օկուպացիան Հունաստանի կողմից", "911e82a3"], "d": ["Բալկանյան առաջին պատերազմում Հունաստանը օկուպացրեց Սամոթրակեն։", "0e592cf7"]},
"OLAYLAR_EK5:1912-11-21:0":{"b": ["Լեսբոսի օկուպացիան Հունաստանի կողմից", "6b2b07ba"], "d": ["Հունական նավատորմը ափ իջավ Լեսբոսում. Բալկանյան առաջին պատերազմի վերջում կղզին գրավեցին հունական բանակն ու նավատորմը։ Լոնդոնի համաժողովը (1913 թ. մայիս) հաստատեց այդ դրությունը։", "a07eeadb"]},
"OLAYLAR_EK5:1912-11-25:0":{"b": ["Հունական ափհանում Քիոսում", "901c6539"], "d": ["Բալկանյան առաջին պատերազմի ժամանակ հույները ափհանում կատարեցին 1912 թ. ապրիլի 7-ին ռմբակոծված Քիոսում. օսմանյան կայազորը անձնատուր եղավ 1913 թ. հունվարի 3-ին։ Կղզին Լոզանի պայմանագրով (1923 թ. հուլիսի 24) անցավ Հունաստանին։", "d9fc9f4b"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["Մեծ վեզիր Մահմուդ Շևքեթ փաշայի սպանությունը մահափորձով Ստամբուլում", "68e60e63"], "d": ["Բաբ-ը Ալիի գրոհից հետո մեծ վեզիրի պաշտոնի բերված Մահմուդ Շևքեթ փաշան, Ռազմական նախարարություն գնալիս, Չարշըքափըի մոտ սպանվեց իր կառքի վրա բացված կրակից։ «Միություն և առաջադիմությունը», մահափորձի մեղքը բարդելով ընդդիմության վրա, սկսեց ձերբակալությունների և մահապատիժների լայն ալիք. «Ազատություն և համաձայնություն» կուսակցությունը փաստացի վերացվեց։ Այս դեպքով վերջնականապես հաստատվեց իթթիհատականների՝ Էնվեր-Թալեաթ-Ջեմալ եռյակի վրա հիմնված միակուսակցական բռնապետությունը։", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["Երկրորդ Բալկանյան պատերազմի սկիզբը. դաշնակիցների բաժանման կռիվը", "48d088a2"], "d": ["Լոնդոնի պայմանագրով Օսմանյան պետությունից խլած հողերը չկարողանալով կիսել՝ բալկանյան դաշնակիցները ընկան իրար դեմ. Բուլղարիայի՝ սերբական և հունական դիրքերի վրա հարձակումով սկսվեց երկրորդ պատերազմը։ Երբ Ռումինիան և Չեռնոգորիան ևս ճակատ բացեցին Բուլղարիայի դեմ, բուլղարական բանակը փլուզվեց։ Օսմանյան պետությունը, օգտվելով այս առիթից, անցավ Լոնդոնի պայմանագրով գծված Միդիա-Էնոս գիծը և Արևելյան Թրակիան Էդիրնեի հետ հետ վերցրեց։", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["Ստամբուլի պայմանագիրը. հաշտություն Բուլղարիայի հետ և Էդիրնեի հաստատումը", "c8c18b2d"], "d": ["Երկրորդ Բալկանյան պատերազմից հետո Օսմանյան պետության և Բուլղարիայի միջև ստորագրված պայմանագիրը, ընդունելով Մարիցա գետը որպես սահման, իրավականորեն հաստատեց, որ Էդիրնեն, Կըրքլարելին, Դիդիմոտիխոն և Արևելյան Թրակիան մնում են Օսմանյան պետությանը։ Դեդեաղաչը թողնվեց Բուլղարիային (իսկ Կավալան 1912 թվականի աշնանը բուլղարական օկուպացիայից հետո 1913 թվականի հուլիսին անցել էր Հունաստանին և 1913 թվականի օգոստոսի 10-ի Բուխարեստի պայմանագրով հաստատվել Հունաստանի կազմում). կարգավորվեցին երկու երկրների միջև բնակչության փոխադարձ փոխանակությունը և Բուլղարիայի մահմեդականների իրավունքները։ Բալկանյան աղետից հետ վերցնել հաջողված միակ հողակտորի երաշխիքը այս տեքստն է։ Նույն ամսաթվին միացած այլ վայրեր՝ Գյումուլջինե (Կոմոտինի)։", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-01:0":{"b": ["Բոզջաադայի և Իմրոզի հետ վերցնելը. Աթենքի պայմանագիրը", "ec084d09"], "d": ["Բալկանյան պատերազմում Հունաստանի զբաղեցրած Հյուսիսային Էգեյան կղզիներից նեղուցի մուտքը հսկող Բոզջաադան և Իմրոզը Աթենքի պայմանագրի բանակցություններում համարվեցին անփոխարինելի Չանակկալեի պաշտպանության համար և վերադարձվեցին Օսմանյան պետությանը։ Մյուս կղզիները մնացին Հունաստանին։ Այս երկու կղզիները դարձան կայսրության՝ Էգեյան ծովում իր ձեռքում պահած վերջին հողերը և Լոզանում ևս թողնվեցին Թուրքիային։", "bc1961ea"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["Աթենքի պայմանագիրը. հաշտություն Հունաստանի հետ և Սալոնիկի ու Յանինայի փոխանցումը", "8e94def7"], "d": ["Օսմանյան պետության և Հունաստանի միջև ստորագրված պայմանագիրը պաշտոնապես ճանաչեց Բալկանյան պատերազմում կորցված Սալոնիկի, Յանինայի և Հարավային Մակեդոնիայի անցումը Հունաստանին, և հրաժարում կատարվեց Կրետեի նկատմամբ օսմանյան իրավունքներից։ Մանրամասն կարգավորվեցին Հունաստանում մնացած մահմեդականների կրոնական և սեփականության իրավունքները, վաքֆերի կարգավիճակը և մուֆթիների նշանակումը։ Իսկ Էգեյան կղզիների կարգավիճակը թողնվեց չլուծված և մնաց երկու պետությունների միջև մշտական լարվածության աղբյուր։", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["Օսմանա-գերմանական գաղտնի դաշինքի պայմանագրի ստորագրումը Ստամբուլում", "0472efb3"], "d": ["Եվրոպայում պատերազմի բռնկվելուն պես մեծ վեզիր Սաիդ Հալիմ փաշայի ապարանքում Օսմանյան պետության և Գերմանիայի միջև ստորագրվեց գաղտնի դաշինքի պայմանագիր. տեքստը նախատեսում էր, որ եթե Ռուսաստանը պատերազմի մեջ մտնի Գերմանիայի դեմ, Օսմանյան պետությունը ևս կկանգնի Գերմանիայի կողքին։ Պայմանագիրը թաքցվեց անգամ կաբինետից, նրա մասին գիտեր միայն չորս մարդ։ Երեք ամիս անց Սև ծովի հարձակումով Օսմանյան պետությունը փաստացի ներքաշվելու էր պատերազմի մեջ, և կայսրության ճակատագիրը կապվելու էր այս փաստաթղթի հետ։", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["Կապիտուլյացիաների միակողմանի վերացումը", "ec773d18"], "d": ["Օսմանյան կառավարությունը, մի պահի, երբ Եվրոպան զբաղված էր պատերազմով, հայտարարեց, որ 1914 թվականի հոկտեմբերի 1-ից միակողմանիորեն վերացնում է կապիտուլյացիաները, որոնք օտարերկրացիներին տալիս էին դատական, ֆինանսական և մաքսային արտոնություններ։ Չորս դարի այս արտոնությունների համակարգին վերջ տալը երկրի ներսում ընդունվեց անկախության մեծ խանդավառությամբ, և Ստամբուլում տոնակատարություններ կազմակերպվեցին։ Բոլոր պետությունները, ներառյալ դաշնակից Գերմանիան, բողոքեցին որոշման դեմ. կապիտուլյացիաները վերջնականապես պատմության գիրկն էին անցնելու միայն 1923 թվականին՝ Լոզանում։", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["Սև ծովի հարձակումը. օսմանյան նավատորմի կողմից ռուսական նավահանգիստների ռմբակոծումը", "8ad4ef61"], "d": ["Գերմանիայից փախած և իբր օսմանյան նավատորմի կողմից «գնված»՝ Goeben-ը և Breslau-ն (Յավուզ և Միդիլլի), ծովակալ Սուշոնի հրամանատարությամբ դուրս գալով Սև ծով, ռմբակոծեցին ռուսական նավահանգիստները և խորտակեցին նավեր։ Էնվեր փաշայի՝ կաբինետից գաղտնի տված այս հրամանը փաստացի վերջ տվեց չեզոքությանը։ Մեկ շաբաթվա ընթացքում Ռուսաստանը, Անգլիան և Ֆրանսիան պատերազմ հայտարարեցին, և Օսմանյան պետությունն անդառնալիորեն մտավ Առաջին համաշխարհային պատերազմ։", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["Անգլո-հնդկական ուժերի կողմից Ֆաոյի գրավումը. իրաքյան ճակատի բացումը", "08663813"], "d": ["Անտանտի պետությունների՝ Օսմանյան պետությանը պատերազմ հայտարարելու հաջորդ առավոտյան Բահրեյնում սպասող անգլո-հնդկական բրիգադը իջավ Շատ ալ-Արաբի գետաբերանի Ֆաո։ Ֆաոյի ավերակ բերդում գտնվող փոքր օսմանյան զորամասը հետ քաշվեց ռազմանավերի կրակի տակ, և Հնդկաստանի հեռագրային գծի կայանն անցավ անգլիացիների ձեռքը։ Այսպիսով բացվեց իրաքյան ճակատը։", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["Մեծ ջիհադի (Ջիհադ-ը Էքբեր) հայտարարումը. ջիհադի ֆեթվայի ընթերցումը Ֆաթիհ մզկիթում", "2a6174e8"], "d": ["Շեյխ ուլ-իսլամ Ուրգուփլու Հայրի էֆենդիի տված հինգ ֆեթվաները, խալիֆա-փադիշահի անունից կարդացվելով Ֆաթիհ մզկիթում, բոլոր մահմեդականներին կոչ արեցին ջիհադի Անտանտի պետությունների դեմ։ Այս քայլը, որի վրա Գերմանիան մեծ հույսեր էր կապում, նպատակ ուներ ապստամբեցնել անգլիական և ֆրանսիական գաղութների մահմեդականներին։ Սպասված համընդհանուր ապստամբությունը տեղի չունեցավ. ընդհակառակը, երկու տարի անց Մեքքայի էմիր շարիֆ Հուսեյնի ապստամբությունը անգլիական աջակցությամբ դառնորեն ցույց տվեց խալիֆայության քաղաքական ազդեցության սահմանները։", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["Քուրնայի հանձնումը անգլիացիներին", "621d36b0"], "d": ["Բասրայի անկումից հետո Տիգրիսի և Եփրատի միախառնման վայրը՝ Քուրնա, քաշված Բասրայի կուսակալ Սուբհի բեյի ուժերը դեկտեմբերի 4-8-ի ընդհարումներից հետո 1914 թվականի դեկտեմբերի 9-ի առավոտյան հանձնվեցին։", "ff45626a"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["Սարիղամիշի գործողությունը. աղետ Կովկասյան ճակատում", "5cbde7f0"], "d": ["Էնվեր փաշան, նպատակ ունենալով հետ վերցնել 1878 թվականին կորցված Կարս-Արդահան-Բաթումը և ապստամբեցնել Կովկասի թուրքերին, ձմռանը Երրորդ բանակը Ալլահուէքբեր լեռների վրայով ուղարկեց ռուսական ուժերը շրջապատելու մանևրի։ Ձմեռային անբավարար հանդերձանքի, սպառված մատակարարման և մինչև մինուս երեսուն աստիճանի հասնող բուքի պատճառով բանակը հալվեց դեռ ճակատամարտի մեջ չմտած. տասնյակ հազարավոր զինվորներ սառչելով մահացան։ Գործողությունը դարձավ պատերազմում Օսմանյան պետության ամենածանր աղետներից մեկը և արևելյան ճակատը երկու տարով թողեց անպաշտպան։", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["Ջրանցքի առաջին գործողությունը. հարձակում Սուեզի վրա Սինայի անապատի միջով", "02dd72f5"], "d": ["Չորրորդ բանակի հրամանատար Ջեմալ փաշան, նպատակ ունենալով Եգիպտոսը ազատել անգլիական օկուպացիայից և Սուեզի ջրանցքը փակել նավագնացության համար, կազմակերպեց հարձակում Սինայի անապատի միջով։ Թեև օսմանյան զորամասերը հասան ջրանցքի արևելյան ափ, և նրանց մի մասին հաջողվեց անցնել մյուս ափ, անգլիական գերազանցության և սպասված եգիպտական ժողովրդական ապստամբության տեղի չունենալու պատճառով հետ քաշվեցին։ Գործողությունը չհասավ իր նպատակին, սակայն, ստիպելով Անգլիային Եգիպտոսում մեծ ուժ պահել, անուղղակի ռազմավարական ազդեցություն ունեցավ։", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["Տեղափոխման և բնակեցման (Թեհջիր) օրենքի ընդունումը", "2f2bc22c"], "d": ["Վանի ապստամբությունից և ռուսական առաջխաղացումից հետո կառավարությունը ընդունեց ժամանակավոր օրենք, որը բանակի հրամանատարներին թույլ էր տալիս թիկունքում անվտանգությունը խաթարող համարվող բնակչությանը տեղափոխել այլ շրջաններ, և փադիշահը 1915 թվականի մայիսի 27-ին վավերացրեց այն։ Կիրառման արդյունքում Անատոլիայի արևելյան և հարավային վիլայեթների հայ բնակչության մեծ մասը ուղարկվեց Սիրիայի և Մոսուլի ուղղությամբ. տեղափոխման ընթացքում հիվանդությունների, սովի և հարձակումների հետևանքով մարդկային շատ մեծ կորուստներ եղան։ Այս որոշումը մնացել է Օսմանյան պետության վերջին տարիների ամենածանր և այսօր էլ ամենավիճահարույց հարցը։", "e8af8dee"]},
"OLAYLAR_EK5:1916-08-07:0":{"b": ["Օսմանյան զորամասերը Մուշը հետ գրավեցին ռուսական օկուպացիայից", "fb1be113"], "d": ["Մուշի առաջին ռուսական օկուպացիայից վեց ամիս անց օսմանյան 16-րդ կորպուսը Բիթլիս-Մուշ հակահարձակման ընթացքում մտավ ավան։", "c235eed5"]},
"OLAYLAR_EK5:1916-08-25:0":{"b": ["Մուշը կրկին անցավ ռուսների ձեռքը", "43ad8a03"], "d": ["Ռուսական հակահարձակման պատճառով օսմանյան զորախումբը դատարկեց Մուշը. ավանը 1916 թ. օգոստոսի 22-25-ի միջև կրկին անցավ ռուսական օկուպացիայի տակ և մինչև 1917 թ. գարուն մնաց նրանց ձեռքում։", "db39e054"]},
"OLAYLAR_EK5:1917-05-01:0":{"b": ["Մուշը վերջնականապես ազատագրվեց ռուսական օկուպացիայից", "f0e89703"], "d": ["Առաջին համաշխարհային պատերազմում ռուսական օկուպացիայի տակ անցած Մուշը 1917 թ. մայիսի 1-ին վերջնականապես հետ գրավվեց օսմանյան ուժերի կողմից։", "f2406306"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["Աբդուլհամիդ II-ի մահը Բեյլերբեյի պալատում", "c9662582"], "d": ["1909 թվականին գահընկեց արված, նախ Սալոնիկ, իսկ Բալկանյան պատերազմում քաղաքի կորստից հետո Ստամբուլ բերված և Բեյլերբեյի պալատում հսկողության տակ պահված Աբդուլհամիդ II-ը վախճանվեց։ Իր երեսուներեքամյա կառավարման ողջ ընթացքում նա փորձել էր պետությունը հեռու պահել պատերազմներից և ժամանակ շահել, սակայն հիշվել էր նաև բռնապետական կառավարմամբ։ Նրա դին մեծ բազմության ուղեկցությամբ թաղվեց Դիվանյոլուի Մահմուդ I-ի դամբարանում. նրա մահը համընկավ պատերազմական մի տարվա, երբ նրա ստեղծած կարգը վաղուց վերացվել էր։", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["Բրեստ-Լիտովսկի պայմանագիրը. Կարսի, Արդահանի և Բաթումի հետ վերցնելը", "da82636f"], "d": ["Բոլշևիկյան հեղափոխությունից հետո պատերազմից դուրս եկած Ռուսաստանի և Քառյակ դաշինքի (Կենտրոնական) պետությունների միջև ստորագրված պայմանագիրը փակեց Արևելյան ճակատը և Օսմանյան պետությանը վերադարձրեց 1878 թվականի Բեռլինի պայմանագրով կորցրած Կարսը, Արդահանը և Բաթումը (Էլվիե-ի Սելասե՝ Երեք սանջակները)։ Սա օսմանյան պատմության մեջ քառասուն տարվա ընդմիջումից հետո ձեռք բերված միակ տարածքային ձեռքբերումն էր։ Սակայն Մուդրոսի զինադադարից հետո շրջանը կրկին ձեռքից դուրս էր գալու, իսկ վերջնական լուծումը գալու էր 1921 թվականի Կարսի պայմանագրով։", "f6f15123"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["Օսմանյան զորամասերը մտան Արդվին", "ca7d1778"], "d": ["Մարտի 25-ին 1914 թվականի սահմանն անցած օսմանյան զորամասերը շարժվեցին Երեք սանջակների (Էլվիե-ի Սելասե) վրա, որոնցում Բրեստ-Լիտովսկը վերադարձրել էր 1878 թվականից առաջվա սահմանը, և 1918 թվականի մարտի 28-ին մտան Արդվին։ Արդվինը, որպես Բաթումի սանջակի մաս, 1878 թվականին թողնվել էր Ռուսաստանին. TDV-ի Արդվինի մասին հոդվածը վերադարձի մասին գրում է միայն «1918 թվականի մարտ», իսկ օրը տալիս է Մուստաֆա Սարըն։", "7c7f5573"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["Արդահանն անցավ թուրքական բանակի ձեռքը", "7fd9e3db"], "d": ["Էլվիյեի Սելասեի (երեք սանջակների) գործողության ընթացքում օսմանյան բանակը Արթվինից հետո 1918 թ. ապրիլի 3-ին գրավեց Արդահանը. Արդահանն ընկել էր 1877 թ. «93-ի պատերազմում» և 1878 թ. զիջվել Ռուսաստանին։ Կարսը գրավվելու էր մեկ ամիս անց՝ ապրիլի 25-ին։", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["Բաթումի հետ վերցնելը", "d37a1a0d"], "d": ["Բրեստ-Լիտովսկի պայմանագրով Ռուսաստանի պատերազմից դուրս գալուց հետո դեպի արևելք առաջ շարժվող օսմանյան բանակը քառասուն տարի անց հետ վերցրեց 1878 թվականին կորցված Բաթումի նավահանգիստը։ Սև ծովի արևելյան ծայրի այս նավահանգիստը Բաքվի նավթի ծովային ելքն էր։ Ձեռքբերումը տևեց ընդամենը յոթ ամիս. Մուդրոսի զինադադարից հետո շրջանը դատարկվելու էր։", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["Էլվիե-ի Սելասե (Երեք սանջակները). Կարսը անցավ օսմանյան կառավարման տակ", "02cbf0b3"], "d": ["Բրեստ-Լիտովսկում որոշվել էր 1878 թվականի Բեռլինի պայմանագրով կորցված երեք սանջակների՝ Կարսի, Արդահանի և Բաթումի վերադարձը. օսմանյան բանակը 1918 թվականի ապրիլի 3-ին մտավ Արդահան, ապրիլի 14-ին՝ Բաթում, ապրիլի 25-ին՝ Կարս, և կառավարումը փաստացի հաստատվեց։ «Էլվիե-ի Սելասե» անունով հիշվող այս հողերը համարվեցին 1877-78 թվականների (93-ի) պատերազմից ի վեր տևող կորստի փոխհատուցումը։ Զինադադարից հետո դրանք կրկին ձեռքից դուրս էին գալու և վերջնականապես Թուրքիային էին միանալու միայն 1921 թվականի Կարսի պայմանագրով։", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["Իգդիրը գրավվեց. առաջխաղացում Արաքսի հովտում", "87ebf4d3"], "d": ["1918 թ. փետրվարին սկսված հարձակողական գործողության շրջանակում թուրքական զորամասերը Արաքսից հյուսիս՝ Սարդարապատում, հաղթեցին հայկական զորամասերին և 1918 թ. մայիսի 20-ին գրավեցին Իգդիրը։ Իգդիրը չէր մտնում Էլվիյեի Սելասեի մեջ, այլ Երևանի նահանգի Սուրմալուի գավառն էր. շուրջ 180 տարի անց տարածաշրջանում հաստատվեց առաջին օսմանյան վարչակարգը։", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["Մեհմեդ V Ռեշադի մահը և Մեհմեդ VI Վահդեդդինի գահակալումը", "d302ba07"], "d": ["Տրիպոլիտանիայի, Բալկանյան և համաշխարհային պատերազմներով անցած իննամյա կառավարումից հետո Մեհմեդ V Ռեշադը վախճանվեց պատերազմի ամենակրիտիկական շրջանում, և նրան փոխարինեց եղբայրը՝ Վահդեդդինը, որը գահ բարձրացավ Մեհմեդ VI անունով։ Նոր փադիշահը փորձեց ազատվել իթթիհատական կադրերի խնամակալությունից. չորս ամիս անց զինադադարի ստորագրումից հետո նա ստիպված էր լինելու ղեկավարել կայսրության լուծարումը։ Նա Օսմանյան հարստության երեսունվեցերորդ և վերջին փադիշահն էր։", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["Անտանտի նավատորմի ժամանումը Ստամբուլի մատույցներ և քաղաքի փաստացի օկուպացիան", "d10cb14d"], "d": ["Մուդրոսի զինադադարից հետո անգլիական, ֆրանսիական, իտալական և հունական նավերից բաղկացած ավելի քան վաթսուն միավորի դաշնակից նավատորմը խարսխեց Դոլմաբահչեի դիմաց, և Ստամբուլը փաստացի անցավ օկուպացիայի տակ։ Չորս հարյուր վաթսունհինգ տարի անց մայրաքաղաքն առաջին անգամ անցել էր օտարերկրյա զինվորների վերահսկողության տակ։ Այն խոսքը, որ նույն օրը, ըստ ավանդության, ասել է Մուստաֆա Քեմալ փաշան՝ Հայդարփաշա իջնելով և տեսնելով տեսարանը՝ «Ինչպես եկել են, այդպես էլ կգնան», դառնալու էր Ազգային պայքարի խորհրդանիշ նախադասություններից մեկը։", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["Նահանջ Արաքսի շրջանում. Իգդիրը դատարկվեց", "57572ab4"], "d": ["Մուդրոսի զինադադարի՝ 1914 թ. սահմանից այն կողմ նահանջելու դրույթի համաձայն Յաքուբ Շևքի փաշան նոյեմբերի 21-ի հրամանագրով կարգադրեց Բրեստ-Լիտովսկի սահմանից դուրս գտնվող զորամասերը մինչև դեկտեմբերի 4-ը հետ քաշել. Իգդիրն ու նրա շրջակայքը այդ օրը լիովին դատարկվեցին։ Այնուհետև 1918 թ. դեկտեմբերի վերջին հայերը տապալեցին Արաքսի թուրքական կառավարությունը։", "68b8ff9a"]},
"OLAYLAR_EK5:1918-12-17:0":{"b": ["Անգլիացիները հաստատվեցին Արթվինում", "e2cb3153"], "d": ["Քանի որ 1918 թ. հոկտեմբերի 30-ի Մուդրոսի զինադադարը պահանջում էր, որ օսմանյան բանակը նահանջի 1914 թ. սահմանից այն կողմ, Արթվինը դատարկվեց և 1918 թ. դեկտեմբերի 17-ին օկուպացվեց անգլիացիների կողմից։ Ըստ TDV-ի «Արթվին» հոդվածի՝ անգլիական օկուպացիան տևեց մինչև 1920 թ. ապրիլ։", "5b9a237d"]},
"OLAYLAR_EK5:1918-12-24:0":{"b": ["Բրիտանական կառավարումը Բաթումում Մուդրոսից հետո", "9dd768fc"], "d": ["1918 թ. հոկտեմբերի 30-ի Մուդրոսի զինադադարի համաձայն Օսմանյան պետությունը ստիպված էր դուրս գալ Բաթումից. 1918 թ. դեկտեմբերի 24-ին քաղաքը գրավեցին բրիտանական զորամասերը։ 1918 թ. ապրիլին առանձին սանջակի կենտրոն դարձած Բաթումը այդ օրվանից մինչև 1920 թ. հուլիսը մնաց անգլիական վերահսկողության ներքո։", "d172259b"]},
"OLAYLAR_EK5:1919-04-20:0":{"b": ["Արդահանն անցավ վրացական տիրապետության տակ", "97cf47f6"], "d": ["Մուդրոսից հետո դատարկված Արդահանը վրացական ուժերը գրավեցին 1919 թ. ապրիլի 20-ին՝ այն օրերին, երբ անգլիացիները ցրում էին Հարավարևմտյան Կովկասի կառավարությունը։ Վրացական տիրապետությունը տևելու էր մինչև 1921 թ. փետրվարի 23-ը։", "6027a645"]},
"OLAYLAR_EK5:1919-04-30:0":{"b": ["Պրեստոնը Կարսի կառավարումը հանձնեց հայ նահանգապետին", "efa81cb0"], "d": ["1919 թ. ապրիլի 12-13-ին Հարավարևմտյան Կովկասի կառավարությունը ցրած անգլիացի հրամանատար Պրեստոնը 1919 թ. ապրիլի 30-ին վերացրեց ժամանակավոր շուրայի կառավարությունը և քաղաքի կառավարումը փոխանցեց Կարսի նահանգապետ նշանակված հայ Կարգանովին. Կարսում սկսվեց հայկական կառավարման շրջանը, որը տևեց մինչև Քյազիմ Քարաբեքիրի 1920 թ. հոկտեմբերի 30-ի հաղթանակը։", "ffa3989a"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["Էրզրումի կոնգրեսը. արևելյան վիլայեթների ազգային դիմադրության որոշումը", "41ef0457"], "d": ["Արևելյան Անատոլիայի իրավունքների պաշտպանության ընկերության գումարած կոնգրեսը, անգլիական ճնշման պատճառով հետաձգվելուց հետո, բացվեց հիսունվեց պատվիրակով, և նախագահ ընտրվեց զինվորական ծառայությունից հրաժարական տված Մուստաֆա Քեմալ փաշան։ Կոնգրեսը հայտարարեց, որ ազգային սահմանների ներսում հայրենիքը մեկ ամբողջություն է, մանդատն ու հովանավորությունը անընդունելի են, իսկ կառավարության ցրվելու դեպքում ազգը իր ձեռքը կվերցնի իր ճակատագիրը։ Այս որոշումները վեց ամիս անց կազմելու էին Ազգային ուխտի (Միսաք-ը Միլլի) տեքստի միջուկը։", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["Սեբաստիայի կոնգրեսը. ազգային դիմադրության միավորումը մեկ հարկի տակ", "0e9ad36b"], "d": ["1919 թվականի սեպտեմբերի 4-ին Սեբաստիայի լիցեյում (Սուլթանիե) իր աշխատանքը սկսած կոնգրեսը երկրի չորս կողմերի իրավունքների պաշտպանության ընկերությունները միավորեց Անատոլիայի և Ռումելիայի իրավունքների պաշտպանության ընկերության անվան տակ և ընտրեց Ներկայացուցչական կոմիտե (Հեյեթ-ի Թեմսիլիյե)։ Ամերիկյան մանդատի առաջարկը երկար քննարկումներից հետո մերժվեց։ Սեպտեմբերի 11-ին հրապարակված հայտարարությամբ Ազգային պայքարը դարձավ մեկ կենտրոնով, լեգիտիմ քաղաքական շարժում, և Ստամբուլի կառավարության հետ սկսվեց բացահայտ ուժային պայքար։", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["Ամասիայի արձանագրությունը. Ստամբուլի կառավարության և Ներկայացուցչական կոմիտեի բանակցությունը", "40e6a6ab"], "d": ["Դամադ Ֆերիդի անկումից և Ալի Ռիզա փաշայի կառավարության ձևավորումից հետո ծովային նախարար Սալիհ փաշան Ներկայացուցչական կոմիտեի հետ բանակցելու նպատակով ուղարկվեց Ամասիա։ Կնքված արձանագրություններով Ստամբուլի կառավարությունը փաստացի ճանաչեց Անատոլիական շարժման գոյությունը. ընդունվեցին Պատգամավորների պալատի գումարումը, ընտրությունների ազատ անցկացումը և ազգային սահմանների պաշտպանությունը։ Սա Ազգային պայքարի՝ Ստամբուլի նկատմամբ ձեռք բերած առաջին պաշտոնական քաղաքական ձեռքբերումն է։", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["Ազգային ուխտի ընդունումը վերջին օսմանյան խորհրդարանում", "6322865e"], "d": ["Վերջին Օսմանյան Պատգամավորների պալատում 121 պատգամավորի ստորագրած Ազգային ուխտի (Ահդ-ը Միլլի) տեքստը պայման էր դնում Մուդրոսի գծի ներսում մնացած և մահմեդական-թուրք մեծամասնությամբ բնակեցված տարածքների անբաժանելի ամբողջականությունը, ժողովրդական քվեարկություն արաբական վիլայեթներում և Արևմտյան Թրակիայում, կապիտուլյացիաների վերացումը և լիակատար քաղաքական-ֆինանսական անկախությունը։ Տեքստը 1920 թվականի փետրվարի 17-ին միաձայն ընդունվեց և հռչակվեց աշխարհին։ Այս հռչակագիրը ոչ միայն Ազգային պայքարի քաղաքական ծրագիրն էր, այլև Լոզանում պաշտպանվելիք սահմանների քարտեզը. այն դարձավ Անտանտի պետությունների կողմից մարտի 16-ին Ստամբուլի պաշտոնական օկուպացիայի ուղղակի պատճառը։", "576d2af5"]},
"OLAYLAR_EK5:1920-04-01:0":{"b": ["Անգլիացիների հեռանալիս Արթվինը մնաց Վրաստանին", "6d086b06"], "d": ["Ըստ TDV-ի «Արթվին» հոդվածի՝ անգլիական օկուպացիան տևեց մինչև 1920 թ. ապրիլ ամիսը. հեռանալիս անգլիացիները քաղաքը թողեցին Վրաստանին։ Արթվինը Վրաստանի ձեռքում մնաց մինչև ԹԱՄԺ-ի 1921 թ. փետրվարի 23-ի վերջնագիրը։", "20ff63b0"]},
"OLAYLAR_EK5:1920-07-07:0":{"b": ["Բաթումը հանձնվեց վրացական կառավարմանը", "6523d095"], "d": ["Անգլիացիների կողմից Բաթումի պաշտոնական հանձնումը վրացիներին տեղի ունեցավ 1920 թ. հուլիսի 7-ին (TDV-ի «Բաթում» հոդվածը նշում է միայն «1920 թ. հուլիս»)։ Անկարայի կառավարությունը հուլիսի 25-ին բողոքեց՝ այդ հանձնումն անվանելով «օկուպացիա»։", "99c9bfc8"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["Գյումրիի պայմանագիրը. Թուրքիայի Մեծ ազգային ժողովի կառավարության առաջին միջազգային պայմանագիրը", "9232c690"], "d": ["Քյազիմ Կարաբեքիրի հրամանատարությամբ Արևելյան ճակատի բանակի կողմից Սարիղամիշը և Կարսը հետ վերցնելուց հետո Հայաստանը հաշտություն խնդրեց և Գյումրիում ստորագրված պայմանագրով ընդունեց, որ չի ճանաչում Սևրը և հրաժարվում է արևելքում իր տարածքային պահանջներից։ Անկարայի կառավարության ստորագրած այս առաջին պայմանագիրը դարձավ Սևրը փաստացի մերժող առաջին միջազգային փաստաթուղթը և Թուրքիայի Մեծ ազգային ժողովի համար բացեց իրավական ճանաչման ճանապարհը։ Այսպիսով արևելյան սահմանը ապահովելով՝ հնարավոր դարձավ ուժեր տեղափոխել Արևմտյան ճակատ։", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["Ինյոնյուի առաջին ճակատամարտը. կանոնավոր բանակի առաջին հաղթանակը", "4add3719"], "d": ["Նորաստեղծ կանոնավոր բանակը Բուրսայի ուղղությամբ առաջ շարժվող հունական ուժերին կանգնեցրեց Ինյոնյուի դիրքերում և ստիպեց նահանջել։ Ռազմական տեսանկյունից սահմանափակ մասշտաբի այս հաջողությունը քաղաքական հետևանքներով շատ մեծ էր. Անկարայի կառավարությունը հրավիրվեց Լոնդոնի կոնֆերանս, ճանապարհ բացվեց Խորհրդային Ռուսաստանի հետ Մոսկվայի պայմանագրի համար, և ընդունվեց Հիմնական կազմակերպական օրենքը (Թեշքիլաթ-ը Էսասիյե)։ Երկրի հասարակական կարծիքում կանոնավոր բանակի նկատմամբ վստահությունը ևս ամրապնդվեց այս հաղթանակով։", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["Ինյոնյուի երկրորդ ճակատամարտը. հունական հարձակման երկրորդ անգամ կոտրումը", "a974521c"], "d": ["Լոնդոնի կոնֆերանսից արդյունք չստացած հունական բանակը Բուրսայի և Ուշաքի ուղղությամբ նոր հարձակման անցավ, սակայն կրկին կանգնեցվեց Ինյոնյուի լեռնաշղթաների վրա և ստիպված եղավ նահանջել։ Մուստաֆա Քեմալ փաշայի՝ Իսմեթ փաշային ուղարկած «Դուք այնտեղ հաղթեցիք ոչ միայն թշնամուն, այլև ազգի չարաբախտ ճակատագրին» հեռագիրը գրվեց այս հաղթանակից հետո։ Ճակատամարտը բարձրացրեց Ազգային պայքարի միջազգային հեղինակությունը և արագացրեց Իտալիայի՝ Անատոլիայից հեռանալու գործընթացը։", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["Անկարայի համաձայնագիրը. հաշտություն Ֆրանսիայի հետ և հարավային ճակատի փակումը", "35fc32db"], "d": ["Սաքարիայի հաղթանակից հետո Ֆրանսիայի հետ Անկարայում ստորագրված համաձայնագրով ավարտվեց հարավային ճակատի պատերազմը. ֆրանսիական ուժերը, դատարկելով Չուքուրովան և Հարավ-Արևելքը, ներառյալ Ադանան, Այնթապը, Մարաշը և Ուրֆան, հետ քաշվեցին Սիրիայի սահման։ Այսպիսով Անտանտի պետություններից մեկը փաստացի ճանաչեց Անկարայի կառավարությունը, և Սևրի ճակատում բացվեց առաջին ճեղքը։ Դատարկված շրջաններից ստացված զենքերը և ազատված զորամասերը վճռորոշ դեր խաղացին Մեծ հարձակման նախապատրաստության մեջ։", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["Մուդանիայի զինադադարը. Ստամբուլի և նեղուցների փոխանցումն առանց պատերազմի", "ac0d9baf"], "d": ["Մեծ հարձակումից հետո թուրքական բանակի և անգլիական ուժերի դեմառդեմ կանգնելը Չանակկալեում և Իզմիթում հանգեցրեց Մուդանիայում գումարված կոնֆերանսի, որը տասնմեկ օր տևած ծանր սակարկությունից հետո ավարտվեց զինադադարով։ Ընդունվեց, որ Արևելյան Թրակիան մինչև Մարիցա տասնհինգ օրվա ընթացքում Հունաստանի կողմից դատարկվելով կանցնի թուրքական կառավարման տակ, իսկ Ստամբուլն ու նեղուցները կհանձնվեն հաշտության պայմանագրով։ Այսպիսով Ազգային պայքարի զինված փուլը փակվեց առանց մեկ գնդակ արձակելու տարած դիվանագիտական հաղթանակով, և բացվեց Լոզանի դուռը։", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["Մեհմեդ VI Վահդեդդինի մեկնումը Ստամբուլից և Աբդուլմեջիդ էֆենդիի ընտրությունը խալիֆա", "8ab0e847"], "d": ["Սուլթանության վերացումից հետո վիճելի դիրքում հայտնված վերջին փադիշահ Մեհմեդ VI Վահդեդդինը 1922 թվականի նոյեմբերի 17-ի ուրբաթ առավոտյան անգլիական Malaya զրահանավով հեռացավ Ստամբուլից և մեկնեց Մալթա։ Թուրքիայի Մեծ ազգային ժողովը երկու օր անց՝ նոյեմբերի 19-ին, Աբդուլմեջիդ էֆենդիին ընտրեց խալիֆա՝ առանց քաղաքական իրավասության։ Այսպիսով փաստացի ավարտվեց Օսմանյան հարստության վեց հարյուր քսաներեքամյա տիրակալությունը. խալիֆայությունը խորհրդանշական կերպով շարունակվելու էր ևս տասնհինգ ամիս։ Մալթա, ապա Իտալիա անցած Վահդեդդինը հաստատվեց Սան Ռեմոյի Villa Nobel-ում. մահմեդական երկիր ընդունվելու նրա դիմումները արդյունք չտվեցին, և նա 1926 թվականի մայիսի 16-ին այնտեղ մահացավ՝ կրկնելով, որ երբեք չի հրաժարվել սուլթանության և խալիֆայության իրավունքներից։", "86831a04"]},
"OLAYLAR_EK5:1926-05-16:0":{"b": ["Վերջին փադիշահ Մեհմեդ VI Վահդեդդինի մահը Սան Ռեմոյում", "7149ed0e"], "d": ["Ստամբուլից հեռանալուց հետո իտալական Սան Ռեմո քաղաքում հաստատված վերջին օսմանյան փադիշահ Մեհմեդ Վահդեդդինը մահացավ 1926 թ. մայիսի 16-ին՝ առանց լուր ստանալու այն խալիֆայության համաժողովի գումարման մասին (1926 թ. մայիսի 13), որին հայտնել էր, թե երբեք չի հրաժարվել սուլթանության և խալիֆայության իրավունքներից։ Նա ծանր դրամական նեղության մեջ էր. Սան Ռեմոյի առևտրականներին պարտք էր 60.000 լիրա, և նրա մահվան մասին լսած պարտատերերը կալանք դրեցին նրա տան իրերի վրա։", "0864312a"]},
"OLAYLAR_EK6:1325-01-01:0":{"b": ["Կոնուրալփի կողմից Բոլուի շրջանի գրավումը. Մուդուռնու, Կոնուրապա և Բոլու", "e245cd27"], "d": ["Օրհան Ղազիի հրամանատարներից Կոնուրալփը, ուղղվելով Սաքարիայից արևելք ընկած լեռնային շրջան, օսմանյան կառավարմանը ենթարկեց Մուդուռնուի, Կոնուրապայի և Բոլուի շրջանը. Դյուզջեի հարթավայրի ավանը կոչվեց նրա անունով։ Գրավման ճշգրիտ տարեթիվն անհայտ է. պատմությունը հիմնված է Աշըքփաշազադեի պատումի վրա։ Այդ ժամանակ շրջանը Ջանդարօղուլների և Բյուզանդիայի միջև ձեռքից ձեռք անցնող սահմանային տարածք էր. գրավումը Օսմանյան պետությանը առաջին անգամ մոտեցրեց Սև ծովի արևմտյան ափին։ Անկարայի ճակատամարտից հետո շրջանը կրկին անցնելու էր Ջանդարօղուլներին և վերջնականապես հետ էր գրավվելու միայն Ֆաթիհի օրոք։", "d7b58190"]},
"OLAYLAR_EK6:1334-01-01:0":{"b": ["Մարմարա ծովի հարավի բյուզանդական ավանների գրավումը. Միխալըչ, Քիրմաստի, Գյոլյազը", "9c61b8d4"], "d": ["Նիկիայի (Իզնիկ) և Նիկոմեդիայի (Իզմիթ) գրավումից հետո Բուրսայի հարթավայրից արևմուտք Բյուզանդիայի ձեռքում մնացած ավանները մեկը մյուսի հետևից անցան օսմանյան կառավարման տակ։ Ուլուաբատ լճի շրջակայքի Գյոլյազըն, Սուսուրլուկ գետի ափին գտնվող Քիրմաստին և Միխալըչը ամբողջացրին Մարմարա ծովի հարավային ափը Կարեսիի հողերին կապող միջանցքը։ Այդ ավանները, երկար պաշարման չենթարկվելով, հանձնվեցին՝ շրջակայքից կտրվելու հետևանքով. այսպիսով, բյուզանդական ներկայությունը տարածաշրջանում սեղմվեց Գեմլիքի ծովածոցի մոտ։", "bd729343"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["Կորնթոսն անցավ Մորեայի դեսպոտությանը", "392495eb"], "d": ["1358 թ. ի վեր Ֆլորենցիայի Աչայուոլի ընտանիքի՝ Աքայայի իշխանապետությանը ենթակա թիմարը հանդիսացող Կորնթոսը 1395 թ. անցավ Բյուզանդիայի Մորեայի դեսպոտ Թեոդորոսի ձեռքը։ Դրանից հետո քաղաքը մինչև օսմանյան նվաճումը մնաց դեսպոտության կառավարման ներքո։", "1803a03a"]},
"OLAYLAR_EK6:1427-06-01:0":{"b": ["Հաջըեմիրօղուլների բեյության բռնակցումը. Օրդու և Յունիե", "c064f07f"], "d": ["Օրդուի շրջակայքում Բայրամ բեյի հիմնած և նրա որդի Հաջը Էմիրի կողմից 1350-ական թվականներին ընդարձակված թուրքմենական բեյությունը, որի կենտրոնը գտնվում էր այժմյան Էսքիփազարում, փոքր, բայց ռազմավարական ափամերձ պետություն էր. այն Սամսունի և Տրապիզոնի միջև միակ անկախ տիրույթն էր։ Էմիր Սուլեյմանը 1398 թ. Յըլդըրըմ Բայազիդի Ջանիկի գործողության ժամանակ հայտնել էր իր հավատարմությունը, իսկ Անկարայի ճակատամարտից հետո բեյությունը կրկին ազատ էր մնացել։ Մուրադ II-ի օրոք, Թաջեդդինօղուլների վերացման նույն տարիներին, բեյության հողերն անմիջականորեն ենթարկվեցին օսմանյան կառավարմանը, և Սև ծովի ափը Սամսունից մինչև Գիրեսուն միավորվեց մեկ ձեռքում։", "d5caa358"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["Կորնթոսի գրավումը", "87a2bc59"], "d": ["Ֆաթիհի Մորեայի արշավանքի ժամանակ Ակրոկորինթոսի բերդը երեք ամիս պաշարվեց և ի վերջո խաղաղ ճանապարհով ընդունվեց հանձնումը։ Այսպիսով, Մորեայի դարպասը համարվող Կորնթոսի պարանոցն անցավ Օսմանյան պետությանը։", "b2be3a05"]},
"OLAYLAR_EK6:1499-01-01:0":{"b": ["Չեռնոգորիայի միացումը օսմանյան կառավարմանը. Ցետինե", "7fdb7cc8"], "d": ["Երբ 1496 թ. Զետան կառավարող Չեռնոևիչների հարստությունը հրաժարվեց իր իշխանությունից, Շկոդրայի «հետնաբակը» հանդիսացող Չեռնոգորիայի լեռնային շրջանն անմիջականորեն անցավ օսմանյան կառավարման տակ և նախ կազմակերպվեց որպես առանձին սանջակ, ապա որպես Շկոդրայի սանջակի մաս։ Ցետինեի վանքը մնաց իր տեղում՝ որպես շրջանի կրոնական կենտրոն։ Աշխարհագրական դաժան պայմանների պատճառով այստեղ կառավարումը երբեք այնքան խիստ չգործեց, որքան հարթավայրերում. երկու հարյուր տարի անց նույն վանքից ծնված վլադիկայի (մետրոպոլիտի) կառավարումը դառնալու էր փաստացի անկախության միջուկը։", "e8356eb2"]},
"OLAYLAR_EK6:1534-06-23:0":{"b": ["Բայազիդ բերդի կողմից օսմանյան տիրապետության ընդունումը Իրաքեյնի արշավանքի ժամանակ", "f29e2e17"], "d": ["Երբ մեծ վեզիր Իբրահիմ փաշան Իրաքեյնի արշավանքի ժամանակ հասավ Բինգյոլի շրջակայք, տարածաշրջանի բազմաթիվ քրդական ցեղերի հետ միասին Վանի, Թոփրաքքալեի, Ավնիքի և Բայազիդի բերդերը համաձայնեցին անցնել օսմանյան տիրապետության տակ։ Բայազիդը 1514 թ. Յավուզի (Սելիմ I-ի) արշավանքի ժամանակ միացել էր Օսմանյան պետությանը, բայց բանակի վերադարձից հետո Սեֆյանները հետ էին գրավել տարածաշրջանը։", "14640206"]},
"OLAYLAR_EK6:1535-06-01:0":{"b": ["Թավրիզի կրկին անցնելը Սեֆյաններին. Իրաքեյնից վերադարձը", "80b8b761"], "d": ["Իրաքեյնի արշավանքի ժամանակ բանակը մտել էր Թավրիզ, սակայն, քանի որ բուն նպատակը Բաղդադն էր, քաղաքում մշտական կայազոր չէր թողնվել։ Երբ ձմեռը Բաղդադում անցկացրած բանակը վերադառնում էր արևմուտք, Թահմասպ շահը կրկին մտավ դատարկված Ատրպատական և հետ գրավեց Թավրիզը։ Սա օսմանա-սեֆյան պատերազմների կրկնվող օրինաչափությունն էր. Թավրիզը հինգ անգամ գրավվեց և հինգ անգամն էլ հնարավոր չեղավ այն պահել. քաղաքը երկարատև օսմանյան կայազոր ունեցավ միայն 1585 թ.։", "f60ea64f"]},
"OLAYLAR_EK6:1535-09-22:0":{"b": ["Վանի և Արճեշի անկումը Թահմասպի ձեռքը (օսմանյան կողմնորոշումն ավարտվեց 1534-35 թթ.)", "cb93d561"], "d": ["1534 թ. Վանը օսմանյան տիրապետությանը հանձնած տարածաշրջանում Ուլամա փաշան Վանի բերդում դիմադրում էր սեֆյան պաշարմանը. բերդն անցավ Սեֆյանների ձեռքը, իսկ Արճեշը պաշարած սեֆյան ուժերը օսմանյան օգնության շնորհիվ նահանջել էին։ Երբ Կանունի Սուլեյմանը հասավ Խլաթ (1535 թ. սեպտեմբերի 23), Վանն արդեն Թահմասպի ձեռքում էր։ Վանը սեֆյան մնաց մինչև 1548 թ.։", "eb576b34"]},
"OLAYLAR_EK6:1547-01-01:0":{"b": ["Բայազիդի սանջակի անցումը սեֆյան տիրապետության տակ (Վանն ու Արճեշը 1535 թ. արդեն սեֆյան էին)", "806a2cf1"], "d": ["Օսմանա-սեֆյան սահմանի մեջտեղում գտնվող Բայազիդի սանջակը կրկին անցավ Իրանի ձեռքը (Kaya 2017-ը դա հիշատակում է «Վանի և Արճեշի հետ միասին», սակայն Վանն ու Արճեշը, ըստ Karataş 2025-ի և TDV-ի, 1535 թ. սեպտեմբերի 22-ին վերադարձել էին Սեֆյաններին. տե՛ս նախորդ գրառումը)։ Այս ձեռքից ձեռք անցման ընթացքում սանջակի որոշ վայրեր ավերվեցին։ Մինչև 16-րդ դարի վերջին քառորդը սանջակը բազմիցս ձեռքից ձեռք անցավ երկու պետությունների միջև։", "28cb6e07"]},
"OLAYLAR_EK6:1553-08-01:0":{"b": ["Բայազիդի սանջակի կրկին անցումը Օսմանյան պետությանը Նախիջևանի արշավանքի ժամանակ", "cf0171fa"], "d": ["Կանունի Սուլեյմանի երրորդ իրանական (նախիջևանյան) արշավանքի ժամանակ Բայազիդի սանջակը կրկին անցավ օսմանյան կառավարման տակ։ 1554 թ. արշավանքում Բայազիդը բանակի համար կարևոր հենակետ դարձավ. սանջակը 1578 թ. վերջնականապես անցավ օսմանյան տիրապետության տակ։", "a6c619eb"]},
"OLAYLAR_EK6:1604-06-08:0":{"b": ["Երևանի կորուստը՝ հօգուտ Շահ Աբբասի", "34413cf2"], "d": ["Այն տարիներին, երբ Ջելալիների ապստամբությունները կաթվածահար էին արել Անատոլիան, և արևելյան ճակատը մնացել էր անպաշտպան, իր բանակը եվրոպական ձևով վերակազմած Շահ Աբբասը անցավ հարձակման։ 1583 թ. Ֆերհադ փաշայի կառուցած Երևանի բերդը յոթամսյա պաշարումից հետո հանձնվեց։ Ֆերհադ փաշայի պայմանագրով ձեռք բերված կովկասյան գծի առաջին օղակը պոկվեց, և հետագա երեք տարում ամբողջ Հարավային Կովկասը կորսվելու էր։", "b5f54d9c"]},
"OLAYLAR_EK6:1606-01-01:0":{"b": ["Թիֆլիսի և Գանձակի կորուստը", "3fb51753"], "d": ["Երևանի անկումից հետո սեֆյան բանակը առաջ շարժվեց Քուռի հովտով. Ղարաբաղի կենտրոն Գանձակը և Վրաստանի մայրաքաղաք Թիֆլիսը իրար հետևից կորսվեցին։ Նույն ժամանակ Օսմանյան պետությունը Ավստրիայի ճակատում վարում էր տասներեք տարի տևած երկար պատերազմը, իսկ Անատոլիայում պայքարում էր Ջելալիների դեմ. արևելք ուղարկելու ուժ չկար։ Այսպիսով, 1590 թ. Ֆերհադ փաշայի պայմանագրով ստեղծված կովկասյան ընդարձակ էյալեթների համակարգը փաստացի ավարտվեց։", "c80d75b7"]},
"OLAYLAR_EK6:1607-01-01:0":{"b": ["Շիրվանի կորուստը. Շամախի, Բաքու և Դերբենդ", "81beab11"], "d": ["Կասպից ծովի ափամերձ Շիրվանի էյալեթը ձեռք էր բերվել Օզդեմիրօղլու Օսման փաշայի 1578-1585 թթ. արշավանքներով և, լինելով մետաքսի առևտրի հիմնական աղբյուրը, զգալի եկամուտ էր ապահովում օսմանյան ֆինանսներին։ Շահ Աբբասի դեպի հյուսիս ուղղված գործողությունը, հաջորդաբար գրավելով Շամախին, Բաքուն և Դերբենդը, վերացրեց այդ էյալեթը։ Կորուստը միայն տարածքային չէր. Օսմանյան կայսրության միջով Եվրոպա հոսող իրանական մետաքսի ուղին նույնպես դուրս եկավ վերահսկողությունից, և Սեֆյան պետությունը սկսեց մետաքսը վաճառել Հնդկական օվկիանոսի միջոցով։", "f85d7f97"]},
"OLAYLAR_EK6:1629-01-01:0":{"b": ["Թաիզի կորուստը", "65f20d53"], "d": ["Օսմանցիները 1038 (1629) թ. Սանաայում Կասիմյան կառավարմանը թողնված Եմենի տիրապետության հետ միասին լքեցին նաև Թաիզը. սա զեյդիական իմամների կողմից ներքին Եմենի վերագրավման գործընթացի առաջին խոշոր քայլն էր։", "72344627"]},
"OLAYLAR_EK6:1635-01-01:0":{"b": ["Եմենի կորուստը. Կասիմյան իմամների տիրապետությունը", "49e83e3c"], "d": ["Եմենը 1538 թ. ի վեր օսմանյան էյալեթ էր, սակայն զեյդիական իմամների դիմադրությունը երբեք չդադարեց։ Իմամ Կասիմի սկսած ապստամբությունը նրա որդի ալ-Մուայյադ Մուհամմադի օրոք տարածվեց ամբողջ երկրով, և օսմանյան կայազորները հերթով պաշարվեցին։ Այն տարիներին, երբ Մուրադ IV-ի ուշադրությունը կենտրոնացած էր Բաղդադի և Երևանի վրա, օգնական ուժեր հնարավոր չեղավ ուղարկել. Թաիզը կորսվել էր 1629 թ., իսկ Մոխան դատարկվել էր նույն փլուզման վերջին փուլում՝ 1635 թ. հոկտեմբերի 22-ին։ 1635 թ. Սանաայի և Զաբիդի վերջին զորամասերը նույնպես դատարկեցին Եմենը։ Այսպիսով, Կարմիր ծովի արևելյան ափը երկու հարյուր երեսունյոթ տարի մնաց կայսրությունից դուրս և կարողացավ հետ գրավվել միայն 1872 թ.։ Լահիջը (ալ-Հաուտա), ըստ TDV İslâm Ansiklopedisi-ի, մինչև 1635 թ. գտնվում էր օսմանցիների ձեռքում. այդ ժամանակից ի վեր ազդեցիկ դարձան զեյդիական իմամները։", "e966b559"]},
"OLAYLAR_EK6:1635-10-22:0":{"b": ["Մոխայի դատարկումը", "c6b3061a"], "d": ["Մուստաֆա բեյը 1045 թ. ջումադա ալ-ուլայի 10-ին (1635 թ. հոկտեմբերի 22) մնացած ուժերով և զենքերով դատարկեց Մոխան. այնուհետև Իմամ Կասիմի որդի Հասան բ. Կասիմը, Զաբիդում և Մոխայում իր մարդկանց նշանակելով, Կասիմյան վերահսկողություն հաստատեց նաև Թիհամայի ափին։", "04e81711"]},
"OLAYLAR_EK6:1670-01-01:0":{"b": ["Լահսայի կորուստը՝ հօգուտ Բանի Խալիդի ամիրայության", "a9b6131a"], "d": ["Լահսան 1550 թ. ստեղծված էյալեթ էր, որի նպատակն էր Պարսից ծոցի (Բասրայի ծոցի) արևմտյան ափը փակել պորտուգալացիների առաջ. սակայն այն շատ հեռու էր Ստամբուլից՝ մեկ անապատային ճանապարհի ծայրին։ Այն տարիներին, երբ Կրետեի պաշարումը սպառում էր ռեսուրսները, տարածաշրջանի Բանի Խալիդ ցեղը Բարրաք բ. Ղուրայրի առաջնորդությամբ դուրս քշեց օսմանյան կայազորը և հիմնեց իր ամիրայությունը։ Ծոցի արևմտյան ափը մեկուկես դար մնաց ցեղային ամիրայությունների ձեռքում. 1795 թ. այն անցնելու էր Սաուդյաններին, իսկ 1871 թ.՝ կրկին Օսմանյան պետությանը։", "f3749775"]},
"OLAYLAR_EK6:1684-09-29:0":{"b": ["Պրևեզայի և Վոնիցայի կորուստը՝ հօգուտ Վենետիկի. Էպիրոսի ափի բացումը", "1201204c"], "d": ["Սրբազան լիգային միացած Վենետիկը, նախքան Մորեայի (Պելոպոնեսի) արշավանքը սկսելը, գրավեց Ամբրակիական ծոցի մուտքը պահող երկու բերդերը՝ Պրևեզան և հանդիպակաց ափի Վոնիցան։ Նույն ամռանը ընկել էր նաև Այա Մավրան (Լեֆկադա)։ Այս երեք դիրքերը հնարավորություն տվեցին նավատորմին ապահով կերպով Իոնական ծովից խորանալ Հունաստան և դարձան հաջորդ տարի սկսվելիք Մորեայի գործողության հենակետը։ Պրևեզան և Վոնիցան Պասարովիցի պայմանագրով նույնպես թողնվեցին Վենետիկին. օսմանյան կառավարման տակ վերադառնալու էին միայն 1798 թ.։", "1de80a4b"]},
"OLAYLAR_EK6:1685-10-12:0":{"b": ["Սոլնոկի կորուստը. Տիսայի գծի քայքայումը", "51c2c8ef"], "d": ["Օգոստոս ամսին Ույվարի անկումից հետո Հաբսբուրգների բանակը շրջվեց դեպի հարավ և գրավեց Տիսա գետի վրայի կամրջագլուխ Սոլնոկը։ Քաղաքը Բուդայի և Տրանսիլվանիայի միջև միակ ապահով անցումն էր. նրա կորուստը նշանակում էր Հունգարիայի արևելյան կեսի օսմանյան բերդերի կտրումը միմյանցից։ Հաջորդ տարի Բուդայի պաշարման ժամանակ մատակարարման ճանապարհի կտրված լինելը վճռորոշ դեր խաղաց։", "a0595e94"]},
"OLAYLAR_EK6:1686-07-10:0":{"b": ["Մոդոնի կորուստը՝ հօգուտ Վենետիկի", "114c9cc0"], "d": ["Մորեա թերակղզու հարավարևմտյան ծայրին գտնվող Մոդոնը այն նավահանգիստն էր, որ Վենետիկը կորցրել էր երեք դար առաջ և անվանում էր «պետության երկու աչքերից մեկը»։ Կորոնի անկումից հետո պաշարված բերդը, միաժամանակ ցամաքից և ծովից ռմբակոծվելով, հանձնվեց։ Այսպիսով, Մորոզինիի Մորեայի գործողությունը տիրեց թերակղզու ողջ արևմտյան ափին, և բացվեց դեպի ներքին շրջաններ տանող ճանապարհը։", "df990436"]},
"OLAYLAR_EK6:1686-10-20:0":{"b": ["Պեչի կորուստը", "99d54cf4"], "d": ["Սեպտեմբերին Բուդայի անկումից հետո Հաբսբուրգների ուժերը Դանուբից արևմուտք շարժվեցին դեպի հարավ և գրավեցին Կանունի Սուլեյմանի ժամանակներից օսմանյան Պեչը (Պեչույ)։ Ղազի Քասըմ փաշայի մզկիթով հայտնի քաղաքը Բուդայի էյալեթի ամենազարգացած սանջակային կենտրոններից էր։ Նրա կորուստը նշանակում էր Մոհաչի հարթավայր իջնող ճանապարհի բացում. հաջորդ տարի հենց այստեղ էր տեղի ունենալու Մոհաչի երկրորդ պարտությունը։", "10e39af1"]},
"OLAYLAR_EK6:1686-10-23:0":{"b": ["Սեգեդի կորուստը", "9fbee1b2"], "d": ["Տիսա և Մուրեշ (Մարոշ) գետերի միախառնման կետում գտնվող Սեգեդը հունգարական հարթավայրի հարավային դարպասն էր և հսկում էր Թեմեշվարի էյալեթ տանող ճանապարհը։ Բուդայի և Պեչի նույն աշնանը ընկնելուց հետո պաշարված բերդը կարճ ժամանակում հանձնվեց։ Մեկ եղանակի ընթացքում երեք բերդերի կորուստը նշան էր, որ 1541 թ. ի վեր Հունգարիայում հաստատված օսմանյան վարչական կառույցը սկսել էր փլուզվել։ Ատլասը նույն օրը Օսմանյան պետությունից Հաբսբուրգների կողմն անցած է համարում նաև Տիսայի ափին գտնվող Զենտան (Զենտային հատուկ հանձնման օրը աղբյուրում չի կարդացվել, օրը վերցված է Սեգեդից. TDV zenta. 1686 թ. հոկտեմբերից սկսվեցին բախումներ Օսմանյան պետության և Հաբսբուրգների գլխավորած դաշնակիցների միջև. հայտարարված մոտավորություն)։", "2450ee08"]},
"OLAYLAR_EK6:1687-08-01:0":{"b": ["Պատրասի (Բալյաբադրա) կորուստը. Մորեայի հյուսիսային դարպասը", "b9cff63c"], "d": ["Կորնթոսի ծոցի մուտքին գտնվող Պատրասը Մորեայի և Ռումելիի միջև անցումը վերահսկող նավահանգիստն էր։ Երբ վենետիկյան բանակը գրավեց քաղաքը, ծոցի երկու ափերի բերդերը նույնպես իրար հետևից ընկան, և թերակղզին ցամաքից լիովին մեկուսացավ։ Այս գործողության վերջում ողջ Մորեան անցավ Վենետիկին. շրջանը մինչև 1715 թ. կառավարվելու էր «Regno di Morea» անունով։", "3b3ca389"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["Կորնթոսի զիջումը Վենետիկին", "9a25b6b9"], "d": ["Պատրասի անկումից հետո Կորնթոսը խաղաղ ճանապարհով թողնվեց վենետիկցիներին, և մուսուլման բնակչությունը լքեց քաղաքը։ 1687 թ. օգոստոսին Մորոզինիի բանակը Աթենքի արշավանքի համար հավաքվում էր Կորնթոսում։", "d92bcf7d"]},
"OLAYLAR_EK6:1687-12-17:0":{"b": ["Էգերի կորուստը", "983391aa"], "d": ["Էգերը (Էղրի) գրավվել էր 1596 թ. Մեհմեդ III-ի անձամբ մասնակցած արշավանքով և դարձել էր իր անունը կրող էյալեթի կենտրոն։ Հյուսիսային Հունգարիայում օսմանյան այս վերջին խոշոր բերդը, Մոհաչի երկրորդ պարտությունից հետո լիովին պաշարված վիճակում, մեկ տարի դիմադրեց և սովի պատճառով հանձնվեց։ Նրա կորստով Օսմանյան պետության հյուսիսային թևը Հունգարիայում ամբողջությամբ վերացվեց։", "ced01ee7"]},
"OLAYLAR_EK6:1688-05-19:0":{"b": ["Սեկեշֆեհերվարի (Իստոլնի Բելգրադ) կորուստը. հունգարական թագավորների թագադրման քաղաքը", "c6147255"], "d": ["Քաղաքը, որտեղ դարեր շարունակ թագադրվել ու թաղվել էին հունգարական թագավորները, 1543 թ. գրավել էր Կանունի Սուլեյմանը, և այն դարձել էր Բուդայի էյալեթի կարևորագույն սանջակային կենտրոններից մեկը։ Բուդայի անկումից մոտ երկու տարի անց շրջակայքից լիովին կտրված բերդը հանձնվեց։ Այս կորստով Դանուբից արևմուտք օսմանյան ներկայությունը սեղմվեց Սրեմի և Օսիեկի շրջակայքում։", "245ff91b"]},
"OLAYLAR_EK6:1689-02-03:0":{"b": ["Սիգետվարի կորուստը", "834910a7"], "d": ["Սիգետվարը այն բերդն էր, որի մոտ 1566 թ. Կանունի Սուլթան Սուլեյմանը մահացավ իր տասներեքերորդ և վերջին արշավանքում՝ պաշարումը դեռ շարունակվելիս. այդ պատճառով այն խորհրդանշական տեղ ուներ օսմանյան հիշողության մեջ։ Հարյուր քսաներեք տարի անց, երբ շրջակա բոլոր բերդերն ընկել էին, ճահիճներով պաշտպանված այդ բերդը նույնպես հանձնվեց։ Դամբարանը, որտեղ թաղված էին Կանունիի ներքին օրգանները, և շրջակա ավանը Հաբսբուրգների կառավարման տակ անցնելուց հետո քանդվեցին։ Նույն ամսաթվին ատլասում Օսմանյան պետությունից Հաբսբուրգներին անցած մյուս բնակավայրը՝ Բարչ, հետևում է Սիգետվարի գլխավոր կենտրոնի («ավագ» կենտրոնի) շղթային (Bánlaky 0017/1449. հայտարարված մոտավորություն)։", "12bc4465"]},
"OLAYLAR_EK6:1692-06-05:0":{"b": ["Վարադի կորուստը", "6cce360d"], "d": ["Վարադը Տրանսիլվանիա տանող առանցքային բերդն էր, որը 1660 թ. գրավել էր Քյոփրյուլյու Մեհմեդ փաշան և դարձրել իր անունը կրող էյալեթի կենտրոն։ Սլանկամենի պարտությունից հետո լիովին մենակ մնացած բերդը գրեթե երկու տարի տևած շրջափակումից հետո սովի պատճառով հանձնվեց։ Նրա կորստով Տրանսիլվանիայի վրա օսմանյան ազդեցությունը փաստացի ավարտվեց, և Հաբսբուրգների տիրապետությունը հաստատվեց Տիսայից արևելք։", "72d9fcc0"]},
"OLAYLAR_EK6:1693-05-27:0":{"b": ["Յանովայի կորուստը. Տրանսիլվանիայի ճանապարհի փակումը", "4b5e30d8"], "d": ["Յանովան 1658 թ. գրավված բերդ էր, որը պահում էր Վարադի և Թեմեշվարի միջև կապը։ Վարադի անկումից անմիջապես հետո, շրջակայքից կտրվելով, այն նույնպես կորսվեց։ Այսպիսով, Թեմեշվարի էյալեթը հյուսիսից լիովին մեկուսացավ և մինչև Կառլովիցի պայմանագիրը շարունակեց գոյությունը որպես Օսմանյան պետության ձեռքում մնացած միակ հունգարական հող։", "67168a2e"]},
"OLAYLAR_EK6:1697-01-01:0":{"b": ["Չեռնոգորիայում վլադիկայի կառավարման հաստատումը. Ցետինեի փաստացի անջատումը", "a924b778"], "d": ["Այն տարիներին, երբ Սրբազան լիգայի պատերազմը թուլացրել էր օսմանյան վերահսկողությունը Բալկաններում, Ցետինեի վանքի գլուխ կանգնած մետրոպոլիտությունը Պետրովիչների ընտանիքում դարձավ հորից որդի անցնող պաշտոն, և շրջանը փաստացի ձեռք բերեց առանձին կառավարում։ Լեռների անմատչելիության շնորհիվ այդ վլադիկությունը երկու հարյուր տարի գոյատևեց ո՛չ լիովին անկախ, ո՛չ էլ լիովին ենթակա կարգավիճակով. իրավաբանորեն նրա անկախությունը ճանաչվելու էր միայն 1878 թ. Բեռլինի պայմանագրով։", "104e26b1"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["Կորնթոսի վերագրավումը", "26f53e3a"], "d": ["Դամադ Ալի փաշայի Մորեայի արշավանքի առաջին մեծ կանգառը Կորնթոսն էր. օսմանցիները 1715 թ. հունիսին քաղաքը հետ գրավեցին վենետիկցիներից և այստեղից առաջ շարժվեցին թերակղզու մնացած մասը։", "82e2e719"]},
"OLAYLAR_EK6:1730-08-12:0":{"b": ["Նադիրի հարձակումը. Թավրիզի, Նախիջևանի, Համադանի, Քերմանշահի, Մարաղայի և Կասրե Շիրինի կորուստը", "d95efd59"], "d": ["Սեֆյան պետության անկումից օգտվելով՝ 1723-1727 թթ. գրավված Արևմտյան Իրանի քաղաքները Իրանում փաստացի իշխանությունը զավթած Նադիր խանի հարձակմամբ մեկը մյուսի հետևից կորսվեցին։ Ատրպատականում Արդաբիլն ու Խալխալը նույնպես անցան Նադիրի ձեռքը։ Համադանի, Քերմանշահի և Կասրե Շիրինի կորուստը Ստամբուլում ծանր արձագանք գտավ. այն, որ բանակը արշավանքի չէր ելնում և սպասում էր Ուսկյուդարում, ինչպես նաև կորուստը քողարկելու փորձերը դարձան վեց շաբաթ անց բռնկված Պատրոնա Հալիլի ապստամբության անմիջական պատճառներից մեկը։ Ատլասը Խոյի շղթային հետևող Քոթուրը նույնպես համարում է այդ օրը Օսմանյան պետությունից Սեֆյաններին անցած (Uluerler 2015, Turkish Studies 10/5, էջ 6. Քոթուրին հատուկ օր աղբյուրում նշված չէ. հայտարարված մոտավորություն)։", "412bd324"]},
"OLAYLAR_EK6:1735-06-19:0":{"b": ["Բաղավարդի (Ախուրյան) պարտությունը. Կովկասի կորուստը՝ հօգուտ Նադիր խանի", "4262f54c"], "d": ["Սեֆյան պետության անկումից օգտվելով՝ 1723-1725 թթ. գրավված կովկասյան էյալեթները հնարավոր եղավ պահել տասը տարի։ Իրանում փաստացի իշխանությունը զավթած Նադիր խանը Երևանի մոտ գտնվող Բաղավարդում ծանր պարտության մատնեց օսմանյան բանակը. սերդար Աբդուլլահ Քյոփրյուլյու փաշան զոհվեց ռազմի դաշտում։ Պարտությունից հետո մի քանի ամսում դատարկվեցին Երևանը, Թիֆլիսը, Գանձակը և Շիրվանը։ Արևելյան սահմանը վերադարձավ 1639 թ. Կասրե Շիրինի գծին, ինչը հաստատվելու էր 1746 թ.։", "f123b2d9"]},
"OLAYLAR_EK6:1770-09-27:0":{"b": ["Բենդերի կորուստը՝ հօգուտ ռուսների", "0daca453"], "d": ["Կագուլի (Քարթալ դաշտի) պարտությունից հետո օսմանյան բանակը նահանջել էր Դանուբից հարավ, և Մոլդովայի ու Օզիի միջև գտնվող բերդերը մնացել էին միայնակ։ Դնեստր (Թուրլա) գետի անցման կետը պահող Բենդերը երկամսյա պաշարումից հետո գրոհով վերցվեց. քաղաքը կողոպտվեց։ Բերդի կորուստը կտրեց հյուսիսային սևծովյան պաշտպանական գծի միջին օղակը, որից հետո ընկան նաև Աքքերմանը և Կիլիան։ Քյուչուկ Կայնարջիի պայմանագրով Բենդերը վերադարձվելու էր, բայց 1806 թ. կրկին կորսվելու էր։", "483d1fad"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["Քուվեյթի Սաբահյան ամիրայության անցումը օսմանյան հովանավորության տակ", "3584dba0"], "d": ["Ըստ TDV-ի «Քուվեյթ» հոդվածի՝ նավամատույցը 18-րդ դարի սկզբին հիմնել էր Նեջդից եկած Ութուբ ցեղը, իսկ Սաբահյան ընտանիքը դարավերջին ստանձնել էր կառավարումը։ Նույն տարիներին, երբ Լահսան անցավ Սաուդյանների ձեռքը, վահաբիական ճնշման առջև Բասրային հենվելուց բացի այլ ընտրություն չունեցող ամիրայությունն անցավ օսմանյան հովանավորության տակ։ Կապը պաշտոնականացվելու էր 1871 թ. Միդհաթ փաշայի Բասրայի վարչական կարգավորմամբ, և Քուվեյթը համարվելու էր Բասրայի սանջակի երեք կազաներից մեկը. Իրաքի հետագա տարածքային պահանջը նույնպես հիմնվում է այս գրառման վրա։", "c084f05f"]},
"OLAYLAR_EK6:1806-01-01:0":{"b": ["Մեքքայի կորուստը՝ հօգուտ վահաբիների", "2da23acd"], "d": ["Նեջդում ծնված վահաբիական շարժումը Սաուդ բ. Աբդուլազիզի օրոք ուղղվեց դեպի Հիջազ. Թաիֆից և Մեդինայից հետո Մեքքան նույնպես երկրորդ անգամ գրավվեց. Մեքքայի ամիր Շերիֆ Ղալիբը, ամիրությունում մնալու պայմանով, քաղաքը հանձնեց վահաբիներին։ Դամբարանները քանդվեցին, և կտրվեց Դամասկոսից ու Կահիրեից եկող հաջի քարավանների ճանապարհը. այդ տարիներին ընդհատվեց նաև փադիշահի՝ ամեն տարի Հարամեյն ուղարկվող սուրրեն (դրամական ընծան). մինչև 1915 թ. անընդմեջ շարունակված այդ հատկացման միակ բացառությունը վահաբիական տիրապետության շրջանն է։ Քանի որ Հարամեյնի (երկու սրբավայրերի) հովանավորի կարգավիճակը փադիշահի լեգիտիմության հիմնական հենարաններից էր, այս կորուստը, տարածքի կորստից անդին, ծանր քաղաքական հարված եղավ. այն հետ գրավելը տևելու էր յոթ տարի և հնարավոր էր դառնալու Կավալալի Մեհմեդ Ալի փաշայի բանակով։", "888df9e3"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["Դուբրովնիկի հանրապետության վախճանը. ֆրանսիական օկուպացիա", "f8e27bf1"], "d": ["Կամպո Ֆորմիոյի պայմանագրով (1797) Դալմաթիայի ափին հաստատված ֆրանսիացիները 1806 թ. մայիսի 27-ին գրավեցին Դուբրովնիկը և վերջ դրեցին փոքրիկ վաճառականական հանրապետությանը։ Այսպիսով, ավարտվեց Դուբրովնիկի երեքուկես դարյա ենթակա կարգավիճակը, որի շնորհիվ նա 1458 թ. ի վեր, Օսմանյան պետությանը հարկ վճարելով, պահպանել էր իր ինքնավարությունն ու առևտրական արտոնությունները. քաղաքը և հանրապետության Մլյետ կղզին քարտեզի վրա անցնում են անմիջական ֆրանսիական կառավարման տակ։", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["Սուխումի կորուստը՝ հօգուտ ռուսների. արևելյան սևծովյան ափի բացումը", "adc96bd4"], "d": ["1806-1812 թթ. ռուս-թուրքական պատերազմում ռուսական նավատորմը ուղղվեց դեպի Սև ծովի արևելյան ափ և գրավեց Սուխում-Կալեն, որի վրա հենվում էր օսմանյան տիրապետությունը Աբխազիայում։ Բերդը կովկասյան ցեղերի հետ կապի և ծովափնյա առևտրի կենտրոնն էր։ Նրա կորստով Ռուսաստանն առաջին անգամ մշտապես հաստատվեց Սև ծովի արևելյան ափին. Օսմանյան պետության ազդեցությունը Կովկասում սեղմվեց Անապայի և Փոթիի շրջակայքում։", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["Պարգայի հանձնումը օսմանյան կառավարմանը", "66e0cc5d"], "d": ["Պարգան 1401 թ. ի վեր Վենետիկի ձեռքում էր և երբեք չէր անցել օսմանյան կառավարման տակ. Վենետիկի անկումից հետո այն հաջորդաբար անցավ Ֆրանսիային և Անգլիային։ TDV-ի «Թեփեդելենլի Ալի փաշա» հոդվածը իրավիճակն այսպես է ամփոփում. քաղաքը հանձնվեց անգլիացիներին և Ալի փաշայի կառավարմանը թողնվեց միայն 1819 թ.։ Փոխանցումն ավարտվեց բնակչության մեծ մասի գաղթով դեպի Իոնական կղզիներ։ Այսպիսով, Պասարովիցի պայմանագրով Վենետիկին թողնված Պրևեզա-Պարգա-Վոնիցա եռյակի վերջինը նույնպես միացավ կայսրությանը. Պարգան իննսունչորս տարի օսմանյան էր մնալու։", "555a1119"]},
"OLAYLAR_EK6:1821-01-01:0":{"b": ["Արգոսի անցումը հույն ապստամբների ձեռքը", "be66a696"], "d": ["Մորեայի ապստամբության առաջին ամիսներին Արգոսը և շրջակայքը դուրս եկան օսմանյան կառավարումից և անցան հույն ապստամբների ձեռքը. 1821 թ. մայիսին քաղաքը դառնալու էր օսմանյան ուժերի հակագործողության թատերաբեմ։", "c3ea2041"]},
"OLAYLAR_EK6:1821-05-05:0":{"b": ["Ահմեդ Քիհայան գրավեց Արգոսը. քաղաքը կողոպտվեց և այրվեց", "d6d3ac7b"], "d": ["Ահմեդ Քիհայայի ուժերը Արգոսում հաղթեցին հույներին, կողոպտեցին և այրեցին քաղաքը. քաղաքը կարճ ժամանակով վերադարձավ օսմանյան վերահսկողության տակ։", "316a51a8"]},
"OLAYLAR_EK6:1821-05-15:0":{"b": ["Ահմեդ Քիհայան Արգոսում միացավ Տրիպոլիցայի մուսուլմաններին և շարժվեց Տրիպոլիցայի վրա", "9d679fd5"], "d": ["Ահմեդ Քիհայան Արգոսում միանալով Տրիպոլիցայի մուսուլմաններին՝ շարժվեց դեպի Տրիպոլիցա. Արգոսը կրկին անցավ հույն ապստամբների վերահսկողության տակ։", "596502da"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["Կորնթոսի անցումը հույն ապստամբներին", "892dcdc6"], "d": ["Հունական անկախության պատերազմի ժամանակ Ակրոկորինթոսն անցավ ապստամբների ձեռքը, և բերդի հրամանատար Քյամիլ բեյը գերի ընկավ։", "a7cb2c26"]},
"OLAYLAR_EK6:1822-07-24:0":{"b": ["Դրամալը Մահմուդ փաշան իր շտաբը հաստատեց Արգոսում", "c79abbfb"], "d": ["Դրամալը Մահմուդ փաշայի բանակը մտավ Արգոսի հարթավայր, և փաշան իր շտաբը հաստատեց Արգոս ավանում. քաղաքը կրկին անցավ օսմանյան վերահսկողության տակ։", "d931b635"]},
"OLAYLAR_EK6:1822-08-06:0":{"b": ["Դրամալը Մահմուդ փաշան սկսեց նահանջել Արգոսից", "5e5afb74"], "d": ["Արգոսի օկուպացիայից երկու շաբաթ չանցած նահանջել ստիպված եղած Դրամալը Մահմուդ փաշան սկսեց իր բանակի առաջին դիվիզիան հետ քաշել Կորնթոսի ուղղությամբ. Արգոսը կրկին անցավ հույն ապստամբների ձեռքը։", "9c49ab0c"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["Նավպլիոնի (Անաբոլու) կորուստը՝ հօգուտ ապստամբների", "1a67fa50"], "d": ["Մորեայի ամենահզոր ամրություններն ունեցող նավահանգիստ Նավպլիոնը, մեկ տարուց ավելի շրջափակումից հետո, սովի պատճառով հանձնվեց։ Բերդը ապստամբության սկզբից ի վեր թերակղզում օսմանյան վերահսկողության վերջին խոշոր հենարանն էր. նրա կորստով ողջ Մորեան անցավ ապստամբների ձեռքը։ Կարճ ժամանակ անց քաղաքը դառնալու էր նոր հունական պետության առաջին մայրաքաղաքը։", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-30:0":{"b": ["Նավպակտոսի (Իներահտը) անցումը հունական կառավարման տակ", "c9d19d4b"], "d": ["Կորնթոսի ծոցի հյուսիսային ափի Իներահտըն, որը մինչև հունական ապստամբությունը մնում էր օսմանյան ձեռքում, 1829 թ. ապրիլին կորսվեց և անցավ հունական կառավարման տակ. ավանի անունը վերափոխվեց հին դարաշրջանի Նավպակտոսի։ Քաղաքի մուսուլման և հրեա բնակչությունը լիովին անհետացավ, և այն վերածվեց փոքրիկ ավանի։", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["Ալժիրի ֆրանսիական օկուպացիան. երեք հարյուր տարվա օջախի վախճանը", "0be8f568"], "d": ["Պարտքի վեճից ծագած հովհարի միջադեպը պատրվակ բռնելով՝ Ֆրանսիան երեք տարի շրջափակման մեջ պահեց Ալժիրի ափը, ապա զորք ափ իջեցրեց Սիդի Ֆերուխում։ Երեքշաբաթյա գործողության վերջում Հուսեյն դեյը անձնատուր եղավ, և ավարտվեց 1516 թ. ի վեր գոյատևող օսմանյան Ալժիրի օջախը։ Օկուպացիան մայրաքաղաքով չսահմանափակվեց. ներքին շրջանների Տլեմսենը, Շերշելը և Մեդեան նույնպես նույն ամռանը կորսվեցին։ Ամբողջ ափի անցումը ֆրանսիական վերահսկողության տակ տևելու էր ևս քսանչորս տարի։", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["Էվբեայի (Էղրիբոզ) հանձնումը Հունաստանին՝ կղզու հետ միասին (Կարիստոս, Օրեյ)", "7b524aa4"], "d": ["Հունական անկախության պատերազմի ողջ ընթացքում բուռն բախումների թատերաբեմ դարձած, բայց օսմանյան ձեռքում մնացած Էվբեան, խաղաղության պայմանագիրն ուժի մեջ մտնելուց հետո, 1831 թ. հանձնվեց հույներին։ 1470 թ. ի վեր կարևոր ծովային հենակետ եղած քաղաքի մուսուլման բնակչությունը, իր ողջ ունեցվածքը շատ էժան գներով վաճառելով, զանգվածաբար գաղթեց օսմանյան հողեր. քաղաքը երկար ժամանակ դատարկ մնաց, և գերմանացի ճանապարհորդ Ֆալմերայերը 1842 թ. այն անվանեց ուրվական քաղաք։", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["Օրանի (Վեհրան) օկուպացիան ֆրանսիացիների կողմից", "a8415d66"], "d": ["Իսպանիայի կողմից 1792 թ. առանց պատերազմի զիջված Օրանը Ալժիրից արևմուտք գտնվող ամենամեծ նավահանգիստն էր։ Մայրաքաղաքի անկումից վեց ամիս անց ֆրանսիական զորամասերը մտան քաղաք։ Այստեղից սկսված արևմտյան գործողությունը շուտով հանդիպելու էր ամիր Աբդ ալ-Կադիրի տասնհինգ տարի տևելիք դիմադրությանը։", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["Աննաբայի (Բոն) օկուպացիան", "21f37fb1"], "d": ["Թունիսի սահմանին մոտ գտնվող Արևելյան Ալժիրի նավահանգիստ Աննաբան գրավվեց ֆրանսիական ուժերի կողմից և վերածվեց Կոնստանտինի վրա արշավի հենակետի։ Քաղաքը միաժամանակ Սարդինիա կղզու դիմաց գտնվող ամենամոտ աֆրիկյան նավահանգիստն էր։", "1ca5b213"]},
"OLAYLAR_EK6:1833-04-12:0":{"b": ["Աթենքի զիջումը նոր հունական պետությանը (այն օրը, երբ բավարական զորամասերը ընդունեցին Ակրոպոլիսի հանձնումը)", "deee4d37"], "d": ["1456 թ. ի վեր օսմանյան եղած Աթենքը հունական անկախության պատերազմի ընթացքում մի քանի անգամ ձեռքից ձեռք էր անցել, և Ակրոպոլիսի կայազորը 1827 թ. կրկին անցել էր օսմանյան վերահսկողության տակ։ Քանի որ Լոնդոնի արձանագրությամբ գծված սահմանից հյուսիս էր մնացել, քաղաքը փոխանցվեց նոր թագավորությանը, և կայազորը դատարկեց Ակրոպոլիսը։ Ատլասի օրը այն օրն է, երբ բավարական զորամասերը ընդունեցին Ակրոպոլիսի հանձնումը. օսմանյան կայազորի փաստացի ելքը տեղի ունեցավ մի քանի օր անց (St Clair, Who Saved the Parthenon?, Open Book Publishers, 2022, գլ. 13; Finlay, Journals and Letters, հ. I, էջ 67)։ Հաջորդ տարի Աթենքը Նավպլիոնի փոխարեն հռչակվեց Հունաստանի մայրաքաղաք։", "378db620"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["Բեջայայի (Բուժի) օկուպացիան", "a8927e00"], "d": ["Կաբիլիայի լեռների դեպի ծով բացվող Բեջայա նավահանգիստը Ալժիրի և Աննաբայի միջև ծովափնյա գծի վերջին անկախ օղակն էր։ Այն գրավվեց ծովային հրետանու աջակցությամբ. սակայն դրա հետևի լեռնային ներքին շրջանը ևս երեսուն տարի չէր անցնելու ֆրանսիական վերահսկողության տակ։ Ծովափի երկայնքով այս օկուպացիաները կազմում են օսմանյան Ալժիրի՝ քարտեզի վրա տարի առ տարի հալվելը։", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["Սետիֆի օկուպացիան", "2073731a"], "d": ["Մեկ տարի առաջ Կոնստանտինի անկումից հետո ֆրանսիական ուժերը բարձրացան բարձրավանդակ և, գրավելով հին հռոմեական Սետիֆ քաղաքը, այնտեղ մշտական կայազոր հաստատեցին։ Սետիֆը ծովափի և Սահարայի միջև քարավանային ճանապարհների հատման կետն էր. դրա օկուպացիան ցույց տվեց, որ Ֆրանսիան այժմ արդեն սկսել էր վերահսկել ոչ միայն նավահանգիստները, այլև ներքին առևտրի ցանցը։", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["Բիսկրայի օկուպացիան. Սահարայի դարպասի կորուստը", "d895cad0"], "d": ["Բիսկրան Ատլաս լեռների հարավային ստորոտի՝ դեպի Սահարա բացվող դարպասն էր և արմավենու օազիսների կենտրոնը։ Այն տարիներին, երբ սկսում էր կոտրվել ամիր Աբդ ալ-Կադիրի դիմադրությունը, նրա գրավմամբ ֆրանսիական վերահսկողությունն առաջին անգամ հասավ անապատի հյուսիսային եզրին։ Այսուհետ դա արդեն օազիս առ օազիս առաջ շարժվող անապատային գործողություն էր լինելու։", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["Տուգուրտի օկուպացիան. ողջ Ալժիրի կորուստը", "33c056e2"], "d": ["Սահարայի հյուսիսի օազիս քաղաք Տուգուրտի գրավմամբ 1830 թ. սկսված օկուպացիան ավարտվեց ներկայիս Ալժիրի հյուսիսային կեսում։ Այդ տարիներին Օսմանյան պետությունը Ղրիմի պատերազմում կռվում էր Ֆրանսիայի հետ նույն ճամբարում. Ալժիրի նկատմամբ իր իրավական հավակնությունից երբեք պաշտոնապես չհրաժարվելով՝ նա փաստացի ոչ մի քայլ անել չկարողացավ։ Հյուսիսային Աֆրիկայում նրա ձեռքում մնացած միակ հողը Տրիպոլիտանիան (Տրաբլուսգարբ) էր։", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["Էլ-Օբեյդի անկումը. Կորդոֆանի անցումը Մահդիի ուժերին", "58299f62"], "d": ["Իրեն մահդի հռչակած Մուհամմադ Ահմեդի սկսած շարժումը արագ տարածվեց Եգիպտոսի սուդանյան կառավարման դեմ։ Կորդոֆանի կենտրոն Էլ-Օբեյդը չորսամսյա պաշարումից հետո ընկավ և դարձավ ապստամբության մայրաքաղաքը. քաղաքի գանձարանն ու զինապահեստները հնարավորություն տվեցին, որ շարժումը վերածվի բանակի։ Սուդանը իրավաբանորեն դեռ Օսմանյան պետությանը ենթակա Եգիպտոսի խեդիվության տարածք էր, ուստի կորուստը քարտեզի վրա հանվում է կայսրության մարմնից։", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["Խարտումի անկումը. ողջ Սուդանի կորուստը", "d4b98464"], "d": ["Տասնամսյա պաշարումից հետո Մահդիի ուժերը մտան Կապույտ և Սպիտակ Նեղոսների միախառնման կետում գտնվող Խարտումը. քաղաքի կուսակալ Գորդոնը սպանվեց, իսկ օգնության ուղարկված անգլիական զորասյունը ուշացավ երկու օր։ Այդ ժամանակից ի վեր ողջ Սուդանը, ներառյալ Սենարը, Դոնգոլան և Կորդոֆանը, տասնչորս տարի մնաց Մահդիի պետության կառավարման տակ։ Շրջանը միայն 1899 թ., օսմանյան կապն ամբողջությամբ խզված վիճակում, անցնելու էր անգլո-եգիպտական համատեղ կառավարման տակ։", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["Մասսաուայի իտալական օկուպացիան. Կարմիր ծովի արևմտյան ափի կորուստը", "c333b95b"], "d": ["Հաբեշի էյալեթի կենտրոն Մասսաուա նավահանգիստը օկուպացրեց Իտալիան՝ օգտվելով Սուդանը պատած մահդիական ապստամբության խառնաշփոթից. դա կազմեց իտալական Էրիթրեայի միջուկը։ Հյուսիսում գտնվող Սուակինը և ծովում գտնվող Դահլակ արշիպելագը նույնպես կորսվեցին նույն գործընթացում։ Այսպիսով, ավարտվեց Յավուզ Սուլթան Սելիմի ժամանակներից գոյատևող օսմանյան տիրապետությունը Կարմիր ծովի արևմտյան ափին, և ծովն այժմ երկու ափով էլ դարձավ օտար ջուր։", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["Հռոդոսի իտալական օկուպացիան", "e08662c5"], "d": ["Տրիպոլիտանիայի (Տրաբլուսգարբի) պատերազմում Օսմանյան պետությանը բանակցությունների սեղան նստեցնել ցանկացող Իտալիան, պատերազմը տեղափոխելով Միջերկրական ծով, զորք ափ իջեցրեց Հռոդոսում։ Կղզին մի քանի օրում գրավվեց։ Այսպիսով, 1522 թ. Կանունի Սուլեյմանի կողմից երկարատև պաշարումով գրավված և երեք հարյուր իննսուն տարի պահված Հռոդոսը դադարեց լինել կայսրության խոշորագույն կղզային հենակետը Արևելյան Միջերկրածովում. թեև Ուշիի պայմանագրում այն համարվում էր ժամանակավոր օկուպացիա, այլևս երբեք հետ չգրավվեց։", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["Դոդեկանեսի (Տասներկու կղզիների) իտալական օկուպացիան", "200aacf2"], "d": ["Հռոդոսի գրավումից մեկ շաբաթվա ընթացքում իտալական նավատորմը օկուպացրեց նաև շրջակա կղզիները. այդ արշիպելագը հետագայում կոչվելու էր «Դոդեկանես» (Տասներկու կղզիներ)։ Կղզիների մեծ մասը Անատոլիայի ափից մի քանի մղոն հեռավորության վրա էր և վերահսկում էր Էգեյան ծովի հարավարևելյան անցումը։ Օկուպացիան Ուշիի պայմանագրով համարվեց ժամանակավոր՝ Տրիպոլիտանիան թողնելու դիմաց, սակայն Իտալիան երբեք չդատարկեց կղզիները. 1947 թ. դրանք փոխանցվելու էին Հունաստանին։", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["Կոսի (Իսթանքյոյ) օկուպացիան", "ab246c62"], "d": ["Դոդեկանեսի գործողության վերջին օղակը՝ Կոսը, Բոդրումի թերակղզու ուղիղ դիմաց գտնվող բերրի և բազմամարդ կղզին էր։ Օկուպացիայով Էգեյան ծովի հարավարևելյան անկյան բոլոր կղզիները անցան իտալական վերահսկողության տակ, և Անատոլիայի հարավարևմտյան ափն իր ողջ երկայնքով շրջապատվեց օտար կղզիների շղթայով։", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["Իկարիայի (Նիկարիա) անկախության հռչակումը", "c4452033"], "d": ["Սամոսի և Քիոսի միջև գտնվող փոքրիկ Իկարիա կղզում ժողովուրդը, իտալական օկուպացիաների ստեղծած անորոշության պայմաններում ապստամբելով, կղզուց դուրս վտարեց օսմանյան ժանդարմերիան և իր դրոշով, դրոշմանիշով ու խորհրդարանով հռչակեց հինգ ամիս գոյատևած «ազատ պետություն»։ 1912 թ. նոյեմբերին կղզին միացավ Հունաստանին։ Չնայած իր փոքրությանը՝ այս դեպքը ակնհայտ վկայությունն է այն բանի, թե ինչպես էր քայքայվում կենտրոնական կառավարումը Էգեյան ծովում։", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["Սամոսի դուրս գալը օսմանյան կառավարումից", "3a862f2b"], "d": ["Սամոսը 1832 թ. ի վեր ինքնավար ամիրայություն էր, որը հարկ էր վճարում Օսմանյան պետությանը և կառավարվում Ստամբուլի նշանակած բեյի կողմից։ Տրիպոլիտանիայի (Տրաբլուսգարբի) պատերազմի ստեղծած դատարկության պայմաններում կղզու միավորման կողմնակից շարժումը զավթեց իշխանությունը, և ինքնավար ամիրայության կարգը փաստացի ավարտվեց. նույն տարում կղզին հայտարարեց Հունաստանին միանալու մասին։ Անատոլիայի ափից երկու կիլոմետր հեռու գտնվող այս կղզին Էգեյան ծովում կորսված առաջին հողերից մեկն էր։", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["Յանինայի անկումը. Էպիրոսի և Պարգայի կորուստը", "d42fce18"], "d": ["Բալկանյան պատերազմում հինգ ամիս պաշարված Յանինան հանձնվեց Բիզանիի դիրքերի անկումից հետո. քաղաքի հետ միասին ողջ Էպիրոսն անցավ Հունաստանին։ Յանինայի սանջակին ենթակա Պարգան նույնպես այդ օրը կորսվեց, և ավարտվեց իննսունչորսամյա օսմանյան կառավարումը։ Յանինայի կորուստը նշանակում էր կայսրության՝ դեպի Ադրիատիկ բացվող վերջին պատուհանի փակումը։", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["Ադրիանապոլսի (Էդիրնե) անկումը բուլղարների ձեռքը", "459d2e56"], "d": ["Հինգուկես ամիս տևած պաշարումից հետո զինամթերքն ու պարենը սպառած Ադրիանապոլիսը (Էդիրնե) հանձնվեց. Շյուքրյու փաշան գերի ընկավ։ 1361 թ. ի վեր օսմանյան և իննսուներկու տարի մայրաքաղաք եղած քաղաքի անկումը համարվեց Բալկանյան պատերազմի ամենածանր հարվածը։ Ադրիանապոլիսը չորս ամիս անց՝ Բալկանյան երկրորդ պատերազմում, օգտվելով Բուլղարիայի մյուս ճակատներում կրած փլուզումից, հետ էր գրավվելու։", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["Յանբուի կորուստը՝ հօգուտ Շերիֆ Հուսեյնի ուժերի", "e291c816"], "d": ["Շերիֆ Հուսեյնի հունիսին սկսած ապստամբությունը տարածվեց Կարմիր ծովի ափով. Մեդինայի նավահանգիստ Յանբուն բրիտանական նավատորմի աջակցությամբ անցավ ապստամբների ձեռքը։ Նավահանգիստը դարձավ ապստամբությանը դրսից ստացվող զենքի և փողի հոսքի հիմնական դարպասը։ Այսպիսով, Մեդինայում գտնվող Ֆահրեդդին փաշայի ուժերի կապը ծովի հետ կտրվեց, և քաղաքը մնաց միայնակ՝ Հիջազի երկաթուղու ծայրին։", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["Գազայի երրորդ ճակատամարտը. Գազայի և Խան Յունիսի կորուստը", "c142a069"], "d": ["Երկու անհաջող փորձից հետո Ալենբին իր երրորդ հարձակման ժամանակ, Բեերշեբայի (Բիրուսսեբի) կողմից շրջանցելով, ճեղքեց ճակատը, և վեց ամիս պահված Գազայի գիծը փլուզվեց։ Գազան և նրանից հարավ գտնվող Խան Յունիսը դատարկվեցին նույն օրը։ Այս ճեղքումը դարձավ Պաղեստինի ճակատի քայքայման սկիզբը. Երուսաղեմը ընկնելու էր հինգ շաբաթ անց։", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["Կոմոտինիի (Գյումյուլջինե) օկուպացիան. Արևմտյան Թրակիայի կորուստը", "904d813c"], "d": ["Մուդրոսից հետո նախ Անտանտի զորամասերի վերահսկողության տակ անցած Արևմտյան Թրակիան Սան Ռեմոյի համաժողովի որոշմամբ տրվեց Հունաստանին, և հունական բանակը մտավ Կոմոտինի։ 1913 թ. Բուլղարիայից հետ գրավված այդ շրջանը դարձավ Ռումելիում կայսրության կորցրած վերջին հողը։ Շրջանի թուրք բնակչության կարգավիճակը երեք տարի անց Լոզանում կարգավորվելու էր փոքրամասնությունների ռեժիմով։ Այս օկուպացիայով Արևմտյան Թրակիայի Կոմոտինիի, Քսանթիի (Իսքեչե), Դեդեաղաչի և Սուֆլիի կազաներն անցան Հունաստանին։", "ef0aeba3"]},
"OLAYLAR_EK7:1335-12-01:0":{"b": ["Իլխանական պետության կազմալուծումը. Աբու Սաիդ Բահադուր խանի մահը", "0f187469"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Իլխանականներ» հոդվածի՝ Աբու Սաիդի մահը՝ առանց ժառանգ թողնելու, հանգեցրեց մեկ դար Իրանում իշխած Իլխանական պետության տրոհմանը. էմիրները, օգտվելով գահակալական կռիվներից, հիմնեցին Ջալայիրյանների, Կարա-Կոյունլուների, Մուզաֆֆարյանների, Խորասանի սարբեդարների և Էրեթնաօղուլների նման տեղական հարստություններ։ Այս կազմալուծումը տարածաշրջանը բաժանեց մեկ դար տևելիք բեյությունների խճանկարի, որը ի վերջո կրկին միավորվելու էր Լենկթեմուրի արշավանքներով։", "ebf54b53"]},
"OLAYLAR_EK7:1387-01-01:0":{"b": ["Լենկթեմուրը իր տիրապետության տակ է առնում Իրանի մեծ մասը", "1cee2b82"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Թեմուր» հոդվածի՝ 1380-ական թվականների սկզբից հետիլխանական տեղական հարստությունները, ինչպիսիք էին սարբեդարները, Քարթերը և Մուզաֆֆարյանները, մեկ առ մեկ վերացրած Լենկթեմուրը 1386-1388 թթ. «եռամյա արշավանքի» ընթացքում փաստացի իր տիրապետության տակ առավ Իրանի մեծ մասը. Մուզաֆֆարյան հարստությանը վերջնական վախճան էր դրվելու 1393 թ.։ Այսպիսով, մեկ դարի մասնատվածությունից հետո տարածաշրջանը կրկին ենթարկվեց մեկ կենտրոնական իշխանության։", "aaab87fe"]},
"OLAYLAR_EK7:1406-10-15:0":{"b": ["Արաքսի հաղթանակը. Կարա Յուսուֆը հաղթեց Թեմուրյան Աբու Բաքր միրզային", "4b61a75a"], "d": ["Լենկթեմուրի 1405 թ. մահից հետո աքսորից վերադարձած Կարա-Կոյունլու բեյ Կարա Յուսուֆը, գրավելով Ավնիքը և կրկին տիրանալով Արևելյան Անատոլիայի իր հողերին, արշավեց Ատրպատականի և երկու Իրաքների տերը համարվող՝ Լենկթեմուրի թոռ Աբու Բաքր միրզայի վրա և Արաքսի ափին հաղթեց նրան։ Այս հաղթանակը Թավրիզը չտվեց Կարա-Կոյունլուներին. TDV `tebriz`-ը գրում է, որ 1408 թ. քաղաքը Աբու Բաքր միրզայի ձեռքում էր. Ատրպատականը ձեռք բերելու ճակատամարտը Սարդրուդի ճակատամարտն էր 1408 թ. ապրիլի 13-ին։", "38fdfcfd"]},
"OLAYLAR_EK7:1408-04-13:0":{"b": ["Սարդրուդի հաղթանակը. Թավրիզն ու Ատրպատականը անցան Կարա-Կոյունլուներին", "1f0a429d"], "d": ["Կարա Յուսուֆը Արաքսից հետո երկրորդ անգամ հաղթեց Թեմուրյան Աբու Բաքր միրզային Թավրիզի մոտ գտնվող Սարդրուդում. այս հաղթանակը Ատրպատականը ձեռք բերեց Կարա-Կոյունլուների համար։ Այնուհետև Կարա Յուսուֆը Բիստամ բեյին հանձնարարեց գրավել Իրաք-ի Աջեմը (Պարսկական Իրաքը);", "10fb176b"]},
"OLAYLAR_EK7:1466-01-01:0":{"b": ["Ժանտախտի համաճարակ Ստամբուլում և պալատի տեղափոխումը Ադրիանապոլիս (Էդիրնե)", "70c7a163"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Ստամբուլ» հոդվածի՝ քաղաքի արագ և խիտ բնակեցումը ժամանակ առ ժամանակ նպաստավոր պայմաններ էր ստեղծում համաճարակային հիվանդությունների տարածման համար. 1466 թ. ժանտախտի համաճարակի ժամանակ պալատը և պետական ավագանին ժամանակավորապես տեղափոխվեցին Ադրիանապոլիս (Էդիրնե)։ Նման համաճարակների ժամանակ քաղաքի բնակչությունը լուրջ կորուստներ ունեցավ։", "7b20238c"]},
"OLAYLAR_EK7:1469-04-01:0":{"b": ["Ուզուն Հասանը վերջ է դնում Կարա-Կոյունլու պետությանը", "ef68399e"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Ուզուն Հասան» հոդվածի՝ Ակ-Կոյունլու տիրակալ Ուզուն Հասանը Կարա-Կոյունլու տիրակալ Ջիհան Շահին Բինգյոլ-Սանջաքի շրջանում 872 թ. ռաբի աս-սանիի 12-ին / 1467 թ. նոյեմբերի 10-ին հաղթեց և սպանեց. Ջիհան Շահի որդի Հասան Ալին 1468 թ. սեպտեմբերին Մարանդում պարտվեց, 1469 թ. ապրիլ-մայիսին Համադանի մոտ սպանվեց, և Կարա-Կոյունլու պետությանը վերջնականապես վերջ դրվեց։ Հողերն անցան Ակ-Կոյունլուների տիրապետության տակ. հաջորդ տասնամյակում պետությունն ընդարձակվելու էր մինչև Իրանի խորքերը։", "8b916ceb"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["Սահնը Սեման մեդրեսեների բացումը ուսուցման համար", "021f2a83"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Սահնը Սեման» հոդվածի՝ Ֆաթիհի համալիրի կազմում հիմնված այս ութ մեդրեսեները մտահղացվել էին որպես ժամանակի ամենաբարձր մակարդակի ուսումնական հաստատություն և կազմում էին օսմանյան ուլեմական (իլմիյե) աստիճանակարգության գագաթը։ Այստեղ դասավանդելը և այստեղից շրջանավարտ լինելը հետագա դարերում կադիի և մուդերրիսի կարիերայի ամենահեղինակավոր աստիճանն էր համարվում։", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["Թոփքափը պալատի (Սարայը Ջեդիդ) ավարտը", "d2db6323"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Թոփքափը պալատ» հոդվածի՝ ժամանակի աղբյուրները տարաձայնում են շինարարության սկզբի և ավարտի թվականների հարցում. Բաբը Հումայունի արձանագրության 883 (1478) թվականի համաձայն՝ Ֆաթիհի հրամանով, հավանաբար, 1465 թ. սկսված շինարարությունը մինչև այդ տարին հիմնականում ավարտված էր, և պալատը փոխարինեց հին պալատում գտնվող պետական կենտրոնին։ Այսպիսով, փադիշահը տեղափոխվեց իր նոր նստավայրը, որը երեք դար լինելու էր պետության վարչական և արարողակարգային սիրտը։", "5dfffded"]},
"OLAYLAR_EK7:1481-05-22:0":{"b": ["Բայազիդ II-ի գահակալումը Ստամբուլում", "9b686d04"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Բայազիդ II» հոդվածի՝ Ամասիայի սանջակի բեյ շեհզադե Բայազիդը, լսելով հոր մահվան լուրը, շտապ եկավ Ստամբուլ և գահ բարձրացավ. ենիչերիների աջակցությամբ նա առաջ անցավ իր եղբայր Ջեմից, որը ճանապարհ էր ընկել Կոնիայից։ Գահակալման ժամանակ ենիչերիներին, ըստ սովորույթի, բաժանվեց գահակալական նվեր (ջուլուս բահշիշի)։ Գահի այս փոփոխությունը բոցավառեց նաև երկու եղբայրների միջև պայքարի պատրույգը։", "7ea657ef"]},
"OLAYLAR_EK7:1481-05-28:0":{"b": ["Ջեմ սուլթանը Բուրսայում իրեն սուլթան է հռչակում", "b355168a"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Ջեմ սուլթան» հոդվածի՝ Կարամանի վրայով Բուրսա հասած Ջեմը, գրավելով քաղաքը, իրեն սուլթան հռչակեց և իր անունով խութբա կարդալ տվեց։ Այս կարճատև սուլթանությունն ավարտվեց, երբ նրա ավագ եղբոր՝ Բայազիդ II-ի ուղարկած ուժերը Ենիշեհիրում հաղթեցին Ջեմին։ Պարտությունից հետո Ջեմը ստիպված եղավ փախչել Եգիպտոս։", "18506663"]},
"OLAYLAR_EK7:1482-11-18:0":{"b": ["Գեդիք Ահմեդ փաշայի մահապատիժը", "6d75a58c"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Գեդիք Ահմեդ փաշա» հոդվածի՝ Օտրանտոյի արշավանքով և մեծ վեզիրությամբ հայտնի փաշան Ջեմ սուլթանի հարցում իր դիրքորոշման և նրա ազդեցությունից եղած մտահոգության պատճառով Բայազիդ II-ի հրամանով Ադրիանապոլսում (Էդիրնե) մահապատժի ենթարկվեց։ Ֆաթիհի օրոքի ամենափորձառու զորավարներից մեկի մահը մեծ արձագանք գտավ պալատում։", "59d06e3a"]},
"OLAYLAR_EK7:1493-01-01:0":{"b": ["Ստամբուլում առաջին տպարանի հիմնումը", "04475930"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Տպարան» հոդվածի՝ Իսպանիայից եկած հրեա գաղթականներ Դավիթ և Սամուել իբն Նահմիաս եղբայրները Ստամբուլում հիմնեցին եբրայական տառերով տպագրող առաջին տպարանը։ Այն գրանցվեց որպես օսմանյան հողերում գործող առաջին տպարանական նախաձեռնություն. արաբատառ թուրքերեն տպագրությունը հնարավոր էր դառնալու շատ ավելի ուշ՝ 18-րդ դարում։", "118df98b"]},
"OLAYLAR_EK7:1501-07-01:0":{"b": ["Շահ Իսմայիլի կողմից Թավրիզի գրավումը. Սեֆյան պետության հիմնումը", "014d81e6"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Սեֆյաններ» և «Ակ-Կոյունլուներ» հոդվածների՝ Արդաբիլի թեքքեի երիտասարդ շեյխ Իսմայիլը Անատոլիայի իր ղըզլբաշ մուրիդներից կազմած բանակով Նախիջևանի շրջանում ծանր պարտության մատնեց Ակ-Կոյունլու սուլթան Էլվենդին. Էլվենդը փախավ Դիարբեքիր, իսկ Իսմայիլը մտավ Թավրիզ, գահ նստեց և տասներկու իմամների շիիզմը հռչակեց պաշտոնական դավանանք։ Այսպիսով, փակվեց թե՛ Ակ-Կոյունլուների տիրապետությունը, թե՛ տարածաշրջանի հետիլխանական բեյությունների ժամանակաշրջանը. հիմնվեց երեք դար տևելիք Սեֆյան պետությունը։", "d6b169b7"]},
"OLAYLAR_EK7:1509-09-14:0":{"b": ["Ստամբուլի «Փոքր Ահեղ դատաստան» երկրաշարժը", "53e3b1d6"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Ստամբուլ» հոդվածի՝ քաղաքին հարվածած ուժեղ երկրաշարժը ժամանակին ժողովրդի մեջ կոչվեց «Փոքր Ահեղ դատաստան» (Քյուչուք Քըյամեթ). պարիսպները, մզկիթները և բազմաթիվ շենքեր ծանր վնասներ կրեցին, եղան բազմաթիվ մարդկային զոհեր։ Բայազիդ II-ի հրամանով քաղաքում սկսվեց լայնածավալ վերանորոգման և վերաշինության արշավ։", "47093985"]},
"OLAYLAR_EK7:1511-04-01:0":{"b": ["Շահքուլուի ապստամբության սկիզբը", "3d9a4a90"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Շահքուլու Բաբա Թեքելի» հոդվածի՝ սեֆյան քարոզչությունից սնվող Շահքուլուն Թեքեի շրջանում, իր շուրջ համախմբելով թուրքմենական լայն զանգված, սկսեց կրոնա-հասարակական բնույթի մեծ ապստամբություն։ Ապստամբությունը, լինելով ժամանակի ներքին անվտանգության ամենալուրջ ճգնաժամերից մեկը, խորապես ցնցեց պետության կենտրոնական իշխանությունը։", "3e064ec6"]},
"OLAYLAR_EK7:1512-06-10:0":{"b": ["Բայազիդ II-ի մահը Դիդիմոտիխոյի (Դիմեթոքա) ճանապարհին", "c46e98c9"], "d": ["Գահից հրաժարվելուց հետո իր ծննդավայր Դիդիմոտիխո մեկնելու համար Ստամբուլից հեռացած նախկին փադիշահը, առաջանալով պատգարակով, որը օրական հազիվ 5-6 կմ ճանապարհ էր անցնում, Չորլուի մոտ գտնվող Աբալար գյուղում վատ զգաց և 918 թ. ռաբի ալ-ավվալի 25-ին (1512 թ. հունիսի 10) մահացավ։ TDV İslâm Ansiklopedisi-ն մահվան պատճառը համարում է խիստ կասկածելի. որոշ տեղական և օտար աղբյուրների համաձայն՝ քննարկվում է թունավորման հնարավորությունը։ Այսպիսով, երեսունմեկամյա գահակալությունից հետո կյանքից հեռացավ Օսման Ղազիի տոհմից սերված ութերորդ փադիշահը։", "4a316f9a"]},
"OLAYLAR_EK7:1513-04-24:0":{"b": ["Շեհզադե Ահմեդի մահապատիժը Յավուզ Սելիմի հրամանով", "65abb2f2"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Սելիմ I» հոդվածի՝ իր հոր՝ Բայազիդ II-ի սիրելին և գահի գլխավոր մրցակիցը եղած շեհզադե Ահմեդը, իր եղբայր Սելիմի գահակալությունից հետո ձեռնարկած պայքարում, պարտվեց Ենիշեհիրի հարթավայրում և ռազմի դաշտից փախչելիս բռնվեց ու սպանվեց։ Այս դեպքով Սելիմը հիմնականում վերջ դրեց եղբայրների և եղբորորդիների միջև գահի մրցակցությանը։", "6cef6bf2"]},
"OLAYLAR_EK7:1523-06-27:0":{"b": ["Իբրահիմ փաշան նշանակվեց մեծ վեզիր", "9c94c1e3"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Իբրահիմ փաշա, Մաքբուլ» հոդվածի՝ հաս օդաբաշիի (սուլթանի առանձնասենյակի ղեկավարի) պաշտոնից Ռումելիի բեյլերբեյի աստիճանին և նույն օրը մեծ վեզիրության բարձրացված Իբրահիմ փաշան 929 թ. շաաբանի 13-ին (1523 թ. հունիսի 27) դարձավ մեծ վեզիր։ Սա պալատական ծառայությունից ուղղակի մեծ վեզիրության անցնելու աննախադեպ նշանակում էր և ցույց էր տալիս Իբրահիմ փաշայի արտակարգ մտերմությունը Կանունի Սուլեյմանի հետ։", "d8908e00"]},
"OLAYLAR_EK7:1534-04-06:0":{"b": ["Բարբարոս Հայրեդդին փաշան նշանակվեց կապուդան փաշա (նավատորմի գլխավոր հրամանատար)", "a0ff6bab"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Բարբարոս Հայրեդդին փաշա» հոդվածի՝ Ալժիրում իր հաջողություններով հայտնի Հայրեդդին փաշան 1534 թ. ապրիլի 6-ին կանչվեց Ստամբուլ և նշանակվեց կապուդան փաշա և Միջերկրական ծովի կղզիների (Ջեզայիր-ի Բահր-ի Սեֆիդ) բեյլերբեյ։ Այս նշանակումը համարվում է օսմանյան նավատորմի վերակառուցման և Միջերկրական ծովում ծովային հզորության ինստիտուցիոնալացման սկիզբը։", "73332d17"]},
"OLAYLAR_EK7:1544-12-02:0":{"b": ["Ռյուսթեմ փաշան առաջին անգամ դարձավ մեծ վեզիր", "ddfcc014"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Ռյուսթեմ փաշա» հոդվածի՝ այն բանից հետո, երբ Հադըմ Սուլեյման փաշան մի վեզիրի հետ ունեցած տարաձայնության պատճառով պաշտոնանկ արվեց, 951 թ. ռամադանի 17-ին (1544 թ. դեկտեմբերի 2) Ռյուսթեմ փաշան նշանակվեց մեծ վեզիր։ Միհրիմահ սուլթանի հետ ամուսնության շնորհիվ պալատին ավելի մոտեցած Ռյուսթեմ փաշան այս պաշտոնով դարձավ Կանունի Սուլեյմանի ժամանակաշրջանի ամենաազդեցիկ պետական գործիչներից մեկը։", "05215a80"]},
"OLAYLAR_EK7:1545-10-01:0":{"b": ["Էբուսսուուդ էֆենդին դարձավ շեյխ ալ-իսլամ", "11ed04f8"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Էբուսսուուդ էֆենդի» հոդվածի՝ ութ տարի Ռումելիի կազասկեր եղած Էբուսսուուդ էֆենդին 952 թ. շաաբանին (1545 թ. հոկտեմբեր) նշանակվեց շեյխ ալ-իսլամ և այդ պաշտոնում մնաց քսանութ տարի տասնմեկ ամիս։ Կանունի Սուլեյմանի օրենսգրքերը շարիաթի իրավունքի հետ ներդաշնակեցնող իր ֆեթվաներով հայտնի Էբուսսուուդ էֆենդին վճռորոշ դեր խաղաց իր ժամանակի իրավական և կրթական հաստատությունների ձևավորման գործում։", "bc622e58"]},
"OLAYLAR_EK7:1546-07-05:0":{"b": ["Մահացավ Բարբարոս Հայրեդդին փաշան", "3378a0bf"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Բարբարոս Հայրեդդին փաշա» հոդվածի՝ կարճատև հիվանդությունից հետո 953 թ. ջումադա ալ-ուլայի 6-ին (1546 թ. հուլիսի 5) նա մահացավ Ստամբուլում։ Բեշիքթաշում իր կառուցած մեդրեսեին կից դամբարանում թաղված Բարբարոսի մահը դիտվեց որպես օսմանյան նավատորմի հաստատած միջերկրածովյան գերակայության մի ժամանակաշրջանի փակում։", "c2863ce0"]},
"OLAYLAR_EK7:1550-06-01:0":{"b": ["Սկսվեց Սուլեյմանիե մզկիթի և համալիրի շինարարությունը", "101ec36f"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Սուլեյմանիե մզկիթ և համալիր» հոդվածի՝ ճարտարապետ Սինանի գլխավոր ճարտարապետությամբ 1550 թ. հիմնադրված համալիրը մտահղացվել էր որպես մեծ սոցիալական համալիր, որը մզկիթից բացի բաղկացած էր մեդրեսեներից, հիվանդանոցից (դարուշշիֆա), աղքատների ճաշարանից (իմարեթ) և գրադարանից։ Շինարարությունը Կանունի Սուլեյմանի գահակալության հզորությունը և Ստամբուլի կառուցապատումը խորհրդանշող ամենամեծ շինարարական ծրագրերից մեկն էր։", "cbcd3e9d"]},
"OLAYLAR_EK7:1552-06-01:0":{"b": ["Ստամբուլում և շրջակայքում սկսվեց ժանտախտի նոր ալիք", "547d6bf6"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Ժանտախտ» (Tâun) հոդվածի՝ իսլամական աշխարհի վրա ազդած 16-րդ դարի համաճարակներից մեկը տեղի ունեցավ 1552-1566 թթ. և հատկապես ազդեց Ստամբուլի, Անատոլիայի, Ռումելիի, Եգիպտոսի և Հյուսիսային Աֆրիկայի վրա։ Ընդլայնվող առևտրական ուղիները և բնակչության աճող շարժունությունը համարվում են այն գործոնները, որոնք կայսրության ամենահզոր ժամանակաշրջանում դյուրացրին համաճարակային հիվանդությունների տարածումը։", "a755c417"]},
"OLAYLAR_EK7:1553-10-05:0":{"b": ["Կարա Ահմեդ փաշան նշանակվեց մեծ վեզիր", "a7d7748e"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Կարա Ահմեդ փաշա» հոդվածի՝ երկրորդ վեզիրի պաշտոնը վարող Կարա Ահմեդ փաշան, գործող մեծ վեզիրի հանկարծակի պաշտոնանկությունից հետո, 960 թ. շավվալի 27-ին (1553 թ. հոկտեմբերի 5) բարձրացվեց մեծ վեզիրության աստիճանին։ Այս փոփոխությունը վկայում է մի ժամանակաշրջանի մասին, երբ շեհզադե Մուստաֆայի մահապատժին համընկնող օրերին պալատական ուժերի հավասարակշռությունն արագորեն փոխվում էր։", "40fe9b6d"]},
"OLAYLAR_EK7:1553-12-01:0":{"b": ["Մահապատժի ենթարկվեց կապուդան փաշա Փիրի ռեյիսը", "3b2ad7a0"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Փիրի ռեյիս» հոդվածի՝ երբ Եգիպտոս հասան այն մեղադրանքները, թե Հորմուզի պաշարումը վերացնելիս նա կաշառքի դիմաց թույլ է տվել կողոպտել մուսուլմանների ունեցվածքը և իր զորքը լքել է ռազմի դաշտում, հռչակավոր ծովագնացն ու քարտեզագիրը 960 թ. վերջում (1553 թ. վերջ) Կահիրեում մահապատժի ենթարկվեց։ Ունեցվածքը բռնագրավված Փիրի ռեյիսի մահը գնահատվում է որպես ժամանակի Բասրայի և Հնդկական օվկիանոսի ծովային քաղաքականությունում փաշաների միջև մրցակցության հետևանք։", "c410d0ce"]},
"OLAYLAR_EK7:1555-09-29:0":{"b": ["Կարա Ահմեդ փաշան մահապատժի ենթարկվեց, Ռյուսթեմ փաշան կրկին դարձավ մեծ վեզիր", "9a85076a"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Ռյուսթեմ փաշա» և «Կարա Ահմեդ փաշա» հոդվածների՝ 962 թ. զու-լ-կաադայի 13-ին (1555 թ. սեպտեմբերի 29) դիվանի նիստի ժամանակ հանկարծակի մահապատժի ենթարկված Կարա Ահմեդ փաշայի փոխարեն Ռյուսթեմ փաշան, Հյուրեմ և Միհրիմահ սուլթանների աջակցությամբ, նույն օրը երկրորդ անգամ նշանակվեց մեծ վեզիր։ Դեպքի կուլիսները աղբյուրներում բաց են մնացել և գնահատվել են որպես պալատական ինտրիգների արդյունք։", "54f3fd71"]},
"OLAYLAR_EK7:1558-04-15:0":{"b": ["Մահացավ Հյուրեմ սուլթանը", "1ae998b5"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Հյուրեմ սուլթան» հոդվածի՝ Կանունի Սուլեյմանի հասեքի սուլթանի կարգավիճակով տարիներ շարունակ պալատում մեծ ազդեցություն ունեցած Հյուրեմ սուլթանը 965 թ. ջումադա աս-սանիյայի 26-ին (1558 թ. ապրիլի 15) մահացավ Ստամբուլում և թաղվեց Սուլեյմանիե մզկիթի համալիրի իր դամբարանում։ 1534 թ. վալիդե սուլթան Հաֆսայի մահից հետո հարեմի վրա իր իշխանությունն ամրապնդած Հյուրեմ սուլթանի մահը վերացրեց նաև նրա որդիներ Բայազիդի և Սելիմի միջև գահի մրցակցության առջև կանգնած հավասարակշռող ազդեցությունը։", "d8c41dae"]},
"OLAYLAR_EK7:1565-06-29:0":{"b": ["Սոքոլլու Մեհմեդ փաշան բարձրացավ մեծ վեզիրության", "896391a2"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Սոքոլլու Մեհմեդ փաշա» հոդվածի՝ Սեմիզ Ալի փաշայի 972 թ. զու-լ-կաադայի 30-ի (1565 թ. հունիսի 29) մահից հետո մեծ վեզիրության բարձրացած Սոքոլլու Մեհմեդ փաշան դարձավ Կանունի Սուլեյմանի վերջին մեծ վեզիրը և, այդ պաշտոնը շարունակելով նաև Սելիմ II-ի և Մուրադ III-ի օրոք, դարձավ օսմանյան պատմության ամենաերկար պաշտոնավարած մեծ վեզիրներից մեկը։", "dfe55e0b"]},
"OLAYLAR_EK7:1566-09-24:0":{"b": ["Սելիմ II-ը հասավ Ստամբուլ և գահակալեց", "0289ef97"], "d": ["Կանունի Սուլթան Սուլեյմանի Սիգետվարում մահանալուց հետո Սոքոլլու Մեհմեդ փաշան, կարգը չխանգարելու համար, լուրը շաբաթներ շարունակ գաղտնի պահեց։ Ըստ TDV İslâm Ansiklopedisi-ի՝ Սելանիքին Սելիմի Ստամբուլ ժամանելու ամսաթիվը նշում է 974 թ. ռաբի ալ-ավվալի 15-ը (1566 թ. սեպտեմբերի 30), մինչդեռ ժամանակակից պատմաբանների մեծ մասը ճիշտ է համարում ռաբի ալ-ավվալի 9-ը (սեպտեմբերի 24)։ Կանունիի մահը պաշտոնապես հայտարարվեց միայն 1566 թ. հոկտեմբերի 24-25-ին Բելգրադում։", "66da7cdb"]},
"OLAYLAR_EK7:1572-06-13:0":{"b": ["Կըլըչ Ալի փաշայի վերստեղծած նավատորմը ծով իջավ", "d0fc9f48"], "d": ["Լեպանտոյի (Ինեբահթը) ծանր պարտությունից (1571 թ. հոկտեմբերի 7) հետո ողջ ձմեռ նավաշինարաններում նավեր կառուցվեցին։ Ըստ TDV İslâm Ansiklopedisi-ի՝ 980 թ. սաֆարի 1-ին (1572 թ. հունիսի 13) 250 գալերիից և մոտ 300 կամավոր ռեյիսների թիանավերից բաղկացած նոր նավատորմը ուժի ցուցադրությամբ ծով իջեցվեց։", "33415db2"]},
"OLAYLAR_EK7:1579-10-12:0":{"b": ["Սոքոլլու Մեհմեդ փաշան մահափորձի ենթարկվեց և սպանվեց", "6ffa8dec"], "d": ["Երեք փադիշահի օրոք տասնչորս տարի մեծ վեզիր եղած Սոքոլլու Մեհմեդ փաշան 987 թ. շաաբանի 20-ին (1579 թ. հոկտեմբերի 12) իր ապարանքի երեկոյան (իքինդի) դիվանում դաշույնով սպանվեց մի դերվիշի կողմից, որը մոտեցել էր, իբր, խնդրագիր հանձնելու։ Ըստ TDV İslâm Ansiklopedisi-ի՝ քննարկվում է, որ մահափորձը կարող էր կապված լինել մահապատժի ենթարկված համզավիյա շեյխ Համզա Բալիի վրեժի հետ։", "b1355377"]},
"OLAYLAR_EK7:1580-01-01:0":{"b": ["Անգլիայի հետ առաջին առևտրական ահիդնամեն. անգլիացիներին տրվեցին կապիտուլյացիաներ", "59c8e3ee"], "d": ["1578 թ. հոկտեմբերին Ստամբուլ ուղարկված անգլիացի ներկայացուցիչ Ուիլյամ Հարբորնը, Սոքոլլու Մեհմեդ փաշայի և Հոջա Սադեդդին էֆենդիի աջակցությամբ, Մուրադ III-ից ստացավ 1580 թ. թվագրված ահիդնամե։ Այս ահիդնամեով անգլիացի առևտրականները ձեռք բերեցին նույն չափով օգտվելու իրավունք այն առևտրական արտոնություններից (կապիտուլյացիաներ), որոնք նախկինում տրվել էին ֆրանսիացիներին և վենետիկցիներին։ Եղիսաբեթ I թագուհու և Մուրադ III-ի միջև նամակներ փոխանակվեցին, և երկու պետությունների միջև հաստատվեց նաև պաշտոնական հարաբերություն։ Այս արտոնություններից անմիջապես հետո՝ 1581 թ., Լոնդոնում հիմնվեց Levant Company-ն. անգլիացիները մինչև 1825 թ. իրենց առևտուրը տարածաշրջանում վարեցին այդ ընկերության միջոցով։", "c25734eb"]},
"OLAYLAR_EK7:1580-01-22:0":{"b": ["Ստամբուլի աստղադիտարանը քանդվեց փադիշահի ձեռագիր հրամանով", "3bc0c78c"], "d": ["Այն ֆեթվայի ազդեցությամբ, թե աստղադիտարանները դժբախտություն են բերում երկրներին, և պալատական ընդդիմության ազդեցությամբ, 987 թ. զու-լ-հիջջայի 4-ի (1580 թ. հունվարի 22) փադիշահի ձեռագիր հրամանով Ստամբուլի աստղադիտարանը քանդվեց իր բոլոր սարքերով։ Ըստ TDV İslâm Ansiklopedisi-ի՝ սա դարձավ Թաքիյուդդին ար-Ռասիդի հիմնած հաստատության կարճ կյանքի վախճանը։", "7b4f41fe"]},
"OLAYLAR_EK7:1582-05-29:0":{"b": ["Սկսվեց շեհզադե Մեհմեդի թլփատման հարսանիքը Աթմեյդանիում", "c2926d5d"], "d": ["Մուրադ III-ի որդի շեհզադե Մեհմեդը թլփատվեց 990 թ. ջումադա ալ-ուլայի 6-ին (1582 թ. մայիսի 29) սկսված և հիսունվեց-հիսունյոթ օր տևած շքեղ արարողություններով։ Ըստ TDV İslâm Ansiklopedisi-ի՝ Աթմեյդանիում կազմակերպված տոնախմբությունները ժամանակի ամենափառահեղ պալատական տոնակատարություններից էին։", "eaf7772a"]},
"OLAYLAR_EK7:1583-12-07:0":{"b": ["Մահացավ Նուրբանու վալիդե սուլթանը", "77d0a577"], "d": ["Մուրադ III-ի մայր Նուրբանու սուլթանը մահացավ 991 թ. զու-լ-կաադայի 22-ին (1583 թ. դեկտեմբերի 7)։ Ըստ TDV İslâm Ansiklopedisi-ի՝ որպես վալիդե սուլթան նա նամակագրություն էր վարել Վենետիկի և Ֆրանսիայի արքունիքների հետ, իսկ Վենետիկի սենատը նույն տարում համաձայնել էր նրա ծառայությունների դիմաց ուղարկել 2000 վենետիկյան ոսկի արժողությամբ նվեր։", "56b04854"]},
"OLAYLAR_EK7:1589-06-01:0":{"b": ["Խարդախված ակչեի պատճառով բռնկվեց Բեյլերբեյիի դեպքը", "db2f2e61"], "d": ["Երբ պետությունը վճարումներ կատարեց՝ իջեցնելով ակչեի արծաթի պարունակությունը, սիփահիներն ու ենիչերիները պաշարեցին պալատը և սկսեցին արյունալի ապստամբություն, որը պատմության մեջ մտավ Բեյլերբեյիի դեպք (Beylerbeyi Vak'ası) անունով։ Ըստ TDV İslâm Ansiklopedisi-ի «Աբդուլկադիր Շեյխի էֆենդի» հոդվածի՝ այս դեպքի պատճառով շեյխ ալ-իսլամը պաշտոնանկ արվեց։", "b1db5aea"]},
"OLAYLAR_EK7:1595-01-27:0":{"b": ["Մեհմեդ III-ը գահ բարձրացավ, տասնինը շեհզադե խեղդամահ արվեց", "2cd9a8c5"], "d": ["Մեհմեդ III-ը, իր հոր՝ Մուրադ III-ի մահից հետո, 1003 թ. ջումադա ալ-ուլայի 16-ին (1595 թ. հունվարի 27), ուրբաթ օրը, հասավ Ստամբուլ և գահ բարձրացավ։ Ըստ TDV İslâm Ansiklopedisi-ի՝ նույն գիշեր խեղդամահ արվեց տասնինը շեհզադե, որոնցից չորսը չափահաս էին (Մուստաֆա, Բայազիդ, Օսման և Աբդուլլահ). սա օսմանյան պատմության ամենաբազմամարդ եղբայրասպանությունն էր։", "fee571d5"]},
"OLAYLAR_EK7:1595-02-01:0":{"b": ["Սաֆիյե սուլթանը որպես վալիդե սուլթան ազդեցություն ձեռք բերեց", "000bec21"], "d": ["Մուրադ III-ի կին և Մեհմեդ III-ի մայր Սաֆիյե սուլթանը, իր որդու գահակալությամբ, որպես վալիդե սուլթան բարձրացավ պալատական քաղաքականության մեջ վճռորոշ դիրքի։ Ըստ TDV İslâm Ansiklopedisi-ի՝ այս շրջանում հարեմից բխող ազդեցությունը հասավ պետական գործերին ուղղակի միջամտելու աստիճանի։", "dcf5f731"]},
"OLAYLAR_EK7:1596-06-20:0":{"b": ["Ենիչերիների ճնշմամբ Մեհմեդ III-ը անձամբ դուրս եկավ արշավանքի", "d3c50656"], "d": ["Չնայած մեծ վեզիր Դամադ Իբրահիմ փաշայի առարկությանը՝ ենիչերիների ճնշմամբ Մեհմեդ III-ը, որպես Կանունի Սուլթան Սուլեյմանից հետո անձամբ բանակի գլուխ անցած առաջին փադիշահ, 1596 թ. հունիսի 20-ին Ստամբուլից դուրս եկավ արշավանքի։ Ըստ TDV İslâm Ansiklopedisi-ի՝ սա նշանակում էր ղազայի հին ավանդույթի վերակենդանացում։", "396dc19b"]},
"OLAYLAR_EK7:1600-06-01:0":{"b": ["1570-ական թվականներին սկսված ժանտախտի համաճարակը շարունակում էր ազդել Ստամբուլի վրա", "eb4ca37a"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Ժանտախտ» (tâun) հոդվածի՝ 1570-ական թվականներին սկսված համաճարակը իր ազդեցությունը պահպանեց մինչև 17-րդ դարի սկիզբը և հարվածեց առաջին հերթին Ստամբուլին, ինչպես նաև Անատոլիային, Բալկաններին, Եգիպտոսին և Հյուսիսային Աֆրիկային։ Համաճարակի շրջանները խրոնիկական սպառնալիք էին, որը հաճախ ընդհատում էր պալատական և քաղաքային կյանքը։", "3afd5ea1"]},
"OLAYLAR_EK7:1602-02-15:0":{"b": ["Մահացավ Կարայազըջը Աբդուլհալիմը, ապստամբական շարժումը թուլացավ", "876ca7a6"], "d": ["1601 թ. օգոստոսի 12-ին Էլբիստանի մոտ գտնվող Սեփեթլիում ծանր պարտություն կրած և վիրավոր նահանջած Կարայազըջը Աբդուլհալիմը մահացավ 1010 (1602) թ.։ Ըստ TDV İslâm Ansiklopedisi-ի՝ մահվան լուրը Ստամբուլ հասավ 1010 թ. ռամադանին (1602 թ. փետրվար-մարտ). աղբյուրները նշում են, որ վիճելի է, թե նրա մահը վերքի հետևանք էր, թե իր մարդկանց ձեռքով էր։", "f9c28a0d"]},
"OLAYLAR_EK7:1603-12-23:0":{"b": ["Եղբայրասպանության ավանդույթի փաստացի ավարտը", "9046c607"], "d": ["Ահմեդ I-ը իր գահակալման ժամանակ, ի տարբերություն նախորդ փադիշահների, չսպանել տվեց իր եղբորը՝ շեհզադե Մուստաֆային, այլ խնայեց նրա կյանքը. այս որոշումը համարվում է օսմանյան ժառանգման համակարգում ավագագույնի (էքբեր-էրշեդ) սկզբունքի փաստացի ընդունման սկիզբը։ TDV İslâm Ansiklopedisi-ի «Մուստաֆա I» հոդվածը հայտնում է, որ այդ ժամանակից ի վեր Մուստաֆան պալատում փակ կյանք էր վարում։ Այս պրակտիկան փաստացի վերջ դրեց դարեր շարունակ տևած գահակալական սպանություններին։", "7734428a"]},
"OLAYLAR_EK7:1609-08-09:0":{"b": ["Դրվեց Սուլթանահմեդ մզկիթի հիմքը", "1683262f"], "d": ["Ահմեդ I-ի հրամանով Աթմեյդանիում արարողությամբ դրվեց այն մզկիթի հիմքը, որը կառուցելու էր ճարտարապետ Սեդեֆքյար Մեհմեդ աղան։ Ըստ TDV İslâm Ansiklopedisi-ի «Սուլթան Ահմեդի մզկիթ և համալիր» հոդվածի՝ կառույցը, լինելով առանց նվաճման հաղթանակի ուղղակի գանձարանից կառուցված առաջին խոշոր սուլթանական (սելաթին) մզկիթը, դարձավ նաև ժամանակի քննադատությունների առարկա։ Համալիրը մտահղացվել էր այնպես, որ մզկիթի հետ ներառեր նաև մեդրեսե, աղքատների ճաշարան և դամբարան։", "2605235a"]},
"OLAYLAR_EK7:1622-05-20:0":{"b": ["Գենչ Օսմանի սպանությունը ենիչերիների կողմից (Հաիլե-ի Օսմանիե)", "324f6582"], "d": ["Այն լուրերի պատճառով, թե նա ուխտագնացության պատրվակով ցանկանում է Ստամբուլից դուրս գալ և լուծարել ենիչերիների օջախը, ապստամբած ենիչերիներն ու սիփահիները գահընկեց արեցին Օսման II-ին և Եդիքուլեի բանտում խեղդամահ արեցին։ Ըստ TDV İslâm Ansiklopedisi-ի «Օսման II» հոդվածի՝ այս դեպքը օսմանյան պատմության մեջ առաջին դեպքն է, երբ փադիշահը բացահայտ ռազմական ապստամբությամբ սպանվեց, և այն խոր ճեղք առաջացրեց հարստության և զինվորականության հարաբերություններում։ Նրա վերջին ժամերն այսպես անցան. ենիչերիների աղա Ալի աղայի ապարանքում ապաստանելու փորձը արդյունք չտալուց հետո փադիշահին, TDV-ի խոսքով, «սարսափելի կերպով, գլխաբաց, հագուստը քրքրված վիճակում» բեռնաձի վրա նստեցրած, ծանր վիրավորանքների ներքո նախ տարան Օրթա Ջամի, որտեղ Մուստաֆա I-ն էր, իսկ նույն օրվա կեսօրից հետո՝ Եդիքուլե. որոշ պատմաբանների համաձայն՝ նրա մահն ապացուցելու համար կտրեցին ականջն ու քիթը և ցույց տվեցին Մուստաֆա I-ի մորը։ Դեպքից հետո Մուստաֆա I-ը երկրորդ անգամ գահ բարձրացվեց։ «Հաիլե-ի Օսմանիե» (Օսմանի ողբերգությունը) անունով հիշվող դեպքը մշտապես խաթարեց պալատի և օջախի հավասարակշռությունը և սկիզբ դրեց լեգիտիմության շուրջ վեճերին, որոնք տևելու էին ողջ դարը։", "cf706a0a"]},
"OLAYLAR_EK7:1622-05-20:1":{"b": ["Մուստաֆա I-ի երկրորդ անգամ գահ բարձրացվելը", "34a0b29a"], "d": ["Գենչ Օսմանի՝ ենիչերիների կողմից սպանվելուց հետո, քանի որ հարստության մեջ այլ չափահաս արական անդամ չկար, Մուստաֆա I-ը երկրորդ անգամ գահ բարձրացվեց։ Ըստ TDV İslâm Ansiklopedisi-ի «Մուստաֆա I» հոդվածի՝ այս երկրորդ գահակալությունն էլ, ի տարբերություն նախորդի, ոչնչով չտարբերվելով, անցավ առանց պետական գործերը փաստացի վարելու, և պետության կառավարումը մնաց վեզիրների և վալիդե սուլթանի ձեռքում։ Տասնչորս ամիս տևած այս շրջանն ավարտվեց 1623 թ. Մուրադ IV-ի գահակալմամբ։", "0fb39afd"]},
"OLAYLAR_EK7:1633-09-01:0":{"b": ["Ջիբալիի հրդեհը", "3e42fb08"], "d": ["Ջիբալիում բռնկված և քամու ազդեցությամբ արագ տարածված հրդեհը մոխրի վերածեց Ստամբուլի մեծ մասը. ըստ TDV İslâm Ansiklopedisi-ի «Ստամբուլ» հոդվածի՝ ժամանակի աղբյուրները հայտնում են, որ այրվել են հազարավոր տներ։ Այն, որ հրդեհը կապվեց փայտաշեն տների և ծխախոտ ծխելու հետ, դարձավ ծխախոտի և սրճարանների խիստ արգելքի ուղղակի հիմնավորումը, որը Մուրադ IV-ը շուտով հայտարարելու էր։ Աղետը միայն մեկն էր այն կրկնվող մեծ հրդեհներից, որոնք տեղի էին ունենում ժամանակի Ստամբուլում։", "580b710f"]},
"OLAYLAR_EK7:1633-10-01:0":{"b": ["Մուրադ IV-ի ծխախոտի և սրճարանների արգելքը", "5dd71297"], "d": ["Ջիբալիի հրդեհից հետո, հրդեհի և հասարակական կարգի մտահոգությամբ, Մուրադ IV-ը արգելեց ծխախոտ ծխելը և սրճարանները. արգելքը խախտողների նկատմամբ կիրառվեցին ծանր պատիժներ, ներառյալ մահապատիժը։ Ըստ TDV İslâm Ansiklopedisi-ի «Մուրադ IV» հոդվածի՝ փադիշահը ներքին կարգապահության այնպիսի խիստ քաղաքականություն վարեց, որ արգելքը վերահսկելու համար անձամբ ծպտված շրջում էր քաղաքի փողոցներում։ Այս խիստ միջոցառումները գնահատվում են որպես կենտրոնական իշխանությունը վերահաստատելու Մուրադ IV-ի ջանքի մաս։", "cc3ae964"]},
"OLAYLAR_EK7:1637-01-01:0":{"b": ["Ժանտախտի համաճարակ Ստամբուլում", "f33f58c5"], "d": ["Մուրադ IV-ի օրոք Ստամբուլը ցնցվեց ժանտախտի ծանր համաճարակով, որը ազդեց բնակչության զգալի մասի վրա. ներքաղաքային առևտուրը և առօրյա կյանքը ամիսներ շարունակ խաթարվեցին։ TDV İslâm Ansiklopedisi-ի «Ստամբուլ» հոդվածը նշում է, որ 17-րդ դարում կրկնվող համաճարակները լրջորեն ազդեցին քաղաքի բնակչության հավասարակշռության վրա։ Համաճարակի ժամանակ պալատը և ընտրանին որոշ ժամանակով տեղափոխվել էին քաղաքից դուրս գտնվող այգիներ և ամառանոցներ։", "2dc59aee"]},
"OLAYLAR_EK7:1638-06-01:0":{"b": ["Հեզարֆեն Ահմեդ Չելեբիի թևավոր թռիչքը (ավանդազրույց)", "df474c04"], "d": ["Ըստ Էվլիյա Չելեբիի հաղորդած ավանդազրույցի՝ Հեզարֆեն Ահմեդ Չելեբին, իր իսկ պատրաստած թևերով ցատկելով Ղալաթիայի աշտարակից, կարողացել է սավառնել մինչև Ուսկյուդար. թեև դրա պատմական ստույգությունը վիճելի է, այն դարձել է տեխնիկական երևակայության խորհրդանիշ։ Փադիշահը սկզբում պարգևատրեց Հեզարֆենին, սակայն դեպքի առաջացրած արձագանքի պատճառով հետագայում աքսորեց Ալժիր։", "f1671c60"]},
"OLAYLAR_EK7:1642-01-01:0":{"b": ["Ջինջի Հոջա Հուսեյն էֆենդիի ազդեցության ձեռքբերումը պալատում", "41d21572"], "d": ["Փադիշահ Իբրահիմի հոգեկան տառապանքները բուժելու համար պալատ հրավիրված փչոց-կախարդանքով բուժող Հուսեյն էֆենդին կարճ ժամանակում շահեց փադիշահի վստահությունը և բարձրացավ մինչև Անատոլիայի կազասկերության աստիճանին։ Ըստ TDV İslâm Ansiklopedisi-ի «Հուսեյն էֆենդի, Ջինջի Հոջա» հոդվածի՝ նա այդ ազդեցությունն օգտագործեց հարստություն կուտակելու և ժամանակի քաղաքական իրադարձություններին միջամտելու համար։ Իբրահիմի մահից հետո նա զրկվեց բոլոր պաշտոններից և 1648 թ. մահապատժի ենթարկվեց։", "af40c3d4"]},
"OLAYLAR_EK7:1644-01-31:0":{"b": ["Քեմանքեշ Մուստաֆա փաշայի մահապատիժը", "0ecc8030"], "d": ["Մուրադ IV-ի օրոքից մեծ վեզիրի պաշտոնը վարող և իր ֆինանսական բարեփոխումներով գանձարանին զգալի հավելուրդ ապահոված Քեմանքեշ Մուստաֆա փաշան, պալատական մրցակիցների կողմից Իբրահիմի վրա ազդելու և ենիչերիների ապստամբություն հրահրելու մեղադրանքից հետո, խեղդամահ արվելով մահապատժի ենթարկվեց։ Ըստ TDV İslâm Ansiklopedisi-ի «Քեմանքեշ Մուստաֆա փաշա» հոդվածի՝ մահապատիժը կատարվեց 1053 թ. զու-լ-կաադայի 21-ին / 1644 թ. հունվարի 31-ին. Քեմանքեշ Կարա Մուստաֆա փաշան Հոջափաշա շուկայում խեղդամահ արվեց դահիճ Կարա Ալիի ձեռքով և թաղվեց Չարշըքափըի իր դամբարանում։ Նրա մահը հիշատակվում է որպես ժամանակի մեծ վեզիրի պաշտոնի անկայունության ցայտուն օրինակ, և այն վերջ դրեց խիստ բարեփոխումների կարճատև շրջանին։", "9ae1d459"]},
"OLAYLAR_EK7:1645-04-01:0":{"b": ["Կրետեի արշավանքի որոշումը դիվանում և նավատորմի ճանապարհ ելնելը", "9076827e"], "d": ["Դիվան-ի Հումայունում որոշվեց լայնածավալ արշավանք ձեռնարկել Վենետիկին պատկանող Կրետե կղզու դեմ, և կապուդան փաշայի հրամանատարությամբ օսմանյան նավատորմը Ստամբուլից շարժվեց դեպի Կրետե։ Ըստ TDV İslâm Ansiklopedisi-ի «Կրետե» հոդվածի՝ այս որոշումը կազմեց մոտ քսանհինգ տարի տևելիք երկարատև պաշարման և պատերազմի ժամանակաշրջանի քաղաքական սկիզբը։ Արշավանքի սկսումը, լինելով Իբրահիմի օրոքի ամենամեծ արտաքին քաղաքական նախաձեռնությունը, լայն վեճեր էր առաջացրել պետական ավագանու շրջանում։", "da4feb76"]},
"OLAYLAR_EK7:1648-08-08:0":{"b": ["Մեհմեդ IV-ի գահակալումը յոթ տարեկանում", "a197a3bc"], "d": ["Իբրահիմի գահընկեցությունից անմիջապես հետո նրա դեռ յոթամյա որդի Մեհմեդը գահ բարձրացվեց և Մեհմեդ IV անունով դարձավ փադիշահ։ Ըստ TDV İslâm Ansiklopedisi-ի «Մեհմեդ IV» հոդվածի՝ այսքան փոքր տարիքում գահ բարձրանալը սաստկացրեց նրա տատ Քյոսեմ սուլթանի և մայր Թուրհան սուլթանի միջև պալատական ազդեցության պայքարը։ Այս իշխանական պայքարն ավարտվելու էր 1651 թ. Քյոսեմ սուլթանի սպանությամբ։", "aa8955d5"]},
"OLAYLAR_EK7:1652-06-20:0":{"b": ["Թարհունջու Ահմեդ փաշայի հավասարակշռված բյուջեի բարեփոխումը", "376fc7f2"], "d": ["Մեծ վեզիր Թարհունջու Ահմեդ փաշան, երկարատև պատերազմի տարիների առաջացրած ֆինանսական ճգնաժամը հաղթահարելու համար, իրականացնելով պալատական ծախսերն էլ ներառող խիստ տնտեսումների ծրագիր, պատրաստեց օսմանյան պատմության մեջ հայտնի առաջին հավասարակշռված բյուջեն (Թարհունջուի նախագիծ)։ Ըստ TDV İslâm Ansiklopedisi-ի «Թարհունջու Ահմեդ փաշա» հոդվածի՝ այս բարեփոխումը գանձարանին զգալի հավելուրդ ապահովեց, բայց լայն դժգոհություն առաջացրեց պալատական շրջանակներում և բարձր բյուրոկրատիայում։ Այս դժգոհությունն ավարտվելու էր մեկ տարի անց նրա իսկ մահապատժով։", "c837950b"]},
"OLAYLAR_EK7:1656-03-04:0":{"b": ["Չինարի դեպքը (Վաքա-ի Վաքվաքիյե)", "4c6ed90f"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Չինարի դեպք» հոդվածի՝ Կրետեի արշավանքից առանց վճարի վերադարձած ենիչերիներն ու սիփահիները Ստամբուլում ապստամբեցին և պահանջեցին կոռուպցիայի մեջ մեղադրած պետական գործիչների մահապատիժը։ Մեծ վեզիր Զուրնազեն Մուստաֆա փաշայի՝ բռնագրավման և աքսորի առաջարկը չընդունվեց. նախ երեք պաշտոնյա, ապա գրեթե երեսուն պետական գործիչ մահապատժի ենթարկվեցին, և նրանց դիակները կախվեցին Սուլթանահմեդ հրապարակի չինարի ծառերից։ Այդ պատճառով դեպքը հիշվեց «Չինարի դեպք» անունով։", "f187180a"]},
"OLAYLAR_EK7:1656-09-15:0":{"b": ["Քյոփրյուլյու Մեհմեդ փաշայի նշանակումը մեծ վեզիր՝ պայմանների ընդունմամբ", "3a6b7f8f"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Քյոփրյուլյու Մեհմեդ փաշա» հոդվածի՝ ութսունին մոտ Քյոփրյուլյու Մեհմեդ փաշան կնիքը վերցրեց միայն այն բանից հետո, երբ վալիդե Թուրհան սուլթանին և Մեհմեդ IV-ին ներկայացրած իր ծանր պայմանները, այն է՝ չմիջամտել իր նշանակումներին և չհավատալ իր դեմ ասվածներին, ընդունել տվեց։ 1066 թ. զու-լ-կաադայի 26-ին նա պաշտոնի անցավ Բոյնուէղրի Մեհմեդ փաշայի փոխարեն և ձեռնամուխ եղավ պետական կարգապահությունը խիստ կերպով վերահաստատելուն։", "066ec089"]},
"OLAYLAR_EK7:1656-10-01:0":{"b": ["Քադըզադեների շարժման ճնշումը Քյոփրյուլյու Մեհմեդ փաշայի կողմից", "5ec3ce84"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Քադըզադեներ» հոդվածի՝ Քյոփրյուլյու Մեհմեդ փաշան, պաշտոնի անցնելուն պես, զբաղվեց Քադըզադե Մեհմեդ էֆենդիի շրջապատի և սուֆիական միաբանությունների հետևորդների միջև կրոնական հակամարտությամբ։ Ուլեմաների հետ խորհրդակցելուց հետո թեև նա շարժման ղեկավարներ Ուստյուվանի Մեհմեդ էֆենդիի, Թյուրք Ահմեդի և Դիվանե Մուստաֆայի մահապատժի ֆիրման հանեց, այդ պատիժը փոխարինվեց աքսորով, և երեքն էլ ուղարկվեցին Կիպրոս. այսպիսով, ավարտվեց շարժման երկրորդ փուլը։", "a6f49f27"]},
"OLAYLAR_EK7:1660-07-15:0":{"b": ["Մեծ հրդեհ Ստամբուլում. Աղաքափըսիի այրվելը", "b9253b66"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Աղաքափըսի» հոդվածի՝ Մեհմեդ IV-ի օրոք 1660 թ. հուլիսին բռնկված մեծ հրդեհում ենիչերիների աղայի պաշտոնական նստավայր Աղաքափըսին լիովին այրվեց և այնուհետև վերակառուցվեց։ Այս հրդեհը այն մեծ քաղաքային հրդեհներից մեկն էր, որոնք բազմիցս հարվածում էին ժամանակի Ստամբուլին։", "f9ae495b"]},
"OLAYLAR_EK7:1661-11-01:0":{"b": ["Քյոփրյուլյուզադե Ֆազիլ Ահմեդ փաշայի նշանակումը մեծ վեզիր", "c1999b5c"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Քյոփրյուլյուզադե Ֆազիլ Ահմեդ փաշա» հոդվածի՝ իր հոր՝ Քյոփրյուլյու Մեհմեդ փաշայի մահից հետո 1072 թ. ռաբի ալ-ավվալի 8-ին (1661 թ. նոյեմբերի 1) նա նշանակվեց մեծ վեզիր։ Ի տարբերություն իր հոր՝ մեղմաբարո, բարեպաշտ և գիտնականների ու արվեստագետների հովանավոր ճանաչված Ֆազիլ Ահմեդ փաշան իր ավելի քան տասնհինգ տարվա մեծ վեզիրության ընթացքում Ստամբուլում և նվաճված հողերում գրադարաններ և բարեգործական հաստատություններ կառուցել տվեց։", "25ea9a1e"]},
"OLAYLAR_EK7:1665-06-01:0":{"b": ["Վանի Մեհմեդ էֆենդիի նշանակումը Ենիջամիի քարոզիչ և փադիշահի ուսուցիչ", "7ea6aaae"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Մեհմեդ էֆենդի, Վանի» հոդվածի՝ Քյոփրյուլյուզադե Ֆազիլ Ահմեդ փաշայի մեծ վեզիր դառնալով Ստամբուլ հրավիրված և Մեհմեդ IV-ին ներկայացված Վանի Մեհմեդ էֆենդին կարճ ժամանակում շահեց փադիշահի մոտ հետաքրքրությունը։ 1665 թ. նշանակվելով Ենիջամիի քարոզիչ և փադիշահի ուսուցիչ՝ նա դարձավ պալատի ամենաազդեցիկ հոգևորականներից մեկը։", "3b1a8c25"]},
"OLAYLAR_EK7:1676-11-05:0":{"b": ["Մերզիֆոնլու Կարա Մուստաֆա փաշայի նշանակումը մեծ վեզիր", "3d1e836c"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Մերզիֆոնլու Կարա Մուստաֆա փաշա» հոդվածի՝ Ֆազիլ Ահմեդ փաշայի մահից հետո 1087 թ. շաաբանի 28-ին (1676 թ. նոյեմբերի 5) նա նշանակվեց մեծ վեզիր։ Լինելով Քյոփրյուլյուների ընտանիքի փեսան և սանը՝ պետական կառավարման մեջ երկար փորձ ունեցող Մերզիֆոնլուն դարձավ Մեհմեդ IV-ի ամենահզոր և ազդեցիկ մեծ վեզիրներից մեկը։", "364f6283"]},
"OLAYLAR_EK7:1685-10-12:0":{"b": ["Վանի Մեհմեդ էֆենդիի մահը աքսորում", "cda714aa"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Մեհմեդ էֆենդի, Վանի» հոդվածի՝ Վիեննայի արշավանքը փադիշահին ընդունել տված գլխավոր անձանցից մեկը համարվող Վանի Մեհմեդ էֆենդին, արշավանքի պարտությամբ ավարտվելուց հետո, հասարակական ճնշման ներքո զրկվեց բարեհաճությունից և աքսորվեց Բուրսայի Քեսթել ավան։ 1096 թ. զու-լ-կաադայի 14-ին (1685 թ. հոկտեմբերի 12) նա մահացավ այնտեղ և թաղվեց իր կառուցած մզկիթի մուտքի մոտ։", "d8dc341f"]},
"OLAYLAR_EK7:1689-10-25:0":{"b": ["Քյոփրյուլյուզադե Ֆազիլ Մուստաֆա փաշայի նշանակումը մեծ վեզիր և նրա ֆինանսական բարեփոխումները", "b048570e"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Քյոփրյուլյուզադե Ֆազիլ Մուստաֆա փաշա» հոդվածի՝ 1101 թ. մուհառամի 11-ին (1689 թ. հոկտեմբերի 25) մեծ վեզիր նշանակված Ֆազիլ Մուստաֆա փաշան ջիզյայի գանձման կարգը վերակազմեց շարիաթական հիմունքներով, պայքարեց մանղըրի (պղնձե մետաղադրամի) գնաճի դեմ և, պալատական հաստատություններից միջոցներ փոխանցելով, ամրապնդեց գանձարանը։ Նաև գավառական կառավարումը ամրապնդեց վստահելի պաշտոնյաներով և կենտրոնական դիվանի նմանվող տեղական խորհուրդներ հիմնել տվեց։", "57c6c63d"]},
"OLAYLAR_EK7:1695-01-01:0":{"b": ["Մալիքյանե համակարգի կիրարկումը", "316b8426"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Մալիքյանե» հոդվածի՝ 17-րդ դարի վերջին քառորդում պատերազմական ծախսերի աճը և հողային կորուստների պատճառով եկամուտների նվազումը գանձարանը ծանր ֆինանսական ճգնաժամի մեջ գցեցին։ 1106 (1695) թ. ուժի մեջ մտած մալիքյանե համակարգում կապալառուներին (մյուլթեզիմներ) ցմահ հաստատուն հարկային իրավունք շնորհվեց, ինչով կարճաժամկետ շահագործման փոխարեն խթան ստեղծվեց արտադրությունը պահպանելու համար։", "f564e96c"]},
"OLAYLAR_EK7:1695-02-06:0":{"b": ["Մուստաֆա II-ի գահակալումը", "b53656c7"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Մուստաֆա II» հոդվածի՝ երեսունմեկ տարեկանում գահ բարձրացած Մուստաֆա II-ը իր գահակալությունը հռչակեց՝ չսպասելով մեծ վեզիրի և շեյխ ալ-իսլամի հաստատմանը. սուր կապելու արարողությունը մի քանի օր անց կատարվեց Էսքի Ջամիում։ Վիեննայի պարտությունից հետո բազմաճակատ պատերազմների շարունակվող ժամանակաշրջանում գահ բարձրացած փադիշահը դարձավ օսմանյան պատմության մեջ անձամբ արշավանքի դուրս եկած վերջին սուլթանը։", "6cd0fed9"]},
"OLAYLAR_EK7:1695-05-25:0":{"b": ["Ֆեյզուլլահ էֆենդիի երկրորդ անգամ նշանակումը շեյխ ալ-իսլամ", "1cf14cff"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Ֆեյզուլլահ էֆենդի, Սեյիդ» հոդվածի՝ Մուստաֆա II-ի գահակալումից հետո 1106 թ. շավվալի 11-ին (1695 թ. մայիսի 25) նա երկրորդ անգամ նշանակվեց շեյխ ալ-իսլամ։ Փադիշահի վրա նրա ազդեցությունը ավելի քան ութ տարի տևած այս պաշտոնավարման ընթացքում գնալով աճեց։", "a2d4ab3e"]},
"OLAYLAR_EK7:1703-03-01:0":{"b": ["Ֆեյզուլլահ էֆենդիի կողմից իր որդիներին բարձր պաշտոնների բերելը և կուտակվող դժգոհությունը", "a6398280"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Ֆեյզուլլահ էֆենդի, Սեյիդ» հոդվածի՝ շեյխ ալ-իսլամը Մուստաֆա II-ից ստացավ աննախադեպ ֆիրման այն մասին, որ իր որդի Ֆեթհուլլահ էֆենդին իրենից հետո դառնալու է շեյխ ալ-իսլամ, և իր ազգականներին երիտասարդ տարիքում բարձր պաշտոնների նշանակեց։ Այս գործելակերպերը լայն դժգոհություն առաջացրին ուլեմական դասի, զինվորականության և Ստամբուլի ժողովրդի շրջանում. միախառնվելով մայրաքաղաքը Ադրիանապոլիս (Էդիրնե) տեղափոխելու մասին լուրերին՝ դրանք նախապատրաստեցին 1703 թ. Ադրիանապոլսի դեպքի հողը։", "34c068d3"]},
"OLAYLAR_EK7:1703-07-17:0":{"b": ["Ադրիանապոլսի (Էդիրնեի) դեպքի սկիզբը", "5a106458"], "d": ["Ըստ TDV-ի «Ադրիանապոլսի (Էդիրնե) դեպք» հոդվածի՝ իրենց ռոճիկները չստացած զինվորների ապստամբությամբ սկսված շարժումը կարճ ժամանակում վերածվեց լայն խռովության, որին մասնակցեցին ենիչերիները, մեդրեսեի ուսանողները, արհեստավորները և ժողովուրդը։ Ապստամբության բուն թիրախը շեյխ ալ-իսլամ Ֆեյզուլլահ էֆենդին էր, որին մեղադրում էին պետական գործերին չափազանց միջամտելու մեջ։ Մոտ 60.000-անոց ամբոխը Ստամբուլից քայլերթով շարժվեց դեպի Ադրիանապոլիս։", "201120ba"]},
"OLAYLAR_EK7:1718-05-09:0":{"b": ["Նևշեհիրլի Դամադ Իբրահիմ փաշայի մեծ վեզիրությունը", "8d627a6f"], "d": ["Ըստ TDV-ի «Դամադ Իբրահիմ փաշա, Նևշեհիրլի» հոդվածի՝ Ավստրիայի հետ ընթացող խաղաղ բանակցությունների ժամանակ, 1130 թ. ջումադա աս-սանիյայի 8-ին (1718 թ. մայիսի 9) նա նշանակվեց մեծ վեզիր և նշանակվելուն պես ուշադրությունն ուղղեց պատերազմն ավարտող բանակցություններին. երկու ամիս անց ստորագրվեց Պասարովիցի պայմանագիրը (1718 թ. հուլիսի 21)։ TDV-ի խոսքով՝ «նա ցանկանում էր զբաղվել հասարակական և ֆինանսական հարցերով և տենչում էր խաղաղության մի ժամանակաշրջան, որը կմոռացնել տար երկար տարիներ պարտությամբ ավարտվող պատերազմները»։ Ֆինանսներում բարեփոխումներ անելով՝ նա նվազեցրեց զինվորների աշխատավարձերը և պետական գանձարանում զգալի հավելուրդ գոյացրեց։ Տասներկու տարի տևելիք նրա մեծ վեզիրությունը կազմեց նրա անունը կրող ժամանակաշրջանի (Կակաչների դարաշրջան) քաղաքական շրջանակը։", "5874203b"]},
"OLAYLAR_EK7:1720-06-01:0":{"b": ["Թուլումբաջիների (հրշեջների) օջախի հիմնումը", "f58b0d97"], "d": ["Ըստ TDV-ի «Թուլումբաջի» հոդվածի՝ 1715 թ. Մորեայի արշավանքից վերադարձած Գերչեք Դավուդի՝ Ստամբուլի հրդեհների ժամանակ պոմպով ցուցաբերած հաջողության հիման վրա մեծ վեզիր Նևշեհիրլի Դամադ Իբրահիմ փաշան նրան հանձնարարեց հիմնել պաշտոնական հրշեջ օջախ։ Աջեմի օղլանների զորանոցում վեց սպայով և հիսուն զինվորով հիմնված օջախը 1724 թ. հասավ 150, իսկ 1755 թ.՝ 461 հոգու։ Դավուդը մինչև իր մահը՝ 1733 թ., մնաց օջախի գլուխ։", "3b860f0f"]},
"OLAYLAR_EK7:1722-06-01:0":{"b": ["Սադաբադ ամառային պալատի կառուցումը", "aec9c65e"], "d": ["Ըստ TDV-ի «Սադաբադ» հոդվածի՝ Քյաղըթհանե գետակի ափին կառուցվեց ֆրանսիական պալատական ճարտարապետությունից ներշնչված ամառային պալատից, ջրանցքից, աղբյուրներից և ամառանոցներից բաղկացած ընդարձակ զվարճանքի և զբոսավայրի համալիր։ Ժամանակի ամենասիրելի զվարճանքի վայրը դարձած Սադաբադը անմահացավ բանաստեղծ Նեդիմի բանաստեղծություններում։ Համալիրը 1730 թ. Պատրոնա Հալիլի ապստամբության ժամանակ մեծապես ավերվեց։", "2698478e"]},
"OLAYLAR_EK7:1722-09-03:0":{"b": ["Ռուսական ուժերի կողմից Դերբենդի գրավումը. Պետրոս I-ի կասպիական արշավանքը", "c2b269f9"], "d": ["Երբ Սեֆյան պետությունը աֆղանական ներխուժումով ներքաշվել էր ներքին խառնակությունների մեջ, ռուսական ցար Պետրոս I-ը արշավանքի ելավ՝ Կասպից ծովի ափի իրանական հողերը զավթելու նպատակով. ափամերձ Դերբենդ քաղաքը, զգալի դիմադրություն ցույց չտալով, հանձնվեց ռուսական ուժերին։ Ըստ TDV İslâm Ansiklopedisi-ի «Դերբենդ» հոդվածի՝ այս օկուպացիան տասներեք տարի տևելիք ժամանակավոր ռուսական տիրապետության սկիզբն էր. Օսմանյան պետությունը, օգտվելով նույն խառնակությունից, նույնպես ուղղվեց դեպի Կովկասի արևմտյան հատված։ Բանակը Աստրախանից ծովով դուրս էր եկել Ագրախանի ծովածոց և այնտեղից ափի երկայնքով Տարկուի վրայով քայլել ցամաքով. Տարկուի շամխալը հյուրընկալել էր Պետրոսին և անցել ռուսական հպատակության տակ։", "4220bd4e"]},
"OLAYLAR_EK7:1726-01-01:0":{"b": ["Տարկուի շամխալության վերացումը. ռուսական ուղղակի կառավարում", "b0f029c6"], "d": ["1722 թ. Պետրոսին հյուրընկալած և ռուսական հպատակության տակ անցած Տարկուի շամխալ Ադիլ-Գիրեյը 1725 թ. ապստամբեց. Յերոպկինը 1725 թ. աշնանը քանդեց Տարկուն, շամխալը 1726 թ. մայիսի կեսին ձերբակալվեց և աքսորվեց, և շամխալությունը վերացվեց։ Տարկուն և շրջակայքը մինչև 1735 թ. Գանձակի պայմանագիրը մնացին ռուսական ուղղակի կառավարման տակ։", "32bb2cc9"]},
"OLAYLAR_EK7:1727-07-01:0":{"b": ["Իբրահիմ Մյութեֆերիքային տպարան հիմնելու թույլտվություն", "0659dd0a"], "d": ["Ըստ TDV-ի «Իբրահիմ Մյութեֆերիքա» հոդվածի՝ Ահմեդ III-ի ֆիրմանով և շեյխ ալ-իսլամ Ենիշեհիրլի Աբդուլլահ էֆենդիի ֆեթվայով թույլատրվեց հիմնել առաջին թուրքական տպարանը։ Տպարանը գործունեություն սկսեց Ստամբուլի Յավուզսելիմ թաղամասում։ Մյութեֆերիքան մինչև իր մահը՝ 1747 թ., տպագրեց քսաներեք հատորից բաղկացած տասնյոթ աշխատություն։", "2b37f2a0"]},
"OLAYLAR_EK7:1729-02-01:0":{"b": ["Առաջին տպագիր գրքի՝ «Վանկուլու Լուղաթի» ավարտը", "684700e8"], "d": ["Ըստ TDV-ի «Իբրահիմ Մյութեֆերիքա» հոդվածի՝ տպարանի առաջին գործը՝ «Սըհահ ուլ-Ջեուհերիի» թուրքերեն թարգմանությունը («Վանկուլու Լուղաթի») ավարտվեց 1729 թ. սկզբին։ Սա օսմանյան հողերում արաբատառ տպագրված առաջին գիրքն էր և համարվում է թուրքական տպագրության պատմության սկիզբը։", "d204cfc9"]},
"OLAYLAR_EK7:1730-10-01:0":{"b": ["Նևշեհիրլի Դամադ Իբրահիմ փաշայի մահապատիժը", "50c64341"], "d": ["Ըստ TDV-ի «Դամադ Իբրահիմ փաշա, Նևշեհիրլի» հոդվածի՝ Պատրոնա Հալիլի ապստամբության ժամանակ պալատում սպանված մեծ վեզիրի դիակը քարշ տվեցին Ստամբուլի փողոցներով և թողեցին Սուլթանահմեդ հրապարակի Ահմեդ III-ի շատրվանի մոտ։ Այսպիսով, նրա տասներկուամյա մեծ վեզիրությունը և Կակաչների դարաշրջանը արյունալի վախճան ունեցան։", "3af021b4"]},
"OLAYLAR_EK7:1730-10-02:0":{"b": ["Ահմեդ III-ի հրաժարումը գահից, Մահմուդ I-ի գահակալումը", "a43f5d40"], "d": ["Ըստ TDV-ի «Մահմուդ I» հոդվածի՝ ապստամբների ճնշման տակ Ահմեդ III-ը, իր և իր զավակների համար երաշխիքներ ստանալով, հրաժարվեց գահից և իր եղբորորդի շեհզադե Մահմուդին անձամբ գահ բարձրացրեց։ Հորեղբոր «պետական գործերը վերցրու քո ձեռքը, ոչ ոքի մի՛ վստահիր» խորհրդով գահ նստած Մահմուդ I-ը իր առաջին գործը դարձրեց իրեն գահ բարձրացրած ապստամբ խմբի ազդեցության կոտրումը։", "32260f8c"]},
"OLAYLAR_EK7:1733-06-01:0":{"b": ["Հումբարաջի Ահմեդ փաշայի կողմից հրետանային օջախի բարեփոխումը", "ea3a7c64"], "d": ["Ըստ TDV-ի «Հումբարաջի» հոդվածի՝ իսլամ ընդունած ֆրանսիական ծագմամբ սպա Ահմեդ փաշան մեծ վեզիր Հեքիմօղլու Ալի փաշայի օրոք ձեռնամուխ եղավ ռոճիկով ծառայող ռմբաձիգների (հումբարաջի) կազմակերպության եվրոպական ոճով բարեփոխմանը։ Նա ստեղծեց անմիջապես մեծ վեզիրին ենթակա 601 հոգանոց նոր կառույց՝ 300 ռոճիկավոր և 301 թիմարատեր։ Ժամանակի տեխնոլոգիայով արտադրել տվեց 100 ականանետ (հավան) և 50.000 գնդակ։", "bf4e60c1"]},
"OLAYLAR_EK7:1734-06-01:0":{"b": ["Հենդեսեհանեի (ճարտարագիտական դպրոցի առաջին օրինակի) հիմնումը", "a77ed1f3"], "d": ["Ըստ TDV-ի «Մահմուդ I» հոդվածի՝ Հումբարաջի Ահմեդ փաշան Ուսկյուդարում հիմնեց Հումբարահանե էլ կոչվող Հենդեսեհանեն և պալատական ծառայողների ու բոստանջիների միջից ընտրած ուսանողներին տվեց մաթեմատիկայի և երկրաչափության վրա հիմնված ռազմական կրթություն։ Այս հաստատությունը համարվում է հետագայում զարգանալիք ճարտարագիտական դպրոցների առաջին օրինակը։", "84b5af85"]},
"OLAYLAR_EK7:1735-03-21:0":{"b": ["Գանձակի պայմանագիրը. Դերբենդն ու Բաքուն վերադարձվեցին Իրանին", "ff19d531"], "d": ["Օսմանյան սպառնալիքի դեմ Իրանի հետ դաշինք փնտրող Ռուսաստանը Գանձակի պայմանագրով տասներեք տարի իր ձեռքում պահած կասպիական ափի քաղաքները վերադարձրեց Նադիր խանի (դեռ շահի տիտղոս չստացած) հրամանատարությամբ Իրանին։ Ըստ TDV İslâm Ansiklopedisi-ի «Դերբենդ» հոդվածի՝ այս նահանջը արդյունքն էր այն բանի, որ Ռուսաստանը չէր ցանկանում հարավում միաժամանակ երկու ճակատով (Օսմանյան պետության և Իրանի դեմ) պայքարել, և այն ամրապնդեց Նադիրի ռազմական հեղինակությունը, որը մի քանի տարի անց նրա առջև բացեց գահի ճանապարհը։ Ռուսական կառավարման տակ գտնվող Տարկին (Տարկու) նույնպես այս նահանջով վերադարձավ իրանական կողմ (քարտեզում օգտագործվում է Գանձակի օրը)։ Ռուսական կառավարման տակ գտնվող Սալյանը և Շաբրանը նույնպես այս նահանջով վերադառնում են իրանական կողմ (բնակավայրերին հատուկ օրը աղբյուրում նշված չէ, քարտեզում օգտագործվում է Գանձակի օրը. հայտարարված մոտավորություն)։", "711f14d9"]},
"OLAYLAR_EK7:1736-03-08:0":{"b": ["Նադիր շահի գահակալումը Մուղանի դաշտում. Սեֆյան հարստության փաստացի վախճանը", "4f640979"], "d": ["Ըստ TDV İslâm Ansiklopedisi-ի «Նադիր շահ» հոդվածի՝ Մուղանի դաշտում հավաքված մոտ քսան հազարանոց կուրուլթայը համառորեն պահանջեց, որ նա անցնի Իրանի գլուխ. Նադիրը ընդունեց այս առաջարկը այն պայմանով, որ թողնվի Սեֆյանների և օսմանցիների միջև պատերազմների պատճառ դարձած ծայրահեղ շիական ըմբռնումը և ընդունվի չափավոր ջաաֆարիական դավանանքը, և 1148 թ. շավվալի 24-ին (1736 թ. մարտի 8) Նադիր շահ տիտղոսով գահ բարձրացավ։ Սա նշանակում էր, որ երկու դարի Սեֆյան հարստությունը փաստացի ավարտվեց, և հիմնվեց Աֆշարյան հարստությունը։", "7f742f06"]},
"OLAYLAR_EK7:1739-06-01:0":{"b": ["Ժանտախտի համաճարակի սկիզբը Ստամբուլում", "9fa82b56"], "d": ["Ըստ TDV-ի «Ժանտախտ» (Tâun) հոդվածի՝ իսլամական աշխարհում 1739-1743 թթ. գործած ժանտախտի համաճարակն այդ ժամանակ հարվածեց նաև Ստամբուլին։ Հոդվածը նշում է, որ 18-րդ դարի համաճարակները նախորդ դարերի համեմատ ընթանում էին համեմատաբար ավելի մեղմ։ Համաճարակի ժամանակաշրջանների թվում են նաև 1713, 1719, 1728-1729 և 1759-1765 թթ.։", "d650b99e"]},
"OLAYLAR_EK7:1755-09-29:0":{"b": ["Հոջափաշայի հրդեհը", "321c7d0d"], "d": ["Ըստ TDV-ի «Ֆաթմա սուլթան մզկիթ» հոդվածի՝ գիշերը բռնկված Հոջափաշայի հրդեհը ավերեց Բաբը Ալին (Բարձր Դուռը) և շրջակայքը. ենթադրվում է, որ այդ հրդեհից վնասվել է նաև շրջանի Ֆաթմա սուլթանի մզկիթը։ Օսման III-ի օրոք Ստամբուլին հարվածած մեծ հրդեհներից մեկը հանդիսացող այս աղետը ծանր ավերածությունների հանգեցրեց քաղաքի առևտրի և կառավարման կենտրոնում։", "3554d781"]},
"OLAYLAR_EK7:1757-02-28:0":{"b": ["Քոջա Ռաղըբ Մեհմեդ փաշայի մեծ վեզիրությունը", "a1846910"], "d": ["Բանաստեղծի և դիվանագետի իր նկարագրով հայտնի Ռաղըբ փաշան Օսման III-ի կողմից նշանակվեց մեծ վեզիր (1757 թ. հոկտեմբերին Օսման III-ի մահից հետո նա շարունակեց պաշտոնավարել և Մուստաֆա III-ից ստացավ նոր կնիք)։ Յոթնամյա պատերազմի շարունակվելու ժամանակ նա վարեց հավասարակշռված արտաքին քաղաքականություն, որը Օսմանյան պետությունը հեռու պահեց Եվրոպայի բախումներից։ Վեց տարի տևելիք իր մեծ վեզիրության ընթացքում նա կարևորեց նաև մշակութային գործունեությունը, ինչպիսին էր գրադարանի հիմնումը։", "d3682725"]},
"OLAYLAR_EK7:1763-04-08:0":{"b": ["Ռաղըբ փաշայի մահը", "6bc19323"], "d": ["Ռաղըբ փաշան մահացավ վեցամյա մեծ վեզիրությունից հետո։ Նրա մահով ավարտվեց Մուստաֆա III-ի ժամանակաշրջանի ամենաերկարատև և հավասարակշռված մեծ վեզիրությունը։", "7da43eab"]},
"OLAYLAR_EK7:1766-05-01:0":{"b": ["Ստամբուլի մեծ երկրաշարժը և Ֆաթիհ մզկիթի փլուզումը", "2475b4dc"], "d": ["Ըստ TDV-ի «Ֆաթիհ մզկիթ և համալիր» հոդվածի՝ 1766 թ. մեծ երկրաշարժի ժամանակ մզկիթի գլխավոր գմբեթը լիովին փլվեց, իսկ պատերը վնասվեցին այնպես, որ հնարավոր չէր վերանորոգել։ Մուստաֆա III-ի հրամանով ճարտարապետներ Սարըմ Իբրահիմ էֆենդիի և Իզզեթ Մեհմեդ բեյի ղեկավարությամբ 1767 թ. սկսված վերակառուցումը, հին հատակագծից տարբերվող նոր ձևավորմամբ, ավարտվեց 1771 թ.։", "680af5a8"]},
"OLAYLAR_EK7:1772-10-01:0":{"b": ["Բարոն դը Տոտի նախաձեռնած կարճակյաց հրետանային դպրոցի փորձը", "4192260c"], "d": ["Ըստ TDV-ի «Մյուհենդիսհանե-ի Բահրի-ի Հումայուն» հոդվածի՝ 1768 թ. ռուս-թուրքական պատերազմի անհաջողությունները ի ցույց դրեցին տեխնիկական ռազմական կրթության անհրաժեշտությունը. ֆրանսիացի սպա Բարոն դը Տոտի աջակցությամբ բացված կարճակյաց հրետանային դպրոցը 1772 թ. հոկտեմբերին սկսեց գործել, բայց մնաց անարդյունք։ Այս փորձը համարվում է 1775 թ. հիմնվելիք Մյուհենդիսհանե-ի Բահրի-ի Հումայունի (Կայսերական ծովային ճարտարագիտական դպրոց) նախակարապետը։", "1b031ce8"]},
"OLAYLAR_EK7:1789-04-07:0":{"b": ["Գահ բարձրացավ Սելիմ III-ը", "00d046d9"], "d": ["Աբդուլհամիդ I-ի մահից հետո գահ բարձրացավ նրա եղբորորդի Սելիմ III-ը։ Ըստ TDV İslâm Ansiklopedisi-ի «Սելիմ III» հոդվածի՝ դեռ շեհզադե եղած ժամանակից եվրոպական բանակների բարեփոխմամբ հետաքրքրված նոր փադիշահը գահակալումից կարճ ժամանակ անց սկսեց պատրաստել տալ արմատական նորացման ծրագիր։ Այս ծրագիրը մի քանի տարի անց կոչվելու էր «Նիզամ-ը Ջեդիդ» (Նոր կարգ)։", "ec094618"]},
"OLAYLAR_EK7:1792-06-01:0":{"b": ["Սկսվեց Նիզամ-ը Ջեդիդի բարեփոխումների ծրագրի պատրաստումը", "eff78a68"], "d": ["Սելիմ III-ը պետական ավագանուց և օտար մասնագետներից պահանջած զեկուցագրերի հիման վրա պատրաստել տվեց նորացման համապարփակ ծրագիր։ Ըստ TDV İslâm Ansiklopedisi-ի «Նիզամ-ը Ջեդիդ» հոդվածի՝ այս ծրագիրը չսահմանափակվեց միայն նոր բանակ ստեղծելով, այլ վերածվեց ֆինանսները, գավառական կառավարումը և դիվանագիտությունն էլ ներառող լայն բարեփոխական շարժման։ Հաջորդ տասնհինգ տարիների ընթացքում ծրագիրն ունենալու էր թե՛ կողմնակիցներ, թե՛ հակառակորդներ։", "7efcd62f"]},
"OLAYLAR_EK7:1793-03-01:0":{"b": ["Եվրոպական մայրաքաղաքներում հիմնվեցին մշտական դեսպանություններ", "2e9dc8a1"], "d": ["Սելիմ III-ը Օսմանյան պետության պատմության մեջ առաջին անգամ մեծ եվրոպական կենտրոններ ուղարկեց մշտական ծառայություն իրականացնող մշտական դեսպաններ։ Ըստ TDV İslâm Ansiklopedisi-ի «Դեսպան» հոդվածի՝ այս քայլով մինչ այդ միայն ժամանակավոր և միանվագ պատվիրակություններով վարվող օսմանյան դիվանագիտությունը ձեռք բերեց մշտական կազմակերպություն։ Նոր դեսպանությունների գլխավոր խնդիրը Եվրոպայի քաղաքական և ռազմական զարգացումները Ստամբուլին կանոնավոր կերպով հաղորդելն էր։", "8fef612b"]},
"OLAYLAR_EK7:1793-06-01:0":{"b": ["Հիմնվեց Իրադ-ը Ջեդիդի գանձարանը", "ae5c8ce2"], "d": ["Նիզամ-ը Ջեդիդ բանակի և բարեփոխումների ծրագրի ծախսերը հոգալու համար հիմնվեց առանձին գանձարան։ Ըստ TDV İslâm Ansiklopedisi-ի «Էսհամ» հոդվածի՝ նոր գանձարանի եկամուտների թվում էին որոշ մուքաթաաների (պետական եկամտաղբյուրների) անմիջական շահագործումը պետության ձեռքով և էսհամի (պետական արժեթղթերի) վաճառքը վերահսկողության տակ առնելը։ Այս կարգավորումը ավանդական ֆինանսական համակարգից դուրս նոր աղբյուր ստեղծելու փորձ էր։", "ddacec62"]},
"OLAYLAR_EK7:1807-05-25:0":{"b": ["Սկսվեց Կաբաքչը Մուստաֆայի ապստամբությունը", "b98eee17"], "d": ["Նիզամ-ը Ջեդիդի դեմ կուտակված դժգոհությունը բռնկվեց, երբ յամաք զինվորները ապստամբեցին Կաբաքչը Մուստաֆայի առաջնորդությամբ։ Ըստ TDV İslâm Ansiklopedisi-ի «Կաբաքչիի ապստամբություն» հոդվածի՝ ապստամբները կարճ ժամանակում Ստամբուլում վերահսկողությունը զավթեցին և պահանջեցին Նիզամ-ը Ջեդիդի կողմնակից պետական գործիչների գլուխները։ Ապստամբությունը մի քանի օրում ավարտվեց Սելիմ III-ի գահընկեցությամբ։", "820bdd75"]},
"OLAYLAR_EK7:1807-05-29:0":{"b": ["Սելիմ III-ը գահընկեց արվեց", "ff2c30ec"], "d": ["Կաբաքչը Մուստաֆայի ապստամբության ճնշման տակ շեյխ ալ-իսլամից ստացված ֆեթվայով Սելիմ III-ը գահընկեց արվեց։ Ըստ TDV İslâm Ansiklopedisi-ի «Սելիմ III» հոդվածի՝ այս որոշումը այն պահն էր, երբ տասնութ տարի տևած բարեփոխումների ժամանակաշրջանը փաստացի ավարտվեց. Նիզամ-ը Ջեդիդ բանակը նույնպես կարճ ժամանակում լուծարվեց։ Սելիմին սկսեցին Թոփքափը պալատում հսկողության տակ պահել։", "d4f1293b"]},
"OLAYLAR_EK7:1807-05-29:1":{"b": ["Գահ բարձրացավ Մուստաֆա IV-ը", "8f1ac86c"], "d": ["Սելիմ III-ի գահընկեցությունից անմիջապես հետո նրա եղբորորդի Մուստաֆա IV-ը հռչակվեց փադիշահ։ Ըստ TDV İslâm Ansiklopedisi-ի «Մուստաֆա IV» հոդվածի՝ նոր փադիշահը իր գահակալությունը սկսեց ապստամբությանն աջակցած Նիզամ-ը Ջեդիդի հակառակորդ շրջանակների ազդեցության ներքո։ Այս կարճատև ժամանակաշրջանը կենտրոնական իշխանության խիստ թուլացած անկայունության փուլ էր։", "58865f17"]},
"OLAYLAR_EK7:1808-07-19:0":{"b": ["Ալեմդար Մուստաֆա փաշան իր բանակով մտավ Ստամբուլ", "0cad3dea"], "d": ["Ռուսչուկի այան Ալեմդար Մուստաֆա փաշան, նպատակ ունենալով Սելիմ III-ին կրկին գահ բարձրացնել, իր բանակով հասավ Ստամբուլի մատույցները։ Ըստ TDV İslâm Ansiklopedisi-ի «Ալեմդար Մուստաֆա փաշա» հոդվածի՝ նրա մուտքը քաղաք դիմավորեց անձամբ Մուստաֆա IV-ը. սակայն մի քանի օրում պալատական ուժերի հավասարակշռությունը լիովին փոխվելու էր։ Այս մուտքը սկիզբ դրեց իրադարձությունների շղթային, որն ավարտվեց թե՛ Սելիմի մահով, թե՛ նոր գահակալությամբ։", "c042d316"]},
"OLAYLAR_EK7:1808-07-28:0":{"b": ["Սպանվեց Սելիմ III-ը", "e452f5f6"], "d": ["Այն օրը, երբ Ալեմդար Մուստաֆա փաշան գրավեց Բաբը Ալին (Բարձր Դուռը), Մուստաֆա IV-ի հրամանով Սելիմ III-ը պալատում սպանվեց։ Ըստ TDV İslâm Ansiklopedisi-ի «Սելիմ III» հոդվածի՝ սա որոշում էր, որն ընդունվել էր գահընկեց արված փադիշահին կրկին գահ բարձրացնելու փորձը կանխելու նպատակով։ Սելիմի մահը նույն օրը հանգեցրեց Մահմուդի գահակալմանը։", "7d63123d"]},
"OLAYLAR_EK7:1808-07-28:1":{"b": ["Գահ բարձրացավ Մահմուդ II-ը", "661c1974"], "d": ["Սելիմ III-ի սպանությունից հետո հարստության միակ արական անդամը մնացած Մահմուդը Ալեմդար Մուստաֆա փաշայի աջակցությամբ գահ բարձրացավ։ Ըստ TDV İslâm Ansiklopedisi-ի «Մահմուդ II» հոդվածի՝ նոր փադիշահը իր գահակալության առաջին ամիսներն անցկացրեց իրեն գահ բարձրացրած Ալեմդարի խնամակալության ներքո և այանների ու կենտրոնի միջև հավասարակշռությունը վերահաստատելու ջանքերով։ Այս շրջանը դարձավ հաջորդ քսան տարվա արմատական բարեփոխումների գործընթացի սկիզբը։", "491f1eb0"]},
"OLAYLAR_EK7:1808-08-15:0":{"b": ["Ստեղծվեց Սեկբան-ը Ջեդիդ բանակը", "6f9eb5e4"], "d": ["Ալեմդար Մուստաֆա փաշան լուծարված Նիզամ-ը Ջեդիդի փոխարեն ստեղծել տվեց եվրոպական ձևով զինված նոր բանակ։ Ըստ TDV İslâm Ansiklopedisi-ի «Սեկբան-ը Ջեդիդ» հոդվածի՝ երեք գնդից բաղկացած այս ուժը ենիչերիների աչքում ընկալվեց որպես ուղղակի սպառնալիք և ստեղծումից ընդամենը մի քանի ամիս անց վերացվեց ենիչերիների ապստամբության ժամանակ։", "ba52d1dd"]},
"OLAYLAR_EK7:1809-12-02:0":{"b": ["Բրաիլայի անկումը. առաջին մեծ ճեղքը Դանուբի գծում", "ee519321"], "d": ["1806 թ. սկսված ռուսական պատերազմում Դանուբի հյուսիսային ափին գտնվող Բրաիլայի (İbrâil) բերդը պաշարեցին և ռմբակոծեցին կոմս Կամենսկու հրամանատարությամբ ռուսական ուժերը։ Ներսում կային 4100 հետևակ, 1100 հեծյալ և 260 թնդանոթ. բերդը պարենի պակասի պատճառով հանձնվեց գեներալ Էսենին։ Այսպիսով, բացվեց Դանուբի պաշտպանական գծի հյուսիսային ծայրը։", "12ec2aef"]},
"OLAYLAR_EK7:1810-09-26:0":{"b": ["Ռուսչուկի հանձնումը. կորսվում է նաև Դանուբի հարավային ափը", "084062e8"], "d": ["Ռուսչուկը դիմադրեց կոմս Կամենսկու հրամանատարությամբ ռուսական բանակի երկարատև և արյունալի պաշարմանը. այն հանձնվեց այն պայմանով, որ կայազորը և խաղաղ բնակչությունը անվտանգ լքեն քաղաքը։ Դանուբի հարավային ափի ամենահզոր բերդաքաղաքի անկումը պատերազմի ընթացքը շրջեց հօգուտ Ռուսաստանի։", "00685e1d"]},
"OLAYLAR_EK7:1826-05-15:0":{"b": ["Հիմնվեց Էշքինջի օջախը", "67c56759"], "d": ["Մահմուդ II-ը ենիչերիների օջախի միջից ընտրված զինվորներով ստեղծել տվեց եվրոպական ձևով վարժանք անցնող նոր զորամաս։ Ըստ TDV İslâm Ansiklopedisi-ի «Էշքինջի օջախ» հոդվածի՝ զորամասը վարժանքները սկսեց 1826 թ. հունիսի 12-ին, սակայն ենիչերիները դա դիտեցին որպես իրենց օջախի վախճան։ Երեք օր անց բռնկված ապստամբությունը վերջ դրեց նաև Էշքինջի օջախի կարճ կյանքին։", "ab923dc4"]},
"OLAYLAR_EK7:1826-06-18:0":{"b": ["Ստեղծվեց Ասաքիր-ի Մանսուրե-ի Մուհամմեդիյե բանակը", "14b84a7e"], "d": ["Ենիչերիների օջախը վերացնելուց անմիջապես հետո Մահմուդ II-ը դրա փոխարեն ստեղծել տվեց կանոնավոր և եվրոպական ձևով վարժված նոր բանակ։ Ըստ TDV İslâm Ansiklopedisi-ի «Ասաքիր-ի Մանսուրե-ի Մուհամմեդիյե» հոդվածի՝ այս բանակը իր աստիճանների կարգով, ուսուցման ծրագրով և աշխատավարձի համակարգով, ի տարբերություն նախորդ փորձերի, դարձավ մշտական հաստատություն։ Հետագա տարիներին բանակը վերածվելու էր Թանզիմաթի ժամանակաշրջանի Նիզամիե բանակի։", "2e0ee6f7"]},
"OLAYLAR_EK7:1826-06-19:0":{"b": ["Փակվեց բեքթաշի միաբանությունը", "f7d9a367"], "d": ["Ենիչերիների օջախի վերացման հետ միաժամանակ արգելվեց նաև բեքթաշի միաբանությունը, որի կրոնական կապերը օջախի հետ հայտնի էին։ Ըստ TDV İslâm Ansiklopedisi-ի «Բեքթաշիություն» հոդվածի՝ որոշ փոքր թեքքեների շեյխերը մահապատժի ենթարկվեցին, իսկ Հաջի Բեքթաշի կացարանի (դերգյահ) շեյխը աքսորվեց Ամասիա, և թեքքեները փոխանցվեցին նակշբանդիական կառավարմանը։ Չնայած այս ծանր հարվածին՝ միաբանությունը շարունակեց գաղտնի կազմակերպվել։", "305773c2"]},
"OLAYLAR_EK7:1827-04-29:0":{"b": ["Հովհարի միջադեպը. օկուպացիայի պատրվակը", "e949001e"], "d": ["Ալժիրին ունեցած ֆրանսիական հին հացահատիկի պարտքի չվճարման պատճառով լարված հանդիպման ժամանակ դեյ Հուսեյնը իր ձեռքի հովհարով հարվածեց ֆրանսիական հյուպատոս Դևալին։ Պարտքի վեճից ծագած այս միջադեպը դարձավ երեք տարի անց սկսվելիք օկուպացիայի պաշտոնական պատրվակը։", "0e58142a"]},
"OLAYLAR_EK7:1827-06-16:0":{"b": ["Ալժիրի ափի ֆրանսիական շրջափակումը. երեք տարի տևած պաշարում", "d0ba97a5"], "d": ["Հովհարի միջադեպից հետո Ֆրանսիան շրջափակեց Ալժիրի ափը։ Շրջափակումը տևեց երեք տարի. ցամաքեցվեցին օջախի ծովային առևտուրը և եկամտի աղբյուրները, և դիմադրելու ունակությունը խարխլվեց դեռ օկուպացիան սկսվելուց առաջ։", "79d27be2"]},
"OLAYLAR_EK7:1828-06-23:0":{"b": ["Բրաիլայի երկրորդ անկումը. Նիկոլայ ցարը բերդի առջև", "eb6a8741"], "d": ["1812 թ. Օսմանյան պետությանը վերադարձված և 1817-1818 թթ. կրկին ամրացված Բրաիլան, որտեղ կային 4000 պահակազորային և 278 թնդանոթ, ապրիլին պաշարվեց։ Նրա պահապան Էբուբեքիր փաշան ստեղծեց նոր պաշտպանական գիծ. Նիկոլայ I ցարը մայիսի վերջին անձամբ եկավ բերդի առջև։ Քաղաքը ենթարկվեց ռուսական օկուպացիայի, բայց Ադրիանապոլսի պայմանագրով վերադարձվելով՝ թողնվելու էր Վալախիայի իշխանությանը։", "b7e53f03"]},
"OLAYLAR_EK7:1829-06-01:0":{"b": ["Ֆեսի հռչակումը պաշտոնական գլխարկ", "f55be4eb"], "d": ["Մահմուդ II-ը, արմատական փոփոխություն անելով պաշտոնյաների և զինվորների հագուստում, չալմայի փոխարեն ֆեսը հռչակեց պաշտոնական գլխանոց։ Ըստ TDV İslâm Ansiklopedisi-ի «Ֆես» հոդվածի՝ այս որոշումը հայտարարվեց փադիշահի ձեռագիր հրամանով և կիրառվեց Ասաքիր-ի Մանսուրե-ի Մուհամմեդիյեի արևմտյան ոճի բարեփոխումների հետ միասին։ Փոփոխությունը նշանակում էր նաև ավանդական հագուստի աստիճանակարգության վախճանը։", "9739e485"]},
"OLAYLAR_EK7:1829-09-14:0":{"b": ["Ախալցխայի (Ահըսկա) զիջումը Ռուսաստանին. Չըլդըրի էյալեթի կենտրոնը կորսվում է", "e2e00b2a"], "d": ["1578 թ. Չըլդըրի ճակատամարտից ի վեր օսմանյան կառավարման տակ գտնվող և Չըլդըրի էյալեթի կենտրոնը հանդիսացող Ախալցխան 1828-1829 թթ. պատերազմի վերջում կնքված Ադրիանապոլսի պայմանագրով զիջվեց Ռուսաստանին։ Քաղաքի կորուստը ժողովրդի մեջ խոր վիշտ առաջացրեց և դարձավ բազմաթիվ ողբերի թեմա։ Այս իրադարձությամբ Ախալքալաքը, Զազալոն և Ծղալթբիլան (Ախալցխա-Ախալքալաքի շրջան) անցան Ռուսաստանին։", "bab87a04"]},
"OLAYLAR_EK7:1830-06-14:0":{"b": ["Սիդի Ֆերուխի ափհանումը. ֆրանսիական բանակը Ալժիրի հողի վրա", "33327553"], "d": ["Եռամյա շրջափակումից հետո կոմս դը Բուրմոնի հրամանատարությամբ ֆրանսիական ափհանման բանակը զորք իջեցրեց Ալժիրից արևմուտք գտնվող Սիդի Ֆերուխի ծովախորշում։ Դեպի քաղաք առաջացող ուժերը երեք շաբաթում ճեղքեցին պաշտպանական գիծը. հուլիսի 4-ին ընկավ քաղաքի վրա իշխող Կայսերական բերդը, իսկ հաջորդ օրը դեյ Հուսեյնը անձնատուր եղավ։", "0d2a2c9a"]},
"OLAYLAR_EK7:1830-08-09:0":{"b": ["Դեյ Հուսեյնի աքսորը. Ալժիրի օջախի փաստացի վախճանը", "e122403b"], "d": ["Հանձնման պայմանների համաձայն՝ Ալժիրի վերջին դեյ Հուսեյնը, իր ընտանիքով և գանձարանով, հանվեց քաղաքից և ուղարկվեց Նեապոլ։ Այսպիսով, ավարտվեց օջախի կառավարումը, որը 1519 թ. միացել էր Սելիմ I Յավուզին և երեք հարյուր տարի եղել Միջերկրական ծովում օսմանյան ամենահզոր ծովային հենակետը։", "bf7169cf"]},
"OLAYLAR_EK7:1834-01-01:0":{"b": ["Ռուսական բանակի դուրսբերումը Վալախիայից և Մոլդովայից. վեցամյա օկուպացիայի վախճանը", "efdb0275"], "d": ["1828-1829 թթ. ռուս-թուրքական պատերազմում ռուսները օկուպացրել էին Վալախիան և Մոլդովան և Ադրիանապոլսի պայմանագրից հետո էլ չէին դուրս եկել մինչև ռազմատուգանքի վճարումը։ 1834 թ. հունվարին, երբ ռազմատուգանքը իջեցվեց հինգ միլիոնի, ռուսական ուժերը դատարկեցին երկու իշխանությունները (Մեմլեքեթեյն), և երկու իշխանություններում նոր վոյևոդներ նշանակվեցին։ Օսմանյան գերիշխանությունը թղթի վրա վերադարձավ, բայց Ռուսաստանը պահպանեց Reglement Organique-ով հաստատած իր ազդեցությունը։", "312a9319"]},
"OLAYLAR_EK7:1834-07-08:0":{"b": ["Հիմնվեց Ռեդիֆ-ի Ասաքիր-ի Մանսուրե կազմակերպությունը", "15947493"], "d": ["Որպես Ասաքիր-ի Մանսուրե-ի Մուհամմեդիյեին աջակցող պահեստային ուժ՝ Ռեդիֆ կազմակերպությունը հիմնվեց 1834 թ. հուլիսի 8-ի կանոնադրությամբ։ Ըստ TDV İslâm Ansiklopedisi-ի «Ռեդիֆ» հոդվածի՝ սերասքեր Քոջա Հյուսրև փաշայի ղեկավարությամբ գավառական կազաներում կազմվեցին մոտ մեկ հազար չորս հարյուրական հոգանոց գումարտակներ։ Կազմակերպությունը մտահղացվել էր այնպես, որ, մշտական ծառայության մեջ չվերցվելով, աջակցեր նաև տեղական անվտանգությանը։", "ca6cb4a0"]},
"OLAYLAR_EK7:1836-06-01:0":{"b": ["Հիմնվեց Արտաքին գործերի նախարարությունը (Հարիջիյե նեզարեթի)", "750c6c7d"], "d": ["Մահմուդ II-ը, վերացնելով արտաքին գործերը վարող ռեիս ուլ-քյութթաբի պաշտոնը, դրա փոխարեն հիմնեց Արտաքին գործերի նախարարությունը։ Ըստ TDV İslâm Ansiklopedisi-ի «Արտաքին գործերի նախարարություն» հոդվածի՝ նոր նախարարության առաջին նախարար նշանակվեց Մեհմեդ Աքիֆ փաշան, և կազմակերպությունը գործունեությունը սկսեց Վիեննայի դեսպան Ռըֆաթ բեյի ապարանքում։ Այս կարգավորումը դարձավ օսմանյան արտաքին քաղաքականությունը ժամանակակից նախարարական սկզբունքով վարելու սկիզբը։", "50ebd952"]},
"OLAYLAR_EK7:1838-03-24:0":{"b": ["Հիմնվեց Մեջլիս-ի Վալա-ի Ահքյամ-ը Ադլիյեն", "69db056e"], "d": ["Մահմուդ II-ը, որպես պատրաստվելիք օրենքները և կանոնակարգերը քննարկող բարձրագույն խորհուրդ, հիմնել տվեց Մեջլիս-ի Վալա-ի Ահքյամ-ը Ադլիյեն (Արդարադատական վճիռների գերագույն խորհուրդ)։ Ըստ TDV İslâm Ansiklopedisi-ի «Մեջլիս-ի Վալա-ի Ահքյամ-ը Ադլիյե» հոդվածի՝ խորհուրդը փաստացի աշխատանքը սկսեց 1838 թ. մարտի 31-ին, և Թանզիմաթի հետագա բարեփոխումներից գրեթե բոլորը պատրաստվեցին և վերահսկվեցին այս մարմնի միջոցով։ Հաստատությունը դարձավ ժամանակակից օսմանյան բյուրոկրատիայի ամենակարևոր կենտրոններից մեկը։", "9346611a"]},
"OLAYLAR_EK7:1853-11-30:0":{"b": ["Սինոպի հարձակումը", "5947e93f"], "d": ["Ռուսական սևծովյան նավատորմը ծովակալ Նախիմովի հրամանատարությամբ, առանց պատերազմ հայտարարելու, հանկարծակի հարձակվեց Սինոպի նավահանգստում խարիսխ գցած օսմանյան նավատորմի վրա. տասներկու նավ խորտակվեց, ավելի քան երկու հազար զինվոր զոհվեց, իսկ նավատորմի հրամանատար Օսման փաշան գերի ընկավ։ Ըստ TDV İslâm Ansiklopedisi-ի «Սինոպ» հոդվածի՝ հարձակման ժամանակ քաղաքում նույնպես այրվեցին յոթ փոքր մզկիթ, երկու դպրոց, 247 տուն և 170 խանութ, և զոհվեցին հինգ մուսուլման ու տասնվեց քրիստոնյա խաղաղ բնակիչ։ Եվրոպական հասարակական կարծիքում «Սինոպի ողբերգություն» անունով արձագանք գտած դեպքը դարձավ անմիջական դրդիչը այն բանի, որ Անգլիան և Ֆրանսիան մի քանի ամսում պատերազմի մեջ մտան Օսմանյան պետության կողմից։", "89a8c874"]},
"OLAYLAR_EK7:1862-06-27:0":{"b": ["Լույս տեսավ «Թասվիր-ի Էֆքյար»-ը", "506c98e2"], "d": ["Շինասիի հրատարակած «Թասվիր-ի Էֆքյար»-ը («Մտքերի պատկեր»), «Թաքվիմ-ի Վաքայի», «Ջերիդե-ի Հավադիս» և «Թերջուման-ը Ահվալ» թերթերից հետո, որպես չորրորդ թուրքերեն թերթ սկսեց հրատարակվել։ Ըստ TDV-ի «Թասվիր-ի Էֆքյար» հոդվածի՝ թերթը հետագայում նրա գլխավոր խմբագրությունն ստանձնած Նամըք Քեմալի օրոք դարձավ Նոր օսմանների շարժման խոսափողը։", "72568463"]},
"OLAYLAR_EK7:1867-08-30:0":{"b": ["Հիմնվեց Նոր օսմանների ընկերությունը", "335fb02d"], "d": ["Մուստաֆա Ֆազիլ փաշայի նախաձեռնությամբ Եվրոպա փախած օսմանյան մտավորականները կազմակերպվեցին Երիտասարդ Թուրքիա անունով՝ տասներեք հոդվածից բաղկացած կանոնադրությամբ։ Ըստ TDV-ի «Նոր օսմանների ընկերություն» հոդվածի՝ խումբը Փարիզում, Լոնդոնում և Ժնևում «Մուհբիր» և «Հյուրրիյեթ» նման թերթեր հրատարակելով՝ տարածեց սահմանադրական կառավարման պահանջը։", "169dff06"]},
"OLAYLAR_EK7:1868-03-05:0":{"b": ["Հիմնվեց Պետական խորհուրդը (Շյուրա-յը Դևլեթ)", "b863b306"], "d": ["Մեջլիս-ի Ահքյամ-ը Ադլիյեն բաժանվեց երկուսի. հիմնվեցին վարչական գործերը վարող Պետական խորհուրդը (Շյուրա-յը Դևլեթ) և դատական գործերով զբաղվող Դիվան-ը Ահքյամ-ը Ադլիյեն։ Ըստ TDV-ի «Շյուրա-յը Դևլեթ» հոդվածի՝ ֆրանսիական Conseil d'État-ի օրինակով ստեղծված հաստատության առաջին նախագահ նշանակվեց Միդհաթ փաշան. նպատակը օրենսդիր, գործադիր և դատական իշխանությունների տարանջատումն էր։", "6a4ac9ed"]},
"OLAYLAR_EK7:1869-04-08:0":{"b": ["Արձակվեց Դարուլֆյունունի (համալսարանի) հիմնադրման հրամանը", "513704bf"], "d": ["Մեծ վեզիր Ալի փաշայի և կրթության նախարար Սաֆվեթ փաշայի պատրաստած հրամանով (իրադե) Դարուլֆյունունը պաշտոնապես հիմնվեց. իսկ առաջին դասերը սկսվել էին դեռ ավելի վաղ՝ 1863 թ.։ Ըստ TDV-ի «Դարուլֆյունուն» հոդվածի՝ հաստատությունը 1870 թ. փետրվարին Հոջա Թահսին էֆենդիի տնօրինությամբ փաստացի սկսեց ուսուցումը՝ փիլիսոփայության-գրականության, բնական գիտությունների և իրավաբանության բաժիններով։", "884a094b"]},
"OLAYLAR_EK7:1869-06-01:0":{"b": ["Սկսվեցին Մեջելե-ի Ահքյամ-ը Ադլիյեի աշխատանքները", "8abdcbee"], "d": ["Դիվան-ը Ահքյամ-ը Ադլիյեի նախագահ Ահմեդ Ջևդեթ փաշայի նախագահությամբ հիմնված Մեջելեի ընկերությունը ձեռնամուխ եղավ հանաֆիական ֆիկհի վրա հիմնված քաղաքացիական օրենսգրքի պատրաստմանը։ Ըստ TDV-ի «Մեջելե-ի Ահքյամ-ը Ադլիյե» հոդվածի՝ տասնվեց գրքից և 1851 հոդվածից բաղկացած աշխատության վերջին պրակը 1876 թ. սեպտեմբերի 15-ին ավարտվեց և ուժի մեջ մտավ. այն համարվում է իսլամական իրավունքի առաջին օրենսգրքացված ձևը։", "159b40e5"]},
"OLAYLAR_EK7:1873-04-01:0":{"b": ["Բեմադրվեց «Վաթան կամ Սիլիստրա»-ն, Նամըք Քեմալը աքսորվեց", "3861284c"], "d": ["Երբ Նամըք Քեմալի հայրենասիրական թեմայով պիեսը բեմադրվեց Գեդիքփաշայի թատրոնում, հանդիսատեսը «Կեցցե՛ հայրենիքը, կեցցե՛ Քեմալը» գոչելով դուրս թափվեց փողոցներ։ Ըստ TDV-ի «Նամըք Քեմալ» հոդվածի՝ կառավարությունը, վախենալով այս ցույցից, փակեց «Իբրեթ» թերթը և 1873 թ. ապրիլի 6-ին Նամըք Քեմալին առանց դատի աքսորեց Կիպրոս (Ֆամագուստա)։", "b713ac86"]},
"OLAYLAR_EK7:1876-06-04:0":{"b": ["Աբդուլազիզը կասկածելի հանգամանքներում մահացավ", "85816692"], "d": ["Գահընկեց արվելուց հետո իր իսկ ցանկությամբ Ֆերիյե պալատ տեղափոխված (1876 թ. հունիսի 1) Աբդուլազիզը հունիսի 4-ին իր սենյակում գտնվեց՝ դաստակների երակները կտրված վիճակում։ Դեսպանատների բժիշկների մասնակցությամբ տասնինը բժշկից բաղկացած հանձնախումբը կազմեց անորոշ ձևակերպումներով զեկուցագիր. մահը հունիսի 6-ին թերթերում հայտարարվեց որպես ինքնասպանություն։ Աբդուլհամիդ II-ի հանձնարարությամբ կատարված հետաքննությունը եկավ այն եզրակացության, որ մահը ոչ թե ինքնասպանություն, այլ սպանություն էր, և մեղադրյալները 1881 թ. դատվեցին Յըլդըզի դատարանում. հարցը պատմագրության մեջ այսօր էլ վիճելի է։", "a7b39d5c"]},
"OLAYLAR_EK7:1877-02-05:0":{"b": ["Միդհաթ փաշայի պաշտոնանկությունը մեծ վեզիրությունից և աքսորը", "b5247b06"], "d": ["Սահմանադրության (Քանուն-ը Էսասի) ճարտարապետ մեծ վեզիր Միդհաթ փաշան դրա հռչակումից վեց շաբաթ անց Աբդուլհամիդ II-ի կողմից պաշտոնից հեռացվեց և մեկ գիշերվա մեջ աքսորվեց արտասահման։ Ըստ TDV İslâm Ansiklopedisi-ի «Միդհաթ փաշա» հոդվածի՝ պաշտոնանկությունը կապվում է սահմանադրության մեջ փադիշահի իրավասությունները սահմանափակող դրույթներից նրա ունեցած դժգոհության հետ։ Փաշան նախ մեկնել է Նեապոլ, ապա Եվրոպայի տարբեր քաղաքներ։", "88f7d5e3"]},
"OLAYLAR_EK7:1902-01-15:0":{"b": ["Աբդուլազիզ բ. Սաուդը Ռիյադը հետ է գրավում ռաշիդյաններից", "75eb8830"], "d": ["Տասը տարի առաջ Քուվեյթ աքսորված Սաուդյան հարստության երիտասարդ Աբդուլազիզը, փոքր զորախմբով հարձակվելով Ռիյադի վրա և սպանելով Ալ Ռաշիդի (Շամմար) վալիի կայմակամին, գրավեց քաղաքը։ Ըստ TDV İslâm Ansiklopedisi-ի «Ռիյադ» հոդվածի՝ ռաշիդյանների աստիճանական թուլացումը և քաղաքին օգնական ուժեր չկարողանալ ուղարկելը դյուրացրին այս հարձակման հաջողությունը. դեպքը համարվում է Երկրորդ սաուդյան պետության հիմնման պահը, որը հետագա երեսուն տարում կազմելու էր ներկայիս Սաուդյան Արաբիայի միջուկը։", "7e0bf55b"]},
"OLAYLAR_EK7:1909-04-24:0":{"b": ["Գործողության բանակի (Հարեքեթ օրդուսու) մուտքը Ստամբուլ", "41c8304c"], "d": ["Սալոնիկից ճանապարհ ընկած և մեծ մասամբ «Միություն և առաջադիմություն» կոմիտեին հարող զորամասերից բաղկացած Գործողության բանակը մտավ Ստամբուլ՝ մարտի 31-ի ապստամբությունը ճնշելու համար։ Ըստ TDV İslâm Ansiklopedisi-ի «Գործողության բանակ» հոդվածի՝ դրա հրամանատարությունը ստանձնել էր Մահմուդ Շևքեթ փաշան, իսկ շտաբի պետը կոլաղասի (ավագ կապիտան) Մուստաֆա Քեմալն էր։ Կարճ բախումներից հետո քաղաքում կարգուկանոնը վերականգնվեց։", "e47ad17d"]},
"OLAYLAR_EK7:1920-04-11:0":{"b": ["Վերջին օսմանյան Պատգամավորների ժողովի (Մեջլիս-ի Մեբուսան) ցրումը", "2b709269"], "d": ["Անտանտի ուժերի կողմից Ստամբուլի պաշտոնական օկուպացիայից և բազմաթիվ պատգամավորների ձերբակալությունից հետո Պատգամավորների ժողովը դարձավ գործունակությունից զուրկ և Մեհմեդ VI-ի հրամանով պաշտոնապես լուծարվեց։ Ըստ TDV İslâm Ansiklopedisi-ի «Մեջլիս-ի Մեբուսան» հոդվածի՝ այս լուծարումը խորհրդանշեց օսմանյան սահմանադրական խորհրդարանական ավանդույթի փաստացի վախճանը։ Փակումն ուժեղացրեց Անկարայում նոր ազգային ժողով հրավիրելու անհրաժեշտությունը։", "4caabf36"]},
"OLAYLAR_EK7:1920-04-23:0":{"b": ["Թուրքիայի ազգային մեծ ժողովի բացումը", "6eab539d"], "d": ["Ստամբուլի Պատգամավորների ժողովի ցրումից հետո պատգամավորները հավաքվեցին Անկարայում և բացեցին Թուրքիայի ազգային մեծ ժողովը, և Մուստաֆա Քեմալ փաշան ընտրվեց ժողովի նախագահ։ Ըստ TDV İslâm Ansiklopedisi-ի «Թուրքիայի ազգային մեծ ժողով» հոդվածի՝ ժողովն ուներ արտակարգ բնույթ՝ իր մեջ կենտրոնացնելով թե՛ օրենսդիր, թե՛ գործադիր իշխանությունը։ Այս բացումը դարձավ շրջադարձային կետ, երբ ազգային պայքարի քաղաքական և ինստիտուցիոնալ կենտրոնը տեղափոխվեց Անկարա։ Այս իրադարձությամբ 124 բնակավայր (Թուրքիայի չօկուպացված շրջանները), ներառյալ Կոնիան, Սեբաստիան (Սվաս), Կայսերին, Էսքիշեհիրը, Էրզրումը, Տրապիզոնը, Սամսունը, Դիարբեքիրը, Վանը, Մալաթիան, Դենիզլին և Իսպարտան, անցան ԹԱՄԺ կառավարության կառավարման տակ։", "47a80fa7"]},
"OLAYLAR_EK8:1460-01-01:0":{"b": ["Զվորնիկի բերդի գրավումը", "657c465a"], "d": ["Դրինա գետի ափի Զվորնիկի բերդը 1460 թ. գրավվեց Օսմանյան պետության կողմից։ Ըստ TDV İslâm Ansiklopedisi-ի՝ վարչական և ռազմական տեսակետից հարմար դիրքի պատճառով այն նախ դարձավ կազայի կենտրոն, 1480 թ. վերածվեց համանուն սանջակի կենտրոնի, իսկ 1491 թ. քարե պարիսպներով ամրացվելով՝ իր վեց մզկիթով, ութ թեքքեով և բաղնիքներով վերածվեց կարևոր վարչա-առևտրական կենտրոնի։", "160e9a01"]},
"OLAYLAR_EK8:1468-01-01:0":{"b": ["Կասիմ խանի մահը, Դանյալ խանի գահակալումը (Կասիմի խանություն)", "522fd0fd"], "d": ["Խանության հիմնադիր Կասիմ խանի 873/1468 թ. մահով նրան հաջորդեց նրա որդի Դանյալը. Դանյալը իշխեց մինչև 1486 թ.։", "6217828f"]}
});
